INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C1','math',4,2,'u3',2,'소수 두 자리 수 — 1을 똑같이 100으로 나눈 하나를 0.01(영 점 영일)로 알고, 소수 두 자리 수를 0.01의 개수로 세며 읽고 쓰고, 자리마다 나타내는 값을 알기(cm → m)',ARRAY['4수01-13']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C2','math',4,2,'u3',3,'소수 세 자리 수 — 1을 똑같이 1000으로 나눈 하나를 0.001(영 점 영영일)로 알고, 소수 세 자리 수를 0.001의 개수로 세며 읽고 쓰고, 소수 셋째 자리까지의 자릿값을 알기(m → km, g → kg)',ARRAY['4수01-13']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C3','math',4,2,'u3',4,'소수 사이의 관계 — 1·0.1·0.01·0.001이 10배씩 차이 남을 알고, 10배·100배 하면 숫자가 왼쪽으로, 10분의 1·100분의 1 하면 오른쪽으로 한 자리씩 옮겨 감을 알기',ARRAY['4수01-13']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C4','math',4,2,'u3',5,'소수의 크기 비교 — 끝자리에 0을 붙여도 크기가 같음을 알고(0.5 = 0.50), 소수점을 기준으로 자리를 맞추어 큰 자리부터 견주기(수의 길이로 견주지 않기)',ARRAY['4수01-14']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C5','math',4,2,'u3',6,'소수 한 자리 수의 덧셈 — 0.1의 개수로 더하고, 소수점을 맞추어 세로로 써서 받아올림(0.1이 10개 = 1)을 하며 계산하기',ARRAY['4수01-16']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C6','math',4,2,'u3',7,'소수 두 자리 수의 덧셈 — 0.01의 개수로 더하고, 자릿수가 다를 때도 오른쪽 끝이 아니라 소수점을 맞추어 같은 자리끼리 받아올림하며 계산하기',ARRAY['4수01-16']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C7','math',4,2,'u3',8,'소수 한 자리 수의 뺄셈 — 0.1의 개수로 빼고, 소수점을 맞추어 세로로 써서 받아내림(1 = 0.1이 10개)을 하며 계산하기',ARRAY['4수01-16']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C8','math',4,2,'u3',9,'소수 두 자리 수의 뺄셈 — 0.01의 개수로 빼고, 빼지는 수의 자릿수가 적으면 끝자리에 0을 붙여 자리를 맞춘 뒤 받아내림하며 계산하기',ARRAY['4수01-16']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C9','math',4,2,'u3',10,'여러 소수의 덧셈과 기록 견주기 — 여러 기록을 차례로 더해 합을 구하고, 기록이 작을수록 빠름을 알고 두 기록의 차를 뺄셈으로 구하기',ARRAY['4수01-16']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u3-C10','math',4,2,'u3',10,'조건에 맞게 소수 고르기 — 기준과 견주고, 한 사람이 한 가지만 맡는 조건에서 합이 가장 작게 되는 짝을 찾으며, 가장 빠른 것만 고르는 방법이 늘 답이 아님을 알기',ARRAY['4수01-14']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X01','math',4,'u3',ARRAY['M4-2-u3-C1','M4-2-u3-C2','M4-2-u3-C3','M4-2-u3-C5','M4-2-u3-C6','M4-2-u3-C7','M4-2-u3-C8']::text[],'0.1·0.01·0.001을 헷갈려 세는 단위를 잘못 잡는다(0.79 → 0.1이 79개, 작은 눈금 0.01을 0.1로)','한 칸이 얼마인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X02','math',4,'u3',ARRAY['M4-2-u3-C1','M4-2-u3-C2']::text[],'소수점 오른쪽을 자연수처럼 읽는다(0.79 → 영 점 칠십구)','오른쪽은 하나씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X03','math',4,'u3',ARRAY['M4-2-u3-C1','M4-2-u3-C2','M4-2-u3-C4']::text[],'숫자가 놓인 자리의 값을 잘못 안다(2.58에서 5 → 5·0.05)','자리가 값을 정한다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X04','math',4,'u3',ARRAY['M4-2-u3-C1','M4-2-u3-C2']::text[],'단위를 바꿀 때 자리 수를 잘못 잡는다(79 cm → 7.9 m, 57 m → 0.57 km)','1 m = 100 cm · 1 km = 1000 m') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X05','math',4,'u3',ARRAY['M4-2-u3-C3']::text[],'10배·10분의 1을 할 때 숫자가 옮겨 가는 방향을 거꾸로 한다(0.65의 10배 → 0.065)','10배는 왼쪽으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X06','math',4,'u3',ARRAY['M4-2-u3-C3']::text[],'10배와 100배(10분의 1과 100분의 1)를 헷갈려 옮기는 자리 수를 잘못 센다','0 하나에 한 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X07','math',4,'u3',ARRAY['M4-2-u3-C4']::text[],'소수의 자리 수가 많을수록 큰 수라고 본다(0.003 > 0.02)','길이로 견주지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X08','math',4,'u3',ARRAY['M4-2-u3-C4']::text[],'소수점 오른쪽 수를 자연수처럼 견준다(47 > 5라서 0.47 > 0.5)','자리를 맞춰 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X09','math',4,'u3',ARRAY['M4-2-u3-C4','M4-2-u3-C8']::text[],'끝자리에 0을 붙이면 크기가 달라진다고 본다(0.5 ≠ 0.50)','끝자리 0은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X10','math',4,'u3',ARRAY['M4-2-u3-C5']::text[],'같은 자리의 합이 10 이상인데 그 합을 소수점 뒤에 그대로 쓴다(0.9 + 0.7 → 0.16)','0.1이 10개면 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X11','math',4,'u3',ARRAY['M4-2-u3-C5','M4-2-u3-C6','M4-2-u3-C9']::text[],'받아올림한 1을 윗자리에 더하지 않는다(3.8 + 4.9 → 7.7)','받아올림 1 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X12','math',4,'u3',ARRAY['M4-2-u3-C6','M4-2-u3-C8']::text[],'소수점이 아니라 오른쪽 끝을 맞추어 쓰고 계산한다(5.1 + 4.26 → 4.77, 4.23 − 1.6 → 4.07)','소수점을 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X13','math',4,'u3',ARRAY['M4-2-u3-C7','M4-2-u3-C8']::text[],'뺄 수 없는 자리에서 받아내림하지 않고 큰 수에서 작은 수를 거꾸로 뺀다(9.28 − 5.79 → 4.51)','거꾸로 빼지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X14','math',4,'u3',ARRAY['M4-2-u3-C7','M4-2-u3-C8']::text[],'받아내림을 하고도 윗자리에서 1을 빼지 않는다(9.28 − 5.79 → 4.59)','빌려 준 자리 1 줄이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X15','math',4,'u3',ARRAY['M4-2-u3-C8']::text[],'빼지는 수의 빈 자리를 0으로 보지 않고 빼는 수의 숫자를 그대로 내린다(1.2 − 0.36 → 0.96)','빈 자리는 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X16','math',4,'u3',ARRAY['M4-2-u3-C5','M4-2-u3-C6','M4-2-u3-C7','M4-2-u3-C8','M4-2-u3-C9']::text[],'더해야 할 때 빼거나 빼야 할 때 더한다(「모두」·「남은」·「몇 더」를 거꾸로)','모으면 덧셈·덜면 뺄셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X17','math',4,'u3',ARRAY['M4-2-u3-C1','M4-2-u3-C2','M4-2-u3-C3','M4-2-u3-C4','M4-2-u3-C5','M4-2-u3-C6','M4-2-u3-C7','M4-2-u3-C8','M4-2-u3-C9','M4-2-u3-C10']::text[],'묻는 말을 거꾸로 읽는다 — 큰↔작은, 빠른↔느린(기록은 작을수록 빠르다), 큰 수부터↔작은 수부터','물음에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X18','math',4,'u3',ARRAY['M4-2-u3-C4','M4-2-u3-C9','M4-2-u3-C10']::text[],'계산하거나 자리를 맞추면 견줄 수 있는데도 「같다」·「견줄 수 없다」고 한다','자리 맞춰 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X19','math',4,'u3',ARRAY['M4-2-u3-C10']::text[],'영법마다 가장 빠른 선수만 고르면 된다고 보고 「한 사람이 한 가지만」 조건을 놓친다','조건 먼저 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X20','math',4,'u3',ARRAY['M4-2-u3-C1','M4-2-u3-C2','M4-2-u3-C4','M4-2-u3-C10']::text[],'□에 들어갈 수를 셀 때 경계의 수를 넣거나 빼고, 개수를 하나 많거나 적게 센다','하나씩 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u3-X21','math',4,'u3',ARRAY['M4-2-u3-C4']::text[],'부등호(>, <)의 뜻을 거꾸로 알아, 같은 자리 숫자를 바르게 견주고도 큰 수 쪽이 아니라 작은 수 쪽으로 벌어지게 쓴다(0.82 < 0.81 · 5.126 > 5.129)','부등호는 큰 수 쪽으로 벌어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_basic#1','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',1,'match','auto','준비하기 — 분수와 크기가 같은 소수를 찾아 선으로 이어 보세요.','{}'::text[],false,'{"seq":1,"concept":"M4-2-u3-C1","difficulty":1,"kind":"match","stem":"준비하기 — 분수와 크기가 같은 소수를 찾아 선으로 이어 보세요.","pairs":[{"l":"⟨2/10⟩","r":"0.2"},{"l":"⟨8/10⟩","r":"0.8"},{"l":"⟨5/10⟩","r":"0.5"}],"mis":"M4-2-u3-X01","explanation":["⟨1/10⟩ = 0.1이에요.","⟨2/10⟩는 0.1이 2개, ⟨8/10⟩은 0.1이 8개, ⟨5/10⟩는 0.1이 5개예요.","⟨2/10⟩ = 0.2, ⟨8/10⟩ = 0.8, ⟨5/10⟩ = 0.5."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_basic#2','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',1,'mc','auto','준비하기 — 1.6을 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X03']::text[],true,'{"seq":2,"concept":"M4-2-u3-C1","difficulty":1,"kind":"mc","stem":"준비하기 — 1.6을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"일 점 육","correct":true},{"t":"일 점 여섯","mis":"M4-2-u3-X02"},{"t":"일 점 영육","mis":"M4-2-u3-X03"},{"t":"십육","mis":"M4-2-u3-X02"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 일.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","1.6 → 일 점 육."],"variant_rule":{"alt":[{"stem":"준비하기 — 9.8을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"구 점 팔","correct":true},{"t":"구 점 여덟","mis":"M4-2-u3-X02"},{"t":"구 점 영팔","mis":"M4-2-u3-X03"},{"t":"구십팔","mis":"M4-2-u3-X02"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 구.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","9.8 → 구 점 팔."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
