INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_basic#4','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',1,'mc','auto','펭귄의 키를 m 단위로 나타내려고 해요. 1 cm는 몇 m인지 소수로 나타내면 얼마인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":4,"concept":"M4-2-u3-C1","difficulty":1,"kind":"mc","stem":"펭귄의 키를 m 단위로 나타내려고 해요. 1 cm는 몇 m인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.01 m","correct":true},{"t":"0.1 m","mis":"M4-2-u3-X04"},{"t":"0.001 m","mis":"M4-2-u3-X04"},{"t":"100 m","mis":"M4-2-u3-X04"}],"explanation":["100 cm = 1 m, 10 cm = ⟨1/10⟩ m = 0.1 m예요.","1 cm = ⟨1/100⟩ m — ⟨1/100⟩은 소수로 0.01(영 점 영일)이에요.","1 cm = 0.01 m."],"variant_rule":{"alt":[{"stem":"스스로 준비학습 — 19 mm는 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"1.9 cm","correct":true},{"t":"0.19 cm","mis":"M4-2-u3-X04"},{"t":"19 cm","mis":"M4-2-u3-X04"},{"t":"0.019 cm","mis":"M4-2-u3-X04"}],"explanation":["10 mm = 1 cm이므로 1 mm = 0.1 cm예요.","19 mm는 0.1 cm가 19개예요.","19 mm = 1.9 cm예요."]},{"stem":"스스로 준비학습 — 23 mm는 몇 cm인지 소수로 나타내면 얼마인가요?","options":[{"t":"2.3 cm","correct":true},{"t":"0.23 cm","mis":"M4-2-u3-X04"},{"t":"23 cm","mis":"M4-2-u3-X04"},{"t":"0.023 cm","mis":"M4-2-u3-X04"}],"explanation":["10 mm = 1 cm이므로 1 mm = 0.1 cm예요.","23 mm는 0.1 cm가 23개예요.","23 mm = 2.3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
