INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_basic#9','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',2,'mc','auto','3.3과 3.4 사이가 똑같이 10칸으로 나누어진 수직선이에요. 3.3에서 오른쪽으로 작은 눈금 9칸을 더 간 곳의 소수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X20']::text[],true,'{"seq":9,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"3.3과 3.4 사이가 똑같이 10칸으로 나누어진 수직선이에요. 3.3에서 오른쪽으로 작은 눈금 9칸을 더 간 곳의 소수는 얼마인가요?","options":[{"t":"3.39","correct":true},{"t":"3.9","mis":"M4-2-u3-X01"},{"t":"3.309","mis":"M4-2-u3-X01"},{"t":"3.38","mis":"M4-2-u3-X20"}],"explanation":["3.3과 3.4 사이가 10칸이므로 작은 눈금 한 칸은 0.01이에요.","3.3에서 0.01씩 9칸 — 3.39예요.","답은 3.39(삼 점 삼구)예요."],"asset":{"type":"number_line","cells":["3.3","3.31","…","?","3.4"]},"variant_rule":{"alt":[{"stem":"3.4와 3.5 사이가 똑같이 10칸으로 나누어진 수직선이에요. 3.4에서 오른쪽으로 작은 눈금 4칸을 더 간 곳의 소수는 얼마인가요?","options":[{"t":"3.44","correct":true},{"t":"3.8","mis":"M4-2-u3-X01"},{"t":"3.404","mis":"M4-2-u3-X01"},{"t":"3.43","mis":"M4-2-u3-X20"}],"explanation":["작은 눈금 한 칸은 0.01 — 0.1로 보면 3.8이 되어 틀려요.","3.4에서 0.01씩 4칸 — 3.44예요.","답은 3.44(삼 점 사사)예요."],"asset":{"type":"number_line","cells":["3.4","…","?","…","3.5"]}},{"stem":"4.5와 4.6 사이가 똑같이 10칸으로 나누어진 수직선이에요. 4.5에서 오른쪽으로 작은 눈금 3칸을 더 간 곳의 소수는 얼마인가요?","options":[{"t":"4.53","correct":true},{"t":"4.8","mis":"M4-2-u3-X01"},{"t":"4.503","mis":"M4-2-u3-X01"},{"t":"4.52","mis":"M4-2-u3-X20"}],"explanation":["작은 눈금 한 칸은 0.01이에요.","4.5에서 0.01씩 3칸 — 4.53이에요.","답은 4.53(사 점 오삼)이에요."],"asset":{"type":"number_line","cells":["4.5","…","?","…","4.6"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_basic#10','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_basic','lesson_basic','M4-2-u3-C1',3,'mc','auto','숫자 9가 나타내는 수가 0.09인 것은 어느 것인가요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":10,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"숫자 9가 나타내는 수가 0.09인 것은 어느 것인가요?","options":[{"t":"3.19","correct":true},{"t":"9.12","mis":"M4-2-u3-X03"},{"t":"1.92","mis":"M4-2-u3-X03"},{"t":"9.86","mis":"M4-2-u3-X03"}],"explanation":["0.09는 소수 둘째 자리의 9가 나타내는 값이에요.","9.12의 9는 9, 1.92의 9는 0.9, 9.86의 9는 9를 나타내요.","3.19 — 9가 소수 둘째 자리에 있어 0.09를 나타내요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 숫자 9가 나타내는 수가 0.09인 것은 어느 것인가요?","options":[{"t":"2.09","correct":true},{"t":"5.94","mis":"M4-2-u3-X03"},{"t":"9.12","mis":"M4-2-u3-X03"},{"t":"1.92","mis":"M4-2-u3-X03"}],"explanation":["0.09는 소수 둘째 자리의 9가 나타내는 값이에요.","5.94의 9는 0.9, 9.12의 9는 9, 1.92의 9는 0.9예요.","2.09 — 9가 소수 둘째 자리에 있어 0.09를 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#1','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',2,'mc','auto','1이 2개, 0.1이 7개, 0.01이 4개인 수는 얼마인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X01']::text[],true,'{"seq":1,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"1이 2개, 0.1이 7개, 0.01이 4개인 수는 얼마인가요?","options":[{"t":"2.74","correct":true},{"t":"2.47","mis":"M4-2-u3-X03"},{"t":"27.4","mis":"M4-2-u3-X03"},{"t":"0.274","mis":"M4-2-u3-X01"}],"explanation":["자리마다 숫자를 차례로 써요 — 일의 자리 2, 소수 첫째 자리 7, 소수 둘째 자리 4.","2 + 0.7 + 0.04 = 2.74.","1이 2개, 0.1이 7개, 0.01이 4개인 수는 2.74예요."],"variant_rule":{"alt":[{"stem":"1이 3개, 0.1이 2개, 0.01이 9개인 수는 얼마인가요?","options":[{"t":"3.29","correct":true},{"t":"3.92","mis":"M4-2-u3-X03"},{"t":"32.9","mis":"M4-2-u3-X03"},{"t":"0.329","mis":"M4-2-u3-X01"}],"explanation":["자리마다 숫자를 차례로 써요 — 일의 자리 3, 소수 첫째 자리 2, 소수 둘째 자리 9.","3 + 0.2 + 0.09 = 3.29.","1이 3개, 0.1이 2개, 0.01이 9개인 수는 3.29예요."]},{"stem":"1이 1개, 0.1이 1개, 0.01이 4개인 수는 얼마인가요?","options":[{"t":"1.14","correct":true},{"t":"1.41","mis":"M4-2-u3-X03"},{"t":"11.4","mis":"M4-2-u3-X03"},{"t":"0.114","mis":"M4-2-u3-X01"}],"explanation":["자리마다 숫자를 차례로 써요 — 일의 자리 1, 소수 첫째 자리 1, 소수 둘째 자리 4.","1 + 0.1 + 0.04 = 1.14.","1이 1개, 0.1이 1개, 0.01이 4개인 수는 1.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#2','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',2,'mc','auto','0.01이 861개인 수는 얼마인가요?',ARRAY['M4-2-u3-X01']::text[],true,'{"seq":2,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"0.01이 861개인 수는 얼마인가요?","options":[{"t":"8.61","correct":true},{"t":"86.1","mis":"M4-2-u3-X01"},{"t":"0.861","mis":"M4-2-u3-X01"},{"t":"861","mis":"M4-2-u3-X01"}],"explanation":["0.01이 100개이면 1이에요.","0.01이 861개 = 1이 8개, 0.01이 61개예요.","0.01이 861개인 수는 8.61이에요."],"variant_rule":{"alt":[{"stem":"0.01이 548개인 수는 얼마인가요?","options":[{"t":"5.48","correct":true},{"t":"54.8","mis":"M4-2-u3-X01"},{"t":"0.548","mis":"M4-2-u3-X01"},{"t":"548","mis":"M4-2-u3-X01"}],"explanation":["0.01이 100개이면 1이에요.","0.01이 548개 = 1이 5개, 0.01이 48개예요.","0.01이 548개인 수는 5.48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#3','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'mc','auto','2.58을 설명한 것이에요. 바르게 설명하지 않은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17']::text[],false,'{"seq":3,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"2.58을 설명한 것이에요. 바르게 설명하지 않은 것은 어느 것인가요?","options":[{"t":"0.01이 58개인 수예요","correct":true},{"t":"1이 2개, 0.1이 5개, 0.01이 8개인 수예요","mis":"M4-2-u3-X17"},{"t":"2 + 0.5 + 0.08이에요","mis":"M4-2-u3-X17"},{"t":"1이 2개, 0.01이 58개인 수예요","mis":"M4-2-u3-X17"}],"explanation":["2.58 = 2 + 0.5 + 0.08 — 0.01이 258개인 수예요.","1이 2개, 0.01이 58개인 수라고 해도 맞아요.","자연수 부분 2를 빼고 0.01이 58개라고 하면 0.58이 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#4','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'match','auto','전체 크기가 1인 모눈종이에 색칠한 수를 바르게 읽은 것끼리 선으로 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u3-C1","difficulty":3,"kind":"match","stem":"전체 크기가 1인 모눈종이에 색칠한 수를 바르게 읽은 것끼리 선으로 이어 보세요.","pairs":[{"l":"0.18","r":"영 점 일팔"},{"l":"0.67","r":"영 점 육칠"},{"l":"1.32","r":"일 점 삼이"}],"mis":"M4-2-u3-X02","explanation":["소수점 오른쪽은 숫자를 하나씩 읽어요.","0.18 → 영 점 일팔, 0.67 → 영 점 육칠.","1.32 → 일 점 삼이(일 점 삼십이가 아니에요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#5','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'mc','auto','생활 속에서 소수 두 자리 수를 찾았어요. 음료수 갑에 1.89 L라고 쓰여 있어요. 1.89에서 숫자 8이 나타내는 값은 얼마인가요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":5,"concept":"M4-2-u3-C1","difficulty":3,"kind":"mc","stem":"생활 속에서 소수 두 자리 수를 찾았어요. 음료수 갑에 1.89 L라고 쓰여 있어요. 1.89에서 숫자 8이 나타내는 값은 얼마인가요?","options":[{"t":"0.8 L","correct":true},{"t":"8 L","mis":"M4-2-u3-X03"},{"t":"0.08 L","mis":"M4-2-u3-X03"},{"t":"80 L","mis":"M4-2-u3-X03"}],"explanation":["8은 소수 첫째 자리 숫자예요.","소수 첫째 자리 숫자 1은 0.1 — 8은 0.1이 8개예요.","8은 0.8 L를 나타내요."],"variant_rule":{"alt":[{"stem":"생활 속에서 소수 두 자리 수를 찾았어요. 저울에 4.86 g이라고 나와 있어요. 4.86에서 숫자 6이 나타내는 값은 얼마인가요?","options":[{"t":"0.06 g","correct":true},{"t":"0.6 g","mis":"M4-2-u3-X03"},{"t":"6 g","mis":"M4-2-u3-X03"},{"t":"60 g","mis":"M4-2-u3-X03"}],"explanation":["6은 소수 둘째 자리 숫자예요.","소수 둘째 자리 숫자 1은 0.01 — 6은 0.01이 6개예요.","6은 0.06 g을 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#6','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'sa','auto','불국사의 석가탑 높이는 10.75 m예요. 10.75는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u3-C1","difficulty":3,"kind":"sa","stem":"불국사의 석가탑 높이는 10.75 m예요. 10.75는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["1075"],"explanation":["1은 0.01이 100개 — 10은 0.01이 1000개예요.","0.75는 0.01이 75개예요.","1000 + 75 = 1075 — 0.01이 1075개예요."],"variant_rule":{"alt":[{"stem":"불국사의 다보탑 높이는 10.29 m예요. 10.29는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["1029"],"explanation":["1은 0.01이 100개 — 10은 0.01이 1000개예요.","0.29는 0.01이 29개예요.","1000 + 29 = 1029 — 0.01이 1029개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#7','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',3,'ox','auto','친구가 「79 cm는 7.9 m예요.」라고 했어요. 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M4-2-u3-X04']::text[],false,'{"seq":7,"concept":"M4-2-u3-C1","difficulty":3,"kind":"ox","stem":"친구가 「79 cm는 7.9 m예요.」라고 했어요. 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"1 cm = 0.01 m이므로 79 cm는 0.01 m가 79개인 0.79 m예요","correct":true},{"t":"79를 10으로 나누면 되니 7.9 m가 맞아요","mis":"M4-2-u3-X04"}],"mis":"M4-2-u3-X04","explanation":["1 m = 100 cm예요.","1 cm = 0.01 m — 79 cm는 0.01 m가 79개예요.","79 cm = 0.79 m — 7.9 m는 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#8','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',4,'essay','teacher','단원 도입 — 「지난달 0.63 kg이었던 다람쥐의 몸무게가 …」 0.63이 어떤 수인지 0.1과 0.01을 써서 설명하고, 소수 한 자리 수만으로는 이 몸무게를 나타낼 수 없는 까닭을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C1","difficulty":4,"kind":"essay","stem":"단원 도입 — 「지난달 0.63 kg이었던 다람쥐의 몸무게가 …」 0.63이 어떤 수인지 0.1과 0.01을 써서 설명하고, 소수 한 자리 수만으로는 이 몸무게를 나타낼 수 없는 까닭을 써 보세요.","answer_guide":{"answer":"예: 0.63은 0.1이 6개, 0.01이 3개인 수(0.01이 63개인 수)이다. 소수 한 자리 수로는 0.6이나 0.7처럼 0.1 단위까지만 나타낼 수 있는데, 0.63은 0.6과 0.7 사이에 있어 0.01 단위가 있어야 정확하게 나타낼 수 있다.","scoring_points":["0.1이 6개·0.01이 3개(0.01이 63개)라고 썼는가","0.63이 0.6과 0.7 사이의 수임을 썼는가","소수 둘째 자리(0.01)가 필요하다는 까닭을 썼는가"]},"explanation":["0.63 = 0.6 + 0.03이에요.","0.6과 0.7 사이를 다시 10칸으로 나누어야 0.63을 나타낼 수 있어요.","그래서 소수 한 자리 수보다 작은 수가 필요해요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]],"hi":true},{"p":[[5,0],[6,0],[6,1],[5,1]],"hi":true},{"p":[[6,0],[7,0],[7,1],[6,1]],"hi":true},{"p":[[7,0],[8,0],[8,1],[7,1]],"hi":true},{"p":[[8,0],[9,0],[9,1],[8,1]],"hi":true},{"p":[[9,0],[10,0],[10,1],[9,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2,1],[3,1],[3,2],[2,2]],"hi":true},{"p":[[3,1],[4,1],[4,2],[3,2]],"hi":true},{"p":[[4,1],[5,1],[5,2],[4,2]],"hi":true},{"p":[[5,1],[6,1],[6,2],[5,2]],"hi":true},{"p":[[6,1],[7,1],[7,2],[6,2]],"hi":true},{"p":[[7,1],[8,1],[8,2],[7,2]],"hi":true},{"p":[[8,1],[9,1],[9,2],[8,2]],"hi":true},{"p":[[9,1],[10,1],[10,2],[9,2]],"hi":true},{"p":[[0,2],[1,2],[1,3],[0,3]],"hi":true},{"p":[[1,2],[2,2],[2,3],[1,3]]