INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#9','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',4,'essay','teacher','2.58을 여러 가지 방법으로 설명해 보세요(세 가지 이상).','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C1","difficulty":4,"kind":"essay","stem":"2.58을 여러 가지 방법으로 설명해 보세요(세 가지 이상).","answer_guide":{"answer":"예: 2.58은 2 + 0.5 + 0.08이다. 1이 2개, 0.1이 5개, 0.01이 8개인 수이다. 0.01이 258개인 수이다. 1이 2개, 0.01이 58개인 수이다. 2는 일의 자리 숫자로 2, 5는 소수 첫째 자리 숫자로 0.5, 8은 소수 둘째 자리 숫자로 0.08을 나타낸다.","scoring_points":["자릿값으로 나누어(2 + 0.5 + 0.08) 설명했는가","0.01이 258개인 수라고 설명했는가","세 가지 이상 바르게 썼는가"]},"explanation":["2.58 = 2 + 0.5 + 0.08이에요.","0.01이 258개 — 1이 2개, 0.01이 58개라고 해도 같아요.","같은 수를 자릿값으로 여러 가지로 말할 수 있어요."],"asset":{"type":"expr_grid","rows":[["","일의 자리","소수 첫째 자리","소수 둘째 자리"],["2.58","2","5","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L02_challenge#10','math',4,2,'u3','L02','tb_g4_2_math_u3_L02_challenge','lesson_challenge','M4-2-u3-C1',4,'essay','teacher','3.3과 3.4 사이가 똑같이 10칸으로 나누어진 수직선에서 친구가 3.3에서 작은 눈금 9칸 간 곳을 「3.3」, 3.4에서 작은 눈금 4칸 간 곳을 「3.8」이라고 읽었어요. 무엇을 잘못했는지 쓰고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C1","difficulty":4,"kind":"essay","stem":"3.3과 3.4 사이가 똑같이 10칸으로 나누어진 수직선에서 친구가 3.3에서 작은 눈금 9칸 간 곳을 「3.3」, 3.4에서 작은 눈금 4칸 간 곳을 「3.8」이라고 읽었어요. 무엇을 잘못했는지 쓰고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 작은 눈금 한 칸을 0.1로 보았다. 3.3과 3.4 사이가 10칸이므로 작은 눈금 한 칸은 0.01이다. 3.3에서 9칸 간 곳은 3.39(삼 점 삼구), 3.4에서 4칸 간 곳은 3.44(삼 점 사사)이다.","scoring_points":["작은 눈금 한 칸이 0.01임을 썼는가","3.39를 바르게 썼는가","3.44를 바르게 썼는가"]},"explanation":["큰 눈금 한 칸은 0.1, 작은 눈금 한 칸은 0.01이에요.","3.3 + 0.09 = 3.39예요.","3.4 + 0.04 = 3.44예요."],"asset":{"type":"number_line","cells":["3.3","…","3.4","…","3.5"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#1','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',1,'sa','auto','훈련사가 안내견과 훈련한 거리는 814 m예요. 814 m = ⟨814/1000⟩ km — ⟨814/1000⟩는 ⟨1/1000⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u3-C2","difficulty":1,"kind":"sa","stem":"훈련사가 안내견과 훈련한 거리는 814 m예요. 814 m = ⟨814/1000⟩ km — ⟨814/1000⟩는 ⟨1/1000⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["814"],"explanation":["1 m = ⟨1/1000⟩ km예요.","814 m는 ⟨1/1000⟩ km가 814개예요.","⟨814/1000⟩는 ⟨1/1000⟩이 814개예요."],"variant_rule":{"alt":[{"stem":"훈련사가 안내견과 훈련한 거리는 965 m예요. 965 m = ⟨965/1000⟩ km — ⟨965/1000⟩는 ⟨1/1000⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["965"],"explanation":["1 m = ⟨1/1000⟩ km예요.","965 m는 ⟨1/1000⟩ km가 965개예요.","⟨965/1000⟩는 ⟨1/1000⟩이 965개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#2','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',1,'mc','auto','훈련한 거리를 km 단위로 나타내려고 해요. 1 m는 몇 km인지 소수로 나타내면 얼마인가요?',ARRAY['M4-2-u3-X04']::text[],false,'{"seq":2,"concept":"M4-2-u3-C2","difficulty":1,"kind":"mc","stem":"훈련한 거리를 km 단위로 나타내려고 해요. 1 m는 몇 km인지 소수로 나타내면 얼마인가요?","options":[{"t":"0.001 km","correct":true},{"t":"0.01 km","mis":"M4-2-u3-X04"},{"t":"0.1 km","mis":"M4-2-u3-X04"},{"t":"1000 km","mis":"M4-2-u3-X04"}],"explanation":["1000 m = 1 km, 100 m = 0.1 km, 10 m = 0.01 km예요.","1 m = ⟨1/1000⟩ km — ⟨1/1000⟩은 소수로 0.001(영 점 영영일)이에요.","1 m = 0.001 km."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#3','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',1,'mc','auto','훈련한 거리 814 m는 몇 km인가요?',ARRAY['M4-2-u3-X04']::text[],true,'{"seq":3,"concept":"M4-2-u3-C2","difficulty":1,"kind":"mc","stem":"훈련한 거리 814 m는 몇 km인가요?","options":[{"t":"0.814 km","correct":true},{"t":"81.4 km","mis":"M4-2-u3-X04"},{"t":"8.14 km","mis":"M4-2-u3-X04"},{"t":"814 km","mis":"M4-2-u3-X04"}],"explanation":["1 km = 1000 m이므로 1 m = 0.001 km예요.","814 m는 0.001 km가 814개예요.","814 m = 0.814 km예요."],"variant_rule":{"alt":[{"stem":"훈련한 거리 965 m는 몇 km인가요?","options":[{"t":"0.965 km","correct":true},{"t":"96.5 km","mis":"M4-2-u3-X04"},{"t":"9.65 km","mis":"M4-2-u3-X04"},{"t":"965 km","mis":"M4-2-u3-X04"}],"explanation":["1 km = 1000 m이므로 1 m = 0.001 km예요.","965 m는 0.001 km가 965개예요.","965 m = 0.965 km예요."]},{"stem":"수박의 무게가 8459 g이에요. 수박의 무게는 몇 kg인가요?","options":[{"t":"8.459 kg","correct":true},{"t":"845.9 kg","mis":"M4-2-u3-X04"},{"t":"84.59 kg","mis":"M4-2-u3-X04"},{"t":"8459 kg","mis":"M4-2-u3-X04"}],"explanation":["1 kg = 1000 g이므로 1 g = 0.001 kg이에요.","8459 g은 0.001 kg이 8459개예요.","8459 g = 8.459 kg이에요."]},{"stem":"계량컵에 물이 225 mL 들어 있어요. 물의 양은 몇 L인가요?","options":[{"t":"0.225 L","correct":true},{"t":"22.5 L","mis":"M4-2-u3-X04"},{"t":"2.25 L","mis":"M4-2-u3-X04"},{"t":"225 L","mis":"M4-2-u3-X04"}],"explanation":["1 L = 1000 mL이므로 1 mL = 0.001 L예요.","225 mL는 0.001 L가 225개예요.","225 mL = 0.225 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#4','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',1,'mc','auto','0.814를 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X03']::text[],true,'{"seq":4,"concept":"M4-2-u3-C2","difficulty":1,"kind":"mc","stem":"0.814를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"영 점 팔일사","correct":true},{"t":"영 점 팔백십사","mis":"M4-2-u3-X02"},{"t":"영 점 영팔일사","mis":"M4-2-u3-X03"},{"t":"팔 점 일사","mis":"M4-2-u3-X03"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 영.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","0.814 → 영 점 팔일사."],"variant_rule":{"alt":[{"stem":"1.643을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"일 점 육사삼","correct":true},{"t":"일 점 육백사십삼","mis":"M4-2-u3-X02"},{"t":"일 점 영육사삼","mis":"M4-2-u3-X03"},{"t":"십육 점 사삼","mis":"M4-2-u3-X03"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 일.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","1.643 → 일 점 육사삼."]},{"stem":"0.147을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"영 점 일사칠","correct":true},{"t":"영 점 백사십칠","mis":"M4-2-u3-X02"},{"t":"영 점 영일사칠","mis":"M4-2-u3-X03"},{"t":"일 점 사칠","mis":"M4-2-u3-X03"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 영.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","0.147 → 영 점 일사칠."]},{"stem":"3.539를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"삼 점 오삼구","correct":true},{"t":"삼 점 오백삼십구","mis":"M4-2-u3-X02"},{"t":"삼 점 영오삼구","mis":"M4-2-u3-X03"},{"t":"삼십오 점 삼구","mis":"M4-2-u3-X03"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 삼.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","3.539 → 삼 점 오삼구."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#5','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'mc','auto','1⟨643/1000⟩을 소수로 나타내면 얼마인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X01']::text[],true,'{"seq":5,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"1⟨643/1000⟩을 소수로 나타내면 얼마인가요?","options":[{"t":"1.643","correct":true},{"t":"16.43","mis":"M4-2-u3-X03"},{"t":"0.643","mis":"M4-2-u3-X03"},{"t":"1643","mis":"M4-2-u3-X01"}],"explanation":["자연수 1은 그대로 쓰고 ⟨643/1000⟩은 소수로 0.643이에요.","1과 0.643 — 1.643(일 점 육사삼)이에요.","1⟨643/1000⟩ = 1.643 = 1 + 0.6 + 0.04 + 0.003."],"variant_rule":{"alt":[{"stem":"3⟨539/1000⟩를 소수로 나타내면 얼마인가요?","options":[{"t":"3.539","correct":true},{"t":"35.39","mis":"M4-2-u3-X03"},{"t":"0.539","mis":"M4-2-u3-X03"},{"t":"3539","mis":"M4-2-u3-X01"}],"explanation":["자연수 3은 그대로 쓰고 ⟨539/1000⟩는 소수로 0.539예요.","3과 0.539 — 3.539(삼 점 오삼구)예요.","3⟨539/1000⟩ = 3.539."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#6','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'mc','auto','4.275에서 숫자 5가 나타내는 값은 얼마인가요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":6,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"4.275에서 숫자 5가 나타내는 값은 얼마인가요?","options":[{"t":"0.005","correct":true},{"t":"0.05","mis":"M4-2-u3-X03"},{"t":"0.5","mis":"M4-2-u3-X03"}],"explanation":["5는 소수 셋째 자리 숫자예요.","소수 셋째 자리 숫자 1은 0.001 — 5는 0.001이 5개예요.","5는 0.005를 나타내요."],"variant_rule":{"alt":[{"stem":"4.275에서 숫자 7이 나타내는 값은 얼마인가요?","options":[{"t":"0.07","correct":true},{"t":"0.7","mis":"M4-2-u3-X03"},{"t":"0.007","mis":"M4-2-u3-X03"},{"t":"7","mis":"M4-2-u3-X03"}],"explanation":["7은 소수 둘째 자리 숫자예요.","소수 둘째 자리 숫자 1은 0.01 — 7은 0.01이 7개예요.","7은 0.07을 나타내요."]},{"stem":"1.643에서 숫자 4가 나타내는 값은 얼마인가요?","options":[{"t":"0.04","correct":true},{"t":"0.4","mis":"M4-2-u3-X03"},{"t":"0.004","mis":"M4-2-u3-X03"},{"t":"4","mis":"M4-2-u3-X03"}],"explanation":["4는 소수 둘째 자리 숫자예요.","소수 둘째 자리 숫자 1은 0.01 — 4는 0.01이 4개예요.","4는 0.04를 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
