INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#8','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'mc','auto','2.51과 2.52 사이가 똑같이 10칸으로 나누어진 수직선이에요. 2.51에서 오른쪽으로 작은 눈금 9칸을 더 간 곳의 소수는 얼마인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X20']::text[],true,'{"seq":8,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"2.51과 2.52 사이가 똑같이 10칸으로 나누어진 수직선이에요. 2.51에서 오른쪽으로 작은 눈금 9칸을 더 간 곳의 소수는 얼마인가요?","options":[{"t":"2.519","correct":true},{"t":"2.6","mis":"M4-2-u3-X01"},{"t":"2.518","mis":"M4-2-u3-X20"},{"t":"2.529","mis":"M4-2-u3-X01"}],"explanation":["2.51과 2.52 사이가 10칸이므로 작은 눈금 한 칸은 0.001이에요.","2.51에서 0.001씩 9칸 — 2.519예요.","답은 2.519(이 점 오일구)예요."],"asset":{"type":"number_line","cells":["2.51","2.511","…","?","2.52"]},"variant_rule":{"alt":[{"stem":"2.52와 2.53 사이가 똑같이 10칸으로 나누어진 수직선이에요. 2.52에서 오른쪽으로 작은 눈금 3칸을 더 간 곳의 소수는 얼마인가요?","options":[{"t":"2.523","correct":true},{"t":"2.55","mis":"M4-2-u3-X01"},{"t":"2.524","mis":"M4-2-u3-X20"},{"t":"2.53","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸은 0.001이에요.","2.52에서 0.001씩 3칸 — 2.523이에요.","답은 2.523(이 점 오이삼)이에요."],"asset":{"type":"number_line","cells":["2.52","…","?","…","2.53"]}},{"stem":"6.23과 6.24 사이가 똑같이 10칸으로 나누어진 수직선이에요. 6.23에서 오른쪽으로 작은 눈금 7칸을 더 간 곳의 소수는 얼마인가요?","options":[{"t":"6.237","correct":true},{"t":"6.3","mis":"M4-2-u3-X01"},{"t":"6.236","mis":"M4-2-u3-X20"},{"t":"6.247","mis":"M4-2-u3-X01"}],"explanation":["작은 눈금 한 칸은 0.001이에요.","6.23에서 0.001씩 7칸 — 6.237이에요.","답은 6.237(육 점 이삼칠)이에요."],"asset":{"type":"number_line","cells":["6.23","…","?","…","6.24"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#9','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',2,'mc','auto','1이 2개, 0.1이 8개, 0.01이 5개, 0.001이 3개인 수는 얼마인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X01']::text[],true,'{"seq":9,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"1이 2개, 0.1이 8개, 0.01이 5개, 0.001이 3개인 수는 얼마인가요?","options":[{"t":"2.853","correct":true},{"t":"2.358","mis":"M4-2-u3-X03"},{"t":"28.53","mis":"M4-2-u3-X03"},{"t":"2853","mis":"M4-2-u3-X01"}],"explanation":["자리마다 숫자를 차례로 써요 — 일의 자리 2, 소수 첫째 자리 8, 소수 둘째 자리 5, 소수 셋째 자리 3.","2 + 0.8 + 0.05 + 0.003 = 2.853.","1이 2개, 0.1이 8개, 0.01이 5개, 0.001이 3개인 수는 2.853이에요."],"variant_rule":{"alt":[{"stem":"1이 1개, 0.1이 6개, 0.01이 4개, 0.001이 3개인 수는 얼마인가요?","options":[{"t":"1.643","correct":true},{"t":"1.346","mis":"M4-2-u3-X03"},{"t":"16.43","mis":"M4-2-u3-X03"},{"t":"1643","mis":"M4-2-u3-X01"}],"explanation":["자리마다 숫자를 차례로 써요 — 일의 자리 1, 소수 첫째 자리 6, 소수 둘째 자리 4, 소수 셋째 자리 3.","1 + 0.6 + 0.04 + 0.003 = 1.643.","1이 1개, 0.1이 6개, 0.01이 4개, 0.001이 3개인 수는 1.643이에요."]},{"stem":"0.001이 7354개인 수는 얼마인가요?","options":[{"t":"7.354","correct":true},{"t":"73.54","mis":"M4-2-u3-X01"},{"t":"735.4","mis":"M4-2-u3-X01"},{"t":"7354","mis":"M4-2-u3-X01"}],"explanation":["0.001이 1000개이면 1이에요.","0.001이 7354개 = 1이 7개, 0.001이 354개예요.","0.001이 7354개인 수는 7.354예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_basic#10','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_basic','lesson_basic','M4-2-u3-C2',3,'mc','auto','㉠ 7.159, ㉡ 9.073, ㉢ 1.987에서 숫자 7이 나타내는 수가 가장 작은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X03']::text[],false,'{"seq":10,"concept":"M4-2-u3-C2","difficulty":3,"kind":"mc","stem":"㉠ 7.159, ㉡ 9.073, ㉢ 1.987에서 숫자 7이 나타내는 수가 가장 작은 것은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M4-2-u3-X17"},{"t":"㉡","mis":"M4-2-u3-X03"},{"t":"셋 다 같아요","mis":"M4-2-u3-X03"}],"explanation":["㉠의 7은 7, ㉡의 7은 0.07, ㉢의 7은 0.007을 나타내요.","같은 숫자라도 놓인 자리에 따라 값이 달라요.","가장 작은 것은 ㉢ — 작은 것부터 ㉢, ㉡, ㉠이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#1','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',2,'mc','auto','소수 셋째 자리 숫자가 5인 수는 어느 것인가요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":1,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"소수 셋째 자리 숫자가 5인 수는 어느 것인가요?","options":[{"t":"3.015","correct":true},{"t":"5.417","mis":"M4-2-u3-X03"},{"t":"1.453","mis":"M4-2-u3-X03"},{"t":"7.526","mis":"M4-2-u3-X03"}],"explanation":["소수점 오른쪽 세 번째 자리가 소수 셋째 자리예요.","5.417은 일의 자리, 1.453은 소수 둘째 자리, 7.526은 소수 첫째 자리에 5가 있어요.","3.015 — 소수 셋째 자리 숫자가 5예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 소수 셋째 자리 숫자가 5인 수는 어느 것인가요?","options":[{"t":"0.605","correct":true},{"t":"15.082","mis":"M4-2-u3-X03"},{"t":"5.417","mis":"M4-2-u3-X03"},{"t":"7.526","mis":"M4-2-u3-X03"}],"explanation":["소수점 오른쪽 세 번째 자리가 소수 셋째 자리예요.","15.082는 일의 자리, 5.417은 일의 자리, 7.526은 소수 첫째 자리에 5가 있어요.","0.605 — 소수 셋째 자리 숫자가 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#2','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',2,'ox','auto','「1.643은 0.001이 1643개인 수예요.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M4-2-u3-X01']::text[],false,'{"seq":2,"concept":"M4-2-u3-C2","difficulty":2,"kind":"ox","stem":"「1.643은 0.001이 1643개인 수예요.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"O","reason_options":[{"t":"1은 0.001이 1000개, 0.643은 0.001이 643개이므로 모두 1643개예요","correct":true},{"t":"0.643만 세어 0.001이 643개인 수예요","mis":"M4-2-u3-X01"}],"mis":"M4-2-u3-X01","explanation":["1 = 0.001이 1000개예요.","0.643 = 0.001이 643개예요.","1000 + 643 = 1643 — 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#3','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'error','auto','6.703에 대한 설명이에요. 잘못된 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X17']::text[],false,'{"seq":3,"concept":"M4-2-u3-C2","difficulty":3,"kind":"error","stem":"6.703에 대한 설명이에요. 잘못된 것은 어느 것인가요?","options":[{"t":"㉠ 육 점 칠삼이라고 읽어요","correct":true,"mis_target":"M4-2-u3-X02"},{"t":"㉡ 소수 둘째 자리 숫자는 0이에요","mis":"M4-2-u3-X17"},{"t":"㉢ 3은 0.003을 나타내요","mis":"M4-2-u3-X17"}],"explanation":["6.703의 소수 둘째 자리 숫자는 0, 3은 소수 셋째 자리로 0.003이에요.","0도 빠뜨리지 않고 「영」으로 읽어요.","바르게 고치면 「육 점 칠영삼이라고 읽어요」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#4','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'mc','auto','소수 맞히기 놀이 — 친구가 만든 소수는 4.715예요. 「일의 자리 숫자는 5보다 커?」라는 질문에 알맞은 대답은 어느 것인가요?',ARRAY['M4-2-u3-X03']::text[],true,'{"seq":4,"concept":"M4-2-u3-C2","difficulty":3,"kind":"mc","stem":"소수 맞히기 놀이 — 친구가 만든 소수는 4.715예요. 「일의 자리 숫자는 5보다 커?」라는 질문에 알맞은 대답은 어느 것인가요?","options":[{"t":"아니 — 일의 자리 숫자는 4예요","correct":true},{"t":"응 — 소수 첫째 자리 숫자 7이 5보다 커요","mis":"M4-2-u3-X03"},{"t":"응 — 소수 셋째 자리 숫자가 5예요","mis":"M4-2-u3-X03"}],"explanation":["4.715에서 일의 자리 숫자는 소수점 왼쪽의 4예요.","7은 소수 첫째 자리, 5는 소수 셋째 자리 숫자예요.","4는 5보다 작으므로 대답은 「아니」예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"일의 자리 숫자는 5보다 커?"},{"who":"친구 2","text":"…"}]},"variant_rule":{"alt":[{"stem":"소수 맞히기 놀이 — 친구가 만든 소수는 3.024예요. 「일의 자리 숫자는 3이야?」라는 질문에 알맞은 대답은 어느 것인가요?","options":[{"t":"응 — 일의 자리 숫자는 3이에요","correct":true},{"t":"아니 — 소수 셋째 자리 숫자가 4예요","mis":"M4-2-u3-X03"},{"t":"아니 — 3.024는 3보다 커요","mis":"M4-2-u3-X03"}],"explanation":["3.024에서 일의 자리 숫자는 소수점 왼쪽의 3이에요.","0은 소수 첫째, 2는 소수 둘째, 4는 소수 셋째 자리 숫자예요.","대답은 「응」이에요."],"asset":{"type":"speech","turns":[{"who":"친구 2","text":"아니, 이제 내 차례다. 일의 자리 숫자는 3이야?"},{"who":"친구 1","text":"…"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#5','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'mc','auto','쇼트 트랙 경기에서 두 팀의 기록은 6분 55.968초로 0.001초까지 같았어요. 55.968에서 숫자 6이 나타내는 값은 얼마인가요?',ARRAY['M4-2-u3-X03']::text[],false,'{"seq":5,"concept":"M4-2-u3-C2","difficulty":3,"kind":"mc","stem":"쇼트 트랙 경기에서 두 팀의 기록은 6분 55.968초로 0.001초까지 같았어요. 55.968에서 숫자 6이 나타내는 값은 얼마인가요?","options":[{"t":"0.06","correct":true},{"t":"0.6","mis":"M4-2-u3-X03"},{"t":"0.006","mis":"M4-2-u3-X03"},{"t":"6","mis":"M4-2-u3-X03"}],"explanation":["55.968에서 9는 소수 첫째, 6은 소수 둘째, 8은 소수 셋째 자리 숫자예요.","소수 둘째 자리 숫자 1은 0.01 — 6은 0.01이 6개예요.","6은 0.06을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#6','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'sa','auto','2.52와 2.53 사이가 똑같이 10칸으로 나누어진 수직선에서 2.523은 2.52에서 오른쪽으로 작은 눈금 몇 칸을 간 곳인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u3-C2","difficulty":3,"kind":"sa","stem":"2.52와 2.53 사이가 똑같이 10칸으로 나누어진 수직선에서 2.523은 2.52에서 오른쪽으로 작은 눈금 몇 칸을 간 곳인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["작은 눈금 한 칸은 0.001이에요.","2.523 − 2.52 = 0.003 — 0.001이 3개예요.","작은 눈금 3칸이에요."],"asset":{"type":"number_line","cells":["2.52","…","2.523","…","2.53"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#7','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',3,'sa','auto','전체 크기가 1인 모눈종이를 1000칸으로 나누었어요. 0.1은 0.001이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u3-C2","difficulty":3,"kind":"sa","stem":"전체 크기가 1인 모눈종이를 1000칸으로 나누었어요. 0.1은 0.001이 몇 개인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0.01은 0.001이 10개예요.","0.1은 0.01이 10개 — 0.001이 10 × 10 = 100개예요.","0.1은 0.001이 100개예요."],"variant_rule":{"alt":[{"stem":"전체 크기가 1인 모눈종이를 1000칸으로 나누었어요. 0.01은 0.001이 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["0.001은 0.01을 똑같이 10으로 나눈 하나예요.","0.01을 만들려면 0.001이 10개 있어야 해요.","0.01은 0.001이 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#8','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',4,'essay','teacher','소수 맞히기 놀이 — 숫자 4개로 소수 세 자리 수 3.024를 만들었어요. 친구가 이 수를 맞힐 수 있도록 「응」, 「아니」로만 대답할 수 있는 질문을 자리마다 하나씩 만들어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C2","difficulty":4,"kind":"essay","stem":"소수 맞히기 놀이 — 숫자 4개로 소수 세 자리 수 3.024를 만들었어요. 친구가 이 수를 맞힐 수 있도록 「응」, 「아니」로만 대답할 수 있는 질문을 자리마다 하나씩 만들어 보세요.","answer_guide":{"answer":"예: 일의 자리 숫자는 홀수야?(응) 소수 첫째 자리 숫자는 0이야?(응) 소수 둘째 자리 숫자는 5보다 작아?(응) 소수 셋째 자리 숫자는 4야?(응)","scoring_points":["일의 자리·소수 첫째·둘째·셋째 자리 이름을 바르게 썼는가","「응」, 「아니」로 대답할 수 있는 질문인가","3.024의 각 자리 숫자와 맞는 대답을 했는가"]},"explanation":["3.024 — 일의 자리 3, 소수 첫째 0, 소수 둘째 2, 소수 셋째 4.","자리 이름을 넣어 물어야 숫자를 하나씩 좁힐 수 있어요.","자리를 정확히 아는 것이 놀이의 핵심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#9','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',4,'essay','teacher','훈련한 거리 814 m를 km 단위의 소수로 나타내는 과정을 1 m가 몇 km인지부터 차례로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C2","difficulty":4,"kind":"essay","stem":"훈련한 거리 814 m를 km 단위의 소수로 나타내는 과정을 1 m가 몇 km인지부터 차례로 설명해 보세요.","answer_guide":{"answer":"예: 1000 m = 1 km이므로 1 m = ⟨1/1000⟩ km = 0.001 km이다. 814 m는 0.001 km가 814개이므로 ⟨814/1000⟩ km = 0.814 km이다. 영 점 팔일사라고 읽는다.","scoring_points":["1 m = 0.001 km를 썼는가","0.001 km가 814개임을 썼는가","0.814 km로 바르게 나타냈는가"]},"explanation":["1 m = 0.001 km예요.","814 m = 0.001 km가 814개예요.","814 m = 0.814 km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L03_challenge#10','math',4,2,'u3','L03','tb_g4_2_math_u3_L03_challenge','lesson_challenge','M4-2-u3-C2',4,'essay','teacher','4.275를 여러 가지 방법으로 설명해 보세요(세 가지 이상).','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C2","difficulty":4,"kind":"essay","stem":"4.275를 여러 가지 방법으로 설명해 보세요(세 가지 이상).","answer_guide":{"answer":"예: 4.275는 4 + 0.2 + 0.07 + 0.005이다. 1이 4개, 0.1이 2개, 0.01이 7개, 0.001이 5개인 수이다. 0.001이 4275개인 수이다. 1이 4개, 0.001이 275개인 수이다.","scoring_points":["자릿값으로 나누어(4 + 0.2 + 0.07 + 0.005) 설명했는가","0.001이 4275개인 수라고 썼는가","세 가지 이상 바르게 썼는가"]},"explanation":["4.275 = 4 + 0.2 + 0.07 + 0.005예요.","0.001이 4275개 — 1이 4개, 0.001이 275개라고 해도 같아요.","5는 소수 셋째 자리 숫자로 0.005를 나타내요."],"asset":{"type":"expr_grid","rows":[["","일의 자리","소수 첫째 자리","소수 둘째 자리","소수 셋째 자리"],["4.275","4","2","7","5"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#1','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',1,'mc','auto','반려동물 영양사가 1 kg짜리 영양제에서 0.1 kg, 0.01 kg, 0.001 kg씩 덜어 내요. 0.01의 10배는 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":1,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"반려동물 영양사가 1 kg짜리 영양제에서 0.1 kg, 0.01 kg, 0.001 kg씩 덜어 내요. 0.01의 10배는 얼마인가요?","options":[{"t":"0.1","correct":true},{"t":"0.001","mis":"M4-2-u3-X05"},{"t":"1","mis":"M4-2-u3-X06"}],"explanation":["0.001, 0.01, 0.1, 1은 10배씩 커져요.","0.01을 10배 하면 소수점을 기준으로 숫자가 왼쪽으로 한 자리 옮겨 가요.","0.01의 10배는 0.1이에요."],"variant_rule":{"alt":[{"stem":"1은 0.1의 몇 배인가요?","options":[{"t":"10배","correct":true},{"t":"⟨1/10⟩배","mis":"M4-2-u3-X05"},{"t":"100배","mis":"M4-2-u3-X06"}],"explanation":["0.1이 10개 모이면 1이에요.","0.1을 10배 하면 1이에요.","1은 0.1의 10배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#2','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',1,'mc','auto','0.1의 ⟨1/10⟩은 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":2,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"0.1의 ⟨1/10⟩은 얼마인가요?","options":[{"t":"0.01","correct":true},{"t":"1","mis":"M4-2-u3-X05"},{"t":"0.001","mis":"M4-2-u3-X06"}],"explanation":["1, 0.1, 0.01, 0.001은 ⟨1/10⟩씩 작아져요.","⟨1/10⟩을 하면 소수점을 기준으로 숫자가 오른쪽으로 한 자리 옮겨 가요.","0.1의 ⟨1/10⟩은 0.01이에요."],"variant_rule":{"alt":[{"stem":"0.001은 0.01의 얼마인가요?","options":[{"t":"⟨1/10⟩","correct":true},{"t":"10배","mis":"M4-2-u3-X05"},{"t":"⟨1/100⟩","mis":"M4-2-u3-X06"}],"explanation":["0.01을 똑같이 10으로 나눈 하나가 0.001이에요.","0.001을 10배 하면 0.01이에요.","0.001은 0.01의 ⟨1/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#3','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',1,'sa','auto','자릿값판에서 1과 0.001을 견주어 보아요. 1은 0.001의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u3-C3","difficulty":1,"kind":"sa","stem":"자릿값판에서 1과 0.001을 견주어 보아요. 1은 0.001의 몇 배인가요? 숫자로 쓰세요.","answer":["1000"],"explanation":["0.001 → 0.01 → 0.1 → 1 — 10배씩 세 번이에요.","10 × 10 × 10 = 1000이에요.","1은 0.001의 1000배예요."],"variant_rule":{"alt":[{"stem":"자릿값판에서 1과 0.01을 견주어 보아요. 1은 0.01의 몇 배인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["0.01 → 0.1 → 1 — 10배씩 두 번이에요.","10 × 10 = 100이에요.","1은 0.01의 100배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#4','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',1,'mc','auto','0.065의 10배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X09']::text[],true,'{"seq":4,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"0.065의 10배는 얼마인가요?","options":[{"t":"0.65","correct":true},{"t":"6.5","mis":"M4-2-u3-X06"},{"t":"0.0650","mis":"M4-2-u3-X09"}],"explanation":["10배를 하면 소수점을 기준으로 숫자가 왼쪽으로 한 자리씩 옮겨 가요.","0.065의 숫자를 왼쪽으로 한 자리 옮겨요.","0.065의 10배는 0.65예요."],"variant_rule":{"alt":[{"stem":"0.65의 10배는 얼마인가요?","options":[{"t":"6.5","correct":true},{"t":"0.065","mis":"M4-2-u3-X05"},{"t":"65","mis":"M4-2-u3-X06"},{"t":"0.650","mis":"M4-2-u3-X09"}],"explanation":["10배를 하면 소수점을 기준으로 숫자가 왼쪽으로 한 자리씩 옮겨 가요.","0.65의 숫자를 왼쪽으로 한 자리 옮겨요.","0.65의 10배는 6.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#5','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'mc','auto','2.4의 ⟨1/10⟩은 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":5,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"2.4의 ⟨1/10⟩은 얼마인가요?","options":[{"t":"0.24","correct":true},{"t":"24","mis":"M4-2-u3-X05"},{"t":"0.024","mis":"M4-2-u3-X06"},{"t":"240","mis":"M4-2-u3-X05"}],"explanation":["⟨1/10⟩을 하면 소수점을 기준으로 숫자가 오른쪽으로 한 자리씩 옮겨 가요.","2.4의 숫자를 오른쪽으로 한 자리 옮겨요.","2.4의 ⟨1/10⟩은 0.24예요."],"variant_rule":{"alt":[{"stem":"0.24의 ⟨1/10⟩은 얼마인가요?","options":[{"t":"0.024","correct":true},{"t":"2.4","mis":"M4-2-u3-X05"},{"t":"24","mis":"M4-2-u3-X05"}],"explanation":["⟨1/10⟩을 하면 소수점을 기준으로 숫자가 오른쪽으로 한 자리씩 옮겨 가요.","0.24의 숫자를 오른쪽으로 한 자리 옮겨요.","0.24의 ⟨1/10⟩은 0.024예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#6','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'mc','auto','0.38 L의 10배는 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06','M4-2-u3-X09']::text[],true,'{"seq":6,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"0.38 L의 10배는 얼마인가요?","options":[{"t":"3.8 L","correct":true},{"t":"0.038 L","mis":"M4-2-u3-X05"},{"t":"38 L","mis":"M4-2-u3-X06"},{"t":"0.380 L","mis":"M4-2-u3-X09"}],"explanation":["10배를 하면 소수점을 기준으로 숫자가 왼쪽으로 한 자리씩 옮겨 가요.","0.38의 숫자를 왼쪽으로 한 자리 옮겨요.","0.38 L의 10배는 3.8 L예요."],"variant_rule":{"alt":[{"stem":"91 cm의 ⟨1/10⟩은 얼마인가요?","options":[{"t":"9.1 cm","correct":true},{"t":"910 cm","mis":"M4-2-u3-X05"},{"t":"0.91 cm","mis":"M4-2-u3-X06"},{"t":"9100 cm","mis":"M4-2-u3-X05"}],"explanation":["⟨1/10⟩을 하면 소수점을 기준으로 숫자가 오른쪽으로 한 자리씩 옮겨 가요.","91의 숫자를 오른쪽으로 한 자리 옮겨요.","91 cm의 ⟨1/10⟩은 9.1 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#7','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'mc','auto','1.239 kg의 100배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X09']::text[],true,'{"seq":7,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"1.239 kg의 100배는 얼마인가요?","options":[{"t":"123.9 kg","correct":true},{"t":"1239 kg","mis":"M4-2-u3-X06"},{"t":"12.39 kg","mis":"M4-2-u3-X06"},{"t":"1.23900 kg","mis":"M4-2-u3-X09"}],"explanation":["100배를 하면 소수점을 기준으로 숫자가 왼쪽으로 두 자리씩 옮겨 가요.","1.239의 숫자를 왼쪽으로 두 자리 옮겨요.","1.239 kg의 100배는 123.9 kg이에요."],"variant_rule":{"alt":[{"stem":"5.4초의 ⟨1/100⟩은 얼마인가요?","options":[{"t":"0.054초","correct":true},{"t":"540초","mis":"M4-2-u3-X05"},{"t":"0.54초","mis":"M4-2-u3-X06"},{"t":"5400초","mis":"M4-2-u3-X05"}],"explanation":["⟨1/100⟩을 하면 소수점을 기준으로 숫자가 오른쪽으로 두 자리씩 옮겨 가요.","5.4의 숫자를 오른쪽으로 두 자리 옮겨요.","5.4초의 ⟨1/100⟩은 0.054초예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#8','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'mc','auto','2951의 ⟨1/10⟩은 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],true,'{"seq":8,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"2951의 ⟨1/10⟩은 얼마인가요?","options":[{"t":"295.1","correct":true},{"t":"29510","mis":"M4-2-u3-X05"},{"t":"29.51","mis":"M4-2-u3-X06"},{"t":"295100","mis":"M4-2-u3-X05"}],"explanation":["⟨1/10⟩을 하면 소수점을 기준으로 숫자가 오른쪽으로 한 자리씩 옮겨 가요.","2951의 숫자를 오른쪽으로 한 자리 옮겨요.","2951의 ⟨1/10⟩은 295.1이에요."],"variant_rule":{"alt":[{"stem":"2.951의 10배는 얼마인가요?","options":[{"t":"29.51","correct":true},{"t":"295.1","mis":"M4-2-u3-X06"},{"t":"2.9510","mis":"M4-2-u3-X09"}],"explanation":["10배를 하면 소수점을 기준으로 숫자가 왼쪽으로 한 자리씩 옮겨 가요.","2.951의 숫자를 왼쪽으로 한 자리 옮겨요.","2.951의 10배는 29.51이에요."]},{"stem":"295.1의 ⟨1/100⟩은 얼마인가요?","options":[{"t":"2.951","correct":true},{"t":"29510","mis":"M4-2-u3-X05"},{"t":"29.51","mis":"M4-2-u3-X06"},{"t":"295100","mis":"M4-2-u3-X05"}],"explanation":["⟨1/100⟩을 하면 소수점을 기준으로 숫자가 오른쪽으로 두 자리씩 옮겨 가요.","295.1의 숫자를 오른쪽으로 두 자리 옮겨요.","295.1의 ⟨1/100⟩은 2.951이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#9','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',2,'sa','auto','3.138에서 일의 자리 숫자 3이 나타내는 수는 소수 둘째 자리 숫자 3이 나타내는 수의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C3","difficulty":2,"kind":"sa","stem":"3.138에서 일의 자리 숫자 3이 나타내는 수는 소수 둘째 자리 숫자 3이 나타내는 수의 몇 배인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["일의 자리 3은 3, 소수 둘째 자리 3은 0.03을 나타내요.","0.03을 10배 하면 0.3, 100배 하면 3이에요.","3은 0.03의 100배예요."],"asset":{"type":"expr_grid","rows":[["","일의 자리","소수 첫째 자리","소수 둘째 자리","소수 셋째 자리"],["3.138","3","1","3","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_basic#10','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_basic','lesson_basic','M4-2-u3-C3',3,'mc','auto','한 병에 0.28 L가 들어 있는 오렌지 주스 10병의 양은 몇 L인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06','M4-2-u3-X16']::text[],true,'{"seq":10,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"한 병에 0.28 L가 들어 있는 오렌지 주스 10병의 양은 몇 L인가요?","options":[{"t":"2.8 L","correct":true},{"t":"0.028 L","mis":"M4-2-u3-X05"},{"t":"28 L","mis":"M4-2-u3-X06"},{"t":"10.28 L","mis":"M4-2-u3-X16"}],"explanation":["0.28 L가 10병 — 0.28의 10배예요.","10배 하면 숫자가 왼쪽으로 한 자리 옮겨 가요.","0.28의 10배는 2.8 — 2.8 L예요."],"variant_rule":{"alt":[{"stem":"10원짜리 동전 한 개의 무게는 1.22 g이에요. 10원짜리 동전을 모아 1000원을 만들면 모은 동전의 무게는 몇 g인가요?","options":[{"t":"122 g","correct":true},{"t":"12.2 g","mis":"M4-2-u3-X06"},{"t":"1220 g","mis":"M4-2-u3-X06"},{"t":"101.22 g","mis":"M4-2-u3-X16"}],"explanation":["10원짜리 동전 100개가 1000원이에요.","1.22 g의 100배 — 숫자가 왼쪽으로 두 자리 옮겨 가요.","1.22의 100배는 122 — 122 g이에요."]},{"stem":"공 한 개의 무게가 5.3 g이에요. 공 100개의 무게는 몇 g인가요?","options":[{"t":"530 g","correct":true},{"t":"53 g","mis":"M4-2-u3-X06"},{"t":"5300 g","mis":"M4-2-u3-X06"},{"t":"0.053 g","mis":"M4-2-u3-X05"}],"explanation":["공 100개 — 5.3의 100배예요.","100배 하면 숫자가 왼쪽으로 두 자리 옮겨 가요.","5.3의 100배는 530 — 530 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#1','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',2,'mc','auto','10배씩 커지는 수를 늘어놓았어요. 0.104 → 1.04 → 10.4 → 104 → □ 에서 □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],false,'{"seq":1,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"10배씩 커지는 수를 늘어놓았어요. 0.104 → 1.04 → 10.4 → 104 → □ 에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"1040","correct":true},{"t":"1050","mis":"M4-2-u3-X06"},{"t":"10.4","mis":"M4-2-u3-X05"},{"t":"10400","mis":"M4-2-u3-X06"}],"explanation":["오른쪽으로 갈수록 10배씩 커져요.","104의 10배는 1040이에요.","거꾸로 왼쪽으로 가면 ⟨1/10⟩씩 작아져 0.104가 돼요."],"asset":{"type":"number_line","cells":["0.104","1.04","10.4","104","?"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#2','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',2,'mc','auto','1.72의 □배는 17.2예요. □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],true,'{"seq":2,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"1.72의 □배는 17.2예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M4-2-u3-X06"},{"t":"⟨1/10⟩","mis":"M4-2-u3-X05"}],"explanation":["1.72 → 17.2: 숫자가 왼쪽으로 한 자리 옮겨 갔어요.","왼쪽으로 한 자리 = 10배예요.","1.72의 10배는 17.2예요."],"variant_rule":{"alt":[{"stem":"14.35의 □은 1.435예요. □에 알맞은 것은 무엇인가요?","options":[{"t":"⟨1/10⟩","correct":true},{"t":"10배","mis":"M4-2-u3-X05"},{"t":"⟨1/100⟩","mis":"M4-2-u3-X06"}],"explanation":["14.35 → 1.435: 숫자가 오른쪽으로 한 자리 옮겨 갔어요.","오른쪽으로 한 자리 = ⟨1/10⟩이에요.","14.35의 ⟨1/10⟩은 1.435예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#3','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'match','auto','같은 것끼리 선으로 이어 보세요.','{}'::text[],false,'{"seq":3,"concept":"M4-2-u3-C3","difficulty":3,"kind":"match","stem":"같은 것끼리 선으로 이어 보세요.","pairs":[{"l":"295.1의 ⟨1/100⟩","r":"2.951"},{"l":"2.951의 10배","r":"29.51"},{"l":"2951의 ⟨1/10⟩","r":"295.1"}],"mis":"M4-2-u3-X06","explanation":["⟨1/100⟩은 오른쪽으로 두 자리, ⟨1/10⟩은 한 자리, 10배는 왼쪽으로 한 자리예요.","295.1의 ⟨1/100⟩ = 2.951, 2.951의 10배 = 29.51이에요.","2951의 ⟨1/10⟩ = 295.1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#4','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'mc','auto','소수를 10배 하면 숫자는 어떻게 달라지나요?',ARRAY['M4-2-u3-X05','M4-2-u3-X09','M4-2-u3-X06']::text[],true,'{"seq":4,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"소수를 10배 하면 숫자는 어떻게 달라지나요?","options":[{"t":"소수점을 기준으로 숫자가 왼쪽으로 한 자리씩 옮겨 가요","correct":true},{"t":"소수점을 기준으로 숫자가 오른쪽으로 한 자리씩 옮겨 가요","mis":"M4-2-u3-X05"},{"t":"수의 끝에 0을 하나 붙여요","mis":"M4-2-u3-X09"},{"t":"숫자가 두 자리씩 옮겨 가요","mis":"M4-2-u3-X06"}],"explanation":["0.065의 10배는 0.65, 0.65의 10배는 6.5예요.","숫자 6과 5가 소수점을 기준으로 왼쪽으로 한 자리씩 옮겨 갔어요.","소수 끝에 0을 붙이면(0.650) 크기가 그대로예요."],"variant_rule":{"alt":[{"stem":"소수의 ⟨1/10⟩을 하면 숫자는 어떻게 달라지나요?","options":[{"t":"소수점을 기준으로 숫자가 오른쪽으로 한 자리씩 옮겨 가요","correct":true},{"t":"소수점을 기준으로 숫자가 왼쪽으로 한 자리씩 옮겨 가요","mis":"M4-2-u3-X05"},{"t":"수의 끝자리 숫자를 하나 지워요","mis":"M4-2-u3-X09"},{"t":"숫자가 두 자리씩 옮겨 가요","mis":"M4-2-u3-X06"}],"explanation":["2.4의 ⟨1/10⟩은 0.24, 0.24의 ⟨1/10⟩은 0.024예요.","숫자 2와 4가 소수점을 기준으로 오른쪽으로 한 자리씩 옮겨 갔어요.","⟨1/10⟩은 오른쪽으로 한 자리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#5','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'sa','auto','수학에 퐁당 — 0.19의 1000배는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u3-C3","difficulty":3,"kind":"sa","stem":"수학에 퐁당 — 0.19의 1000배는 얼마인가요? 숫자로 쓰세요.","answer":["190"],"explanation":["1000배 하면 숫자가 왼쪽으로 세 자리 옮겨 가요.","0.19 → 1.9 → 19 → 190이에요.","0.19의 1000배는 190이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#6','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'mc','auto','수학에 퐁당 — ❶ 1.9의 ⟨1/10⟩, ❷ 0.19의 1000배, ❸ 19의 ⟨1/1000⟩을 구해 표에서 짝 지어진 글자를 찾았어요(190 테, 1.9 크, 19 라, 0.019 빈, 0.19 스). 분수를 소수로 나타낸 수학자의 이름은 무엇인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],false,'{"seq":6,"concept":"M4-2-u3-C3","difficulty":3,"kind":"mc","stem":"수학에 퐁당 — ❶ 1.9의 ⟨1/10⟩, ❷ 0.19의 1000배, ❸ 19의 ⟨1/1000⟩을 구해 표에서 짝 지어진 글자를 찾았어요(190 테, 1.9 크, 19 라, 0.019 빈, 0.19 스). 분수를 소수로 나타낸 수학자의 이름은 무엇인가요?","options":[{"t":"스테빈","correct":true},{"t":"라테빈","mis":"M4-2-u3-X05"},{"t":"스라빈","mis":"M4-2-u3-X06"},{"t":"스테스","mis":"M4-2-u3-X06"}],"explanation":["❶ 1.9의 ⟨1/10⟩ = 0.19(스), ❷ 0.19의 1000배 = 190(테)이에요.","❸ 19의 ⟨1/1000⟩ = 0.019(빈)이에요.","수학자의 이름은 스테빈 — 소수를 널리 보급했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#7','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',3,'ox','auto','친구가 「0.01의 10배는 0.001이에요.」라고 했어요. 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M4-2-u3-X05']::text[],false,'{"seq":7,"concept":"M4-2-u3-C3","difficulty":3,"kind":"ox","stem":"친구가 「0.01의 10배는 0.001이에요.」라고 했어요. 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"10배 하면 숫자가 왼쪽으로 옮겨 가므로 0.01의 10배는 0.1이에요","correct":true},{"t":"10배 하면 0이 하나 늘어나므로 0.001이에요","mis":"M4-2-u3-X05"}],"mis":"M4-2-u3-X05","explanation":["10배는 왼쪽으로 한 자리 — 0.01의 10배는 0.1이에요.","0.001은 0.01의 ⟨1/10⟩이에요.","친구의 말은 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#8','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',4,'essay','teacher','1.239 kg의 100배는 몇 kg인지 구하고, 자릿값판에서 숫자가 어떻게 옮겨 가는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C3","difficulty":4,"kind":"essay","stem":"1.239 kg의 100배는 몇 kg인지 구하고, 자릿값판에서 숫자가 어떻게 옮겨 가는지 설명해 보세요.","answer_guide":{"answer":"1.239 kg의 100배는 123.9 kg이다. 100배를 하면 소수점을 기준으로 숫자 1, 2, 3, 9가 왼쪽으로 두 자리씩 옮겨 간다(10배를 두 번 한 것과 같다).","scoring_points":["123.9 kg을 구했는가","왼쪽으로 옮겨 간다고 썼는가","두 자리씩 옮겨 간다고 썼는가"]},"explanation":["100배 = 10배를 두 번 한 것이에요.","1.239 → 12.39 → 123.9예요.","1.239 kg의 100배는 123.9 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#9','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',4,'essay','teacher','10원짜리 동전 한 개의 무게는 1.22 g이에요. 10원짜리 동전을 모아 1000원을 만들면 모은 동전의 무게는 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C3","difficulty":4,"kind":"essay","stem":"10원짜리 동전 한 개의 무게는 1.22 g이에요. 10원짜리 동전을 모아 1000원을 만들면 모은 동전의 무게는 몇 g인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"10원짜리 동전 100개를 모으면 1000원이 된다. 모은 동전의 무게는 1.22 g의 100배이므로 122 g이다.","scoring_points":["동전이 100개임을 썼는가","1.22의 100배로 식을 세웠는가","122 g을 구했는가"]},"explanation":["10 × 100 = 1000 — 동전 100개예요.","1.22의 100배 — 숫자가 왼쪽으로 두 자리 옮겨 가요.","모은 동전의 무게는 122 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L04_challenge#10','math',4,2,'u3','L04','tb_g4_2_math_u3_L04_challenge','lesson_challenge','M4-2-u3-C3',4,'essay','teacher','5.4초의 ⟨1/100⟩은 몇 초인지 구하고, 0.001, 0.01, 0.1, 1 사이의 관계를 써서 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C3","difficulty":4,"kind":"essay","stem":"5.4초의 ⟨1/100⟩은 몇 초인지 구하고, 0.001, 0.01, 0.1, 1 사이의 관계를 써서 까닭을 설명해 보세요.","answer_guide":{"answer":"5.4초의 ⟨1/100⟩은 0.054초이다. ⟨1/10⟩을 하면 숫자가 오른쪽으로 한 자리 옮겨 가는데 ⟨1/100⟩은 ⟨1/10⟩을 두 번 한 것이므로 5.4 → 0.54 → 0.054가 된다. 1의 ⟨1/10⟩은 0.1, 0.1의 ⟨1/10⟩은 0.01인 것과 같다.","scoring_points":["0.054초를 구했는가","⟨1/100⟩은 ⟨1/10⟩을 두 번 한 것임을 썼는가","숫자가 오른쪽으로 두 자리 옮겨 간다고 썼는가"]},"explanation":["⟨1/100⟩ = ⟨1/10⟩을 두 번이에요.","5.4 → 0.54 → 0.054예요.","5.4초의 ⟨1/100⟩은 0.054초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_basic#1','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',1,'mc','auto','교과서 한 번 더 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.7 ○ 0.58',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],true,'{"seq":1,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"교과서 한 번 더 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.7 ○ 0.58","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X07"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 첫째 자리 숫자를 견주면 7 > 5예요.","0.7 > 0.58."],"variant_rule":{"alt":[{"stem":"교과서 한 번 더 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.42 ○ 0.46","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X21"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 둘째 자리 숫자를 견주면 2 < 6이에요.","0.42 < 0.46."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_basic#2','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',1,'sa','auto','0.5를 전체 크기가 1인 모눈종이(100칸)에 나타냈어요. 0.5는 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u3-C4","difficulty":1,"kind":"sa","stem":"0.5를 전체 크기가 1인 모눈종이(100칸)에 나타냈어요. 0.5는 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["0.5는 0.1이 5개 — 100칸 모눈종이에서는 50칸이에요.","0.5 = 0.50 — 끝자리에 0을 붙여도 크기는 같아요.","0.5는 0.01이 50개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,10],[0,10]],"hi":true},{"p":[[1,0],[2,0],[2,10],[1,10]],"hi":true},{"p":[[2,0],[3,0],[3,10],[2,10]],"hi":true},{"p":[[3,0],[4,0],[4,10],[3,10]],"hi":true},{"p":[[4,0],[5,0],[5,10],[4,10]],"hi":true},{"p":[[5,0],[6,0],[6,10],[5,10]]},{"p":[[6,0],[7,0],[7,10],[6,10]]},{"p":[[7,0],[8,0],[8,10],[7,10]]},{"p":[[8,0],[9,0],[9,10],[8,10]]},{"p":[[9,0],[10,0],[10,10],[9,10]]}],"u":16},"variant_rule":{"alt":[{"stem":"0.47을 전체 크기가 1인 모눈종이(100칸)에 나타냈어요. 0.47은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["모눈종이 한 칸은 0.01이에요.","0.47은 47칸을 색칠해요.","0.47은 0.01이 47개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]],"hi":true},{"p":[[5,0],[6,0],[6,1],[5,1]],"hi":true},{"p":[[6,0],[7,0],[7,1],[6,1]],"hi":true},{"p":[[7,0],[8,0],[8,1],[7,1]],"hi":true},{"p":[[8,0],[9,0],[9,1],[8,1]],"hi":true},{"p":[[9,0],[10,0],[10,1],[9,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2,1],[3,1],[3,2],[2,2]],"hi":true},{"p":[[3,1],[4,1],[4,2],[3,2]],"hi":true},{"p":[[4,1],[5,1],[5,2],[4,2]],"hi":true},{"p":[[5,1],[6,1],[6,2],[5,2]],"hi":true},{"p":[[6,1],[