INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_basic#8','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',2,'ox','auto','「0.5와 0.50은 크기가 달라요.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M4-2-u3-X09']::text[],false,'{"seq":8,"concept":"M4-2-u3-C4","difficulty":2,"kind":"ox","stem":"「0.5와 0.50은 크기가 달라요.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"0.5는 0.01이 50개, 0.50도 0.01이 50개로 크기가 같아요","correct":true},{"t":"0.50은 숫자가 하나 더 있으니 더 커요","mis":"M4-2-u3-X09"}],"mis":"M4-2-u3-X09","explanation":["0.5를 100칸 모눈종이에 나타내면 50칸이에요.","소수는 오른쪽 끝자리에 0을 붙여도 크기가 같아요.","0.5 = 0.50 — 친구의 말은 틀렸어요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,10],[0,10]],"hi":true},{"p":[[1,0],[2,0],[2,10],[1,10]],"hi":true},{"p":[[2,0],[3,0],[3,10],[2,10]],"hi":true},{"p":[[3,0],[4,0],[4,10],[3,10]],"hi":true},{"p":[[4,0],[5,0],[5,10],[4,10]],"hi":true},{"p":[[5,0],[6,0],[6,10],[5,10]]},{"p":[[6,0],[7,0],[7,10],[6,10]]},{"p":[[7,0],[8,0],[8,10],[7,10]]},{"p":[[8,0],[9,0],[9,10],[8,10]]},{"p":[[9,0],[10,0],[10,10],[9,10]]}],"u":16}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_basic#9','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',2,'mc','auto','두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.483 ○ 0.487',ARRAY['M4-2-u3-X21','M4-2-u3-X18']::text[],true,'{"seq":9,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.483 ○ 0.487","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X21"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 셋째 자리 숫자를 견주면 3 < 7이에요.","0.483 < 0.487."],"variant_rule":{"alt":[{"stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 2.504 ○ 2.53","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X07"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 둘째 자리 숫자를 견주면 0 < 3이에요.","2.504 < 2.53."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_basic#10','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_basic','lesson_basic','M4-2-u3-C4',3,'mc','auto','성진이네 반에서 음악실까지는 12.9 m, 과학실까지는 14.1 m, 화장실까지는 12.63 m예요. 거리가 가까운 곳부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X17','M4-2-u3-X08']::text[],false,'{"seq":10,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"성진이네 반에서 음악실까지는 12.9 m, 과학실까지는 14.1 m, 화장실까지는 12.63 m예요. 거리가 가까운 곳부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"화장실, 음악실, 과학실","correct":true},{"t":"음악실, 화장실, 과학실","mis":"M4-2-u3-X07"},{"t":"과학실, 음악실, 화장실","mis":"M4-2-u3-X17"},{"t":"화장실, 과학실, 음악실","mis":"M4-2-u3-X08"}],"explanation":["자연수 부분을 견주면 12 < 14 — 과학실이 가장 멀어요.","12.9와 12.63: 소수 첫째 자리 9 > 6 — 12.63이 더 작아요.","가까운 곳부터 화장실, 음악실, 과학실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#1','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',2,'mc','auto','2.943, 3.14, 2.947을 큰 수부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X17','M4-2-u3-X08']::text[],false,'{"seq":1,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"2.943, 3.14, 2.947을 큰 수부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"3.14, 2.947, 2.943","correct":true},{"t":"2.947, 2.943, 3.14","mis":"M4-2-u3-X07"},{"t":"2.943, 2.947, 3.14","mis":"M4-2-u3-X17"},{"t":"3.14, 2.943, 2.947","mis":"M4-2-u3-X08"}],"explanation":["자연수 부분을 먼저 견주면 3.14가 가장 커요.","2.943과 2.947: 소수 셋째 자리 3 < 7이에요.","큰 수부터 3.14, 2.947, 2.943이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#2','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',2,'mc','auto','미술 시간에 사용한 파란색 실의 길이는 8.36 m, 빨간색 실의 길이는 8.34 m예요. 사용한 길이가 더 긴 실은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X18']::text[],false,'{"seq":2,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"미술 시간에 사용한 파란색 실의 길이는 8.36 m, 빨간색 실의 길이는 8.34 m예요. 사용한 길이가 더 긴 실은 어느 것인가요?","options":[{"t":"파란색 실","correct":true},{"t":"빨간색 실","mis":"M4-2-u3-X17"},{"t":"두 실의 길이가 같아요","mis":"M4-2-u3-X18"}],"explanation":["일의 자리, 소수 첫째 자리가 같아요.","소수 둘째 자리를 견주면 6 > 4예요.","8.36 > 8.34 — 파란색 실이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#3','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',3,'mc','auto','은비의 의견에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X08','M4-2-u3-X18']::text[],false,'{"seq":3,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"은비의 의견에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"0.5 = 0.50이라 0.01이 50개, 0.47은 0.01이 47개이므로 0.5가 더 커요","correct":true},{"t":"0.47이 0.5보다 소수의 자릿수가 더 많아서 은비의 말이 맞아요","mis":"M4-2-u3-X07"},{"t":"47이 5보다 크니까 은비의 말이 맞아요","mis":"M4-2-u3-X08"},{"t":"자릿수가 달라서 견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["0.47과 0.5를 0.01의 개수로 견주어요.","0.5는 0.50과 같아 0.01이 50개예요.","47개 < 50개 — 0.5가 더 커요."],"asset":{"type":"speech","turns":[{"who":"은비","text":"47이 5보다 더 크므로 0.47이 0.5보다 더 큰 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#4','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',3,'mc','auto','5장의 카드 5, 0, 2, 7, 「.」을 한 번씩만 사용하여 소수 세 자리 수를 만들려고 해요. 7.025와 7.25 사이에 있는 수를 모두 쓴 것은 어느 것인가요?',ARRAY['M4-2-u3-X09','M4-2-u3-X20','M4-2-u3-X07']::text[],false,'{"seq":4,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"5장의 카드 5, 0, 2, 7, 「.」을 한 번씩만 사용하여 소수 세 자리 수를 만들려고 해요. 7.025와 7.25 사이에 있는 수를 모두 쓴 것은 어느 것인가요?","options":[{"t":"7.052, 7.205","correct":true},{"t":"7.052, 7.205, 7.250","mis":"M4-2-u3-X09"},{"t":"7.052","mis":"M4-2-u3-X20"},{"t":"7.205, 7.502","mis":"M4-2-u3-X07"}],"explanation":["7□.□□□ — 7.025보다 크고 7.25보다 작아야 해요.","7.25 = 7.250 — 사이에 있지 않아요.","만들 수 있는 수는 7.052, 7.205예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#5','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',3,'error','auto','한 친구가 「0.003은 0.02보다 크고, 0.4는 0.03보다 작다.」라고 했어요. 친구가 잘못 생각한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X09','M4-2-u3-X21']::text[],false,'{"seq":5,"concept":"M4-2-u3-C4","difficulty":3,"kind":"error","stem":"한 친구가 「0.003은 0.02보다 크고, 0.4는 0.03보다 작다.」라고 했어요. 친구가 잘못 생각한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"소수의 길이(자릿수)가 길수록 큰 수라고 생각했어요","correct":true,"mis_target":"M4-2-u3-X07"},{"t":"끝자리에 0을 붙이면 수의 크기가 달라진다고 생각했어요","mis":"M4-2-u3-X09"},{"t":"부등호의 뜻을 거꾸로 알았어요","mis":"M4-2-u3-X21"}],"explanation":["0.003은 소수 셋째 자리까지 있어 길지만 0.02보다 작아요.","소수는 수의 길이와 크기가 비례하지 않아요.","자리를 맞추어 큰 자리부터 견주면 0.003 < 0.02, 0.4 > 0.03이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#6','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',3,'mc','auto','건우와 도윤이가 소수의 크기를 비교하고 있어요. 도윤이의 질문에 알맞은 대답은 어느 것인가요?',ARRAY['M4-2-u3-X08','M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":6,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"건우와 도윤이가 소수의 크기를 비교하고 있어요. 도윤이의 질문에 알맞은 대답은 어느 것인가요?","options":[{"t":"아니, 1.54가 더 커 — 일의 자리가 같고 소수 첫째 자리가 5 > 2야","correct":true},{"t":"응, 1296이 154보다 크니까 1.296이 더 커","mis":"M4-2-u3-X08"},{"t":"응, 1.296이 자릿수가 더 많으니까 더 커","mis":"M4-2-u3-X07"},{"t":"자릿수가 달라서 견줄 수 없어","mis":"M4-2-u3-X18"}],"explanation":["소수의 크기는 같은 자리끼리 견주어요.","일의 자리는 1로 같고 소수 첫째 자리는 5 > 2예요.","1.54 > 1.296이에요."],"asset":{"type":"speech","turns":[{"who":"건우","text":"1.54와 1.296의 크기를 비교해 보자."},{"who":"도윤","text":"1296은 154보다 더 큰 수야. 그럼 1.296이 1.54보다 더 클까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#7','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',3,'mc','auto','두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 3.97 ○ 3.962',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],true,'{"seq":7,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 3.97 ○ 3.962","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X07"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 둘째 자리 숫자를 견주면 7 > 6이에요.","3.97 > 3.962."],"variant_rule":{"alt":[{"stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 5.126 ○ 5.129","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X21"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 셋째 자리 숫자를 견주면 6 < 9예요.","5.126 < 5.129."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#8','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',4,'essay','teacher','1.642와 1.648의 크기를 자릿값 표를 이용하여 비교하고, 소수의 크기를 비교하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C4","difficulty":4,"kind":"essay","stem":"1.642와 1.648의 크기를 자릿값 표를 이용하여 비교하고, 소수의 크기를 비교하는 방법을 설명해 보세요.","answer_guide":{"answer":"1.642와 1.648은 일의 자리 1, 소수 첫째 자리 6, 소수 둘째 자리 4가 같고 소수 셋째 자리를 비교하면 2 < 8이므로 1.642 < 1.648이다. 소수의 크기는 소수점을 기준으로 자리를 맞추어 쓰고 큰 자리 수부터 같은 자리 수끼리 차례대로 비교한다.","scoring_points":["1.642 < 1.648을 바르게 썼는가","소수 셋째 자리에서 2 < 8로 견주었는가","큰 자리부터 같은 자리끼리 비교한다고 썼는가"]},"explanation":["자리를 맞추어 큰 자리부터 견주어요.","일·소수 첫째·둘째 자리가 같고 소수 셋째 자리가 2 < 8이에요.","1.642 < 1.648이에요."],"asset":{"type":"expr_grid","rows":[["","일의 자리","소수 첫째 자리","소수 둘째 자리","소수 셋째 자리"],["1.642","1","6","4","2"],["1.648","1","6","4","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#9','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',4,'essay','teacher','건우와 도윤이의 대화예요. 건우가 「1.54가 더 커. 왜냐하면 …」이라고 말을 이어 가요. 건우의 마지막 말을 완성해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C4","difficulty":4,"kind":"essay","stem":"건우와 도윤이의 대화예요. 건우가 「1.54가 더 커. 왜냐하면 …」이라고 말을 이어 가요. 건우의 마지막 말을 완성해 보세요.","answer_guide":{"answer":"예: 소수의 크기를 비교할 때는 같은 자리 수끼리 비교해야 해. 1.54와 1.296은 일의 자리 수가 같으므로 소수 첫째 자리 수를 비교하면 5 > 2이므로 1.54 > 1.296이야.","scoring_points":["같은 자리 수끼리 비교해야 한다고 썼는가","일의 자리가 같고 소수 첫째 자리 5 > 2를 썼는가","1.54 > 1.296의 결론을 썼는가"]},"explanation":["1296과 154는 자연수라서 길이로 견줄 수 있어요.","소수는 소수점을 기준으로 자리를 맞추어 견주어요.","1.54 > 1.296이에요."],"asset":{"type":"speech","turns":[{"who":"건우","text":"1.54와 1.296의 크기를 비교해 보자."},{"who":"도윤","text":"1296은 154보다 더 큰 수야. 그럼 1.296이 1.54보다 더 클까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L05_challenge#10','math',4,2,'u3','L05','tb_g4_2_math_u3_L05_challenge','lesson_challenge','M4-2-u3-C4',4,'essay','teacher','토의·토론 — 은비의 의견 「47이 5보다 더 크므로 0.47이 0.5보다 더 큰 것 같아.」에 대한 나의 생각을 쓰고, 모눈종이와 0.01의 개수를 이용하여 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C4","difficulty":4,"kind":"essay","stem":"토의·토론 — 은비의 의견 「47이 5보다 더 크므로 0.47이 0.5보다 더 큰 것 같아.」에 대한 나의 생각을 쓰고, 모눈종이와 0.01의 개수를 이용하여 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 내 생각과 다르다(빨간불). 0.47은 100칸 모눈종이에 47칸, 0.5는 0.50과 같아 50칸을 색칠하므로 0.5가 더 크다. 0.47은 0.01이 47개, 0.5는 0.01이 50개이므로 0.47 < 0.5이다.","scoring_points":["은비의 의견이 틀렸다고 판단했는가","0.5 = 0.50(0.01이 50개)을 썼는가","0.01의 개수(47 < 50)로 견주었는가"]},"explanation":["0.5 = 0.50이에요.","0.47은 0.01이 47개, 0.5는 0.01이 50개예요.","0.47 < 0.5 — 소수의 길이로 견주면 안 돼요."],"asset":{"type":"speech","turns":[{"who":"은비","text":"47이 5보다 더 크므로 0.47이 0.5보다 더 큰 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#1','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',1,'sa','auto','동물 보건사가 고양이들에게 사료를 오전에 0.3 kg, 오후에 0.5 kg 주었어요. 0.3 + 0.5는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u3-C5","difficulty":1,"kind":"sa","stem":"동물 보건사가 고양이들에게 사료를 오전에 0.3 kg, 오후에 0.5 kg 주었어요. 0.3 + 0.5는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["0.3은 0.1이 3개, 0.5는 0.1이 5개예요.","3 + 5 = 8 — 모눈종이 8칸이에요.","0.3 + 0.5는 0.1이 8개 — 0.8이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,10],[0,10]],"hi":true},{"p":[[1,0],[2,0],[2,10],[1,10]],"hi":true},{"p":[[2,0],[3,0],[3,10],[2,10]],"hi":true},{"p":[[3,0],[4,0],[4,10],[3,10]],"hi":true},{"p":[[4,0],[5,0],[5,10],[4,10]],"hi":true},{"p":[[5,0],[6,0],[6,10],[5,10]],"hi":true},{"p":[[6,0],[7,0],[7,10],[6,10]],"hi":true},{"p":[[7,0],[8,0],[8,10],[7,10]],"hi":true},{"p":[[8,0],[9,0],[9,10],[8,10]]},{"p":[[9,0],[10,0],[10,10],[9,10]]}],"u":16},"variant_rule":{"alt":[{"stem":"동물 보건사가 고양이들에게 사료를 오전에 0.2 kg, 오후에 0.3 kg 주었어요. 0.2 + 0.3은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["0.2는 0.1이 2개, 0.3은 0.1이 3개예요.","2 + 3 = 5 — 모눈종이 5칸이에요.","0.2 + 0.3은 0.1이 5개 — 0.5예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,10],[0,10]],"hi":true},{"p":[[1,0],[2,0],[2,10],[1,10]],"hi":true},{"p":[[2,0],[3,0],[3,10],[2,10]],"hi":true},{"p":[[3,0],[4,0],[4,10],[3,10]],"hi":true},{"p":[[4,0],[5,0],[5,10],[4,10]],"hi":true},{"p":[[5,0],[6,0],[6,10],[5,10]]},{"p":[[6,0],[7,0],[7,10],[6,10]]},{"p":[[7,0],[8,0],[8,10],[7,10]]},{"p":[[8,0],[9,0],[9,10],[8,10]]},{"p":[[9,0],[10,0],[10,10],[9,10]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#2','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',1,'mc','auto','고양이들에게 오전에 0.3 kg, 오후에 0.5 kg 준 사료는 모두 몇 kg인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":2,"concept":"M4-2-u3-C5","difficulty":1,"kind":"mc","stem":"고양이들에게 오전에 0.3 kg, 오후에 0.5 kg 준 사료는 모두 몇 kg인가요?","options":[{"t":"0.8 kg","correct":true},{"t":"0.2 kg","mis":"M4-2-u3-X16"},{"t":"8 kg","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 3 + 5 = 8이에요.","0.3 + 0.5 = 0.8 kg이에요."],"variant_rule":{"alt":[{"stem":"고양이들에게 오전에 0.2 kg, 오후에 0.3 kg 준 사료는 모두 몇 kg인가요?","options":[{"t":"0.5 kg","correct":true},{"t":"0.1 kg","mis":"M4-2-u3-X16"},{"t":"5 kg","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 2 + 3 = 5예요.","0.2 + 0.3 = 0.5 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#3','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',1,'mc','auto','0.6 + 0.1을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":3,"concept":"M4-2-u3-C5","difficulty":1,"kind":"mc","stem":"0.6 + 0.1을 계산한 값은 얼마인가요?","options":[{"t":"0.7","correct":true},{"t":"0.5","mis":"M4-2-u3-X16"},{"t":"7","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 6 + 1 = 7이에요.","0.6 + 0.1 = 0.7이에요."],"variant_rule":{"alt":[{"stem":"0.4 + 0.1을 계산한 값은 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"0.3","mis":"M4-2-u3-X16"},{"t":"5","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 4 + 1 = 5예요.","0.4 + 0.1 = 0.5예요."]},{"stem":"0.6 + 0.3을 계산한 값은 얼마인가요?","options":[{"t":"0.9","correct":true},{"t":"0.3","mis":"M4-2-u3-X16"},{"t":"9","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 6 + 3 = 9예요.","0.6 + 0.3 = 0.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#4','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',1,'mc','auto','수직선에서 0부터 1.7만큼 오른쪽으로 간 다음 0.6만큼 오른쪽으로 더 갔어요. 1.7 + 0.6은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],false,'{"seq":4,"concept":"M4-2-u3-C5","difficulty":1,"kind":"mc","stem":"수직선에서 0부터 1.7만큼 오른쪽으로 간 다음 0.6만큼 오른쪽으로 더 갔어요. 1.7 + 0.6은 얼마인가요?","options":[{"t":"2.3","correct":true},{"t":"1.3","mis":"M4-2-u3-X11"},{"t":"1.13","mis":"M4-2-u3-X10"},{"t":"1.1","mis":"M4-2-u3-X16"}],"explanation":["수직선의 작은 눈금 한 칸은 0.1 — 1.7에서 6칸을 더 가요.","소수 첫째 자리: 7 + 6 = 13 — 3을 쓰고 일의 자리로 1을 받아올려요.","1.7 + 0.6 = 2.3이에요."],"asset":{"type":"number_line","cells":["0","…","1.7","…","?"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#5','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',2,'sa','auto','1.7 + 0.6을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u3-C5","difficulty":2,"kind":"sa","stem":"1.7 + 0.6을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 7 + 6 = 13 — 3을 쓰고 일의 자리로 1을 받아올려요.","1.7 + 0.6 = 2.3 — ?는 일의 자리 숫자 2예요."],"asset":{"type":"expr_grid","rows":[["","1",".","7"],["+","0",".","6"],["","?",".","3"]]},"variant_rule":{"alt":[{"stem":"5.8 + 0.4를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 8 + 4 = 12 — 2를 쓰고 일의 자리로 1을 받아올려요.","5.8 + 0.4 = 6.2 — ?는 일의 자리 숫자 6이에요."],"asset":{"type":"expr_grid","rows":[["","5",".","8"],["+","0",".","4"],["","?",".","2"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#6','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',2,'mc','auto','3.8 + 4.9를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],true,'{"seq":6,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"3.8 + 4.9를 계산한 값은 얼마인가요?","options":[{"t":"8.7","correct":true},{"t":"7.7","mis":"M4-2-u3-X11"},{"t":"7.17","mis":"M4-2-u3-X10"},{"t":"1.1","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 8 + 9 = 17 — 7을 쓰고 일의 자리로 1을 받아올려요.","3.8 + 4.9 = 8.7이에요."],"asset":{"type":"expr_grid","rows":[["","3",".","8"],["+","4",".","9"],["","?",".","?"]]},"variant_rule":{"alt":[{"stem":"0.5 + 2.3을 계산한 값은 얼마인가요?","options":[{"t":"2.8","correct":true},{"t":"1.8","mis":"M4-2-u3-X16"},{"t":"28","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 5 + 23 = 28이에요.","0.5 + 2.3 = 2.8이에요."],"asset":{"type":"expr_grid","rows":[["","0",".","5"],["+","2",".","3"],["","?",".","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#7','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',2,'mc','auto','집에서 서점까지의 거리는 1.9 km이고, 서점에서 은행까지의 거리는 0.7 km예요. 집에서 서점을 지나 은행까지 간 거리는 몇 km인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],true,'{"seq":7,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"집에서 서점까지의 거리는 1.9 km이고, 서점에서 은행까지의 거리는 0.7 km예요. 집에서 서점을 지나 은행까지 간 거리는 몇 km인가요?","options":[{"t":"2.6 km","correct":true},{"t":"1.6 km","mis":"M4-2-u3-X11"},{"t":"1.16 km","mis":"M4-2-u3-X10"},{"t":"1.2 km","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 9 + 7 = 16 — 6을 쓰고 일의 자리로 1을 받아올려요.","1.9 + 0.7 = 2.6 km예요."],"variant_rule":{"alt":[{"stem":"모은 재활용 종이의 무게는 2.8 kg이고, 유리의 무게는 종이의 무게보다 0.4 kg 더 무거워요. 모은 재활용 유리의 무게는 몇 kg인가요?","options":[{"t":"3.2 kg","correct":true},{"t":"2.2 kg","mis":"M4-2-u3-X11"},{"t":"2.12 kg","mis":"M4-2-u3-X10"},{"t":"2.4 kg","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 8 + 4 = 12 — 2를 쓰고 일의 자리로 1을 받아올려요.","2.8 + 0.4 = 3.2 kg이에요."]},{"stem":"채원이의 가방 무게는 1.5 kg이고, 은비의 가방 무게는 채원이의 가방 무게보다 0.7 kg 더 무거워요. 은비의 가방 무게는 몇 kg인가요?","options":[{"t":"2.2 kg","correct":true},{"t":"1.2 kg","mis":"M4-2-u3-X11"},{"t":"1.12 kg","mis":"M4-2-u3-X10"},{"t":"0.8 kg","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 5 + 7 = 12 — 2를 쓰고 일의 자리로 1을 받아올려요.","1.5 + 0.7 = 2.2 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
