INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#9','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',2,'error','auto','지도서 오류 — 0.9 + 0.7 = 0.16 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X10','M4-2-u3-X11','M4-2-u3-X12']::text[],false,'{"seq":9,"concept":"M4-2-u3-C5","difficulty":2,"kind":"error","stem":"지도서 오류 — 0.9 + 0.7 = 0.16 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 자리의 합이 10이 넘었는데 그 합을 그 자리에 그대로 썼어요","correct":true,"mis_target":"M4-2-u3-X10"},{"t":"받아올림한 1을 윗자리에 더하지 않았어요","mis":"M4-2-u3-X11"},{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","mis":"M4-2-u3-X12"}],"explanation":["틀린 답 0.16: 같은 자리의 합이 10이 넘었는데 그 합을 그 자리에 그대로 썼어요.","소수점을 맞추어 같은 자리끼리 더하고, 받아올림을 생각해요.","바르게 계산하면 0.9 + 0.7 = 1.6이에요."],"asset":{"type":"expr_grid","rows":[["","0",".","9",""],["+","0",".","7",""],["","0",".","1","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_basic#10','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_basic','lesson_basic','M4-2-u3-C5',3,'error','auto','7.8 + 1.9 = 8.7 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X12']::text[],false,'{"seq":10,"concept":"M4-2-u3-C5","difficulty":3,"kind":"error","stem":"7.8 + 1.9 = 8.7 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"받아올림한 1을 윗자리에 더하지 않았어요","correct":true,"mis_target":"M4-2-u3-X11"},{"t":"같은 자리의 합이 10이 넘었는데 그 합을 그 자리에 그대로 썼어요","mis":"M4-2-u3-X10"},{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","mis":"M4-2-u3-X12"}],"explanation":["틀린 답 8.7: 받아올림한 1을 윗자리에 더하지 않았어요.","소수점을 맞추어 같은 자리끼리 더하고, 받아올림을 생각해요.","바르게 계산하면 7.8 + 1.9 = 9.7이에요."],"asset":{"type":"expr_grid","rows":[["","7",".","8"],["+","1",".","9"],["","8",".","7"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#1','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',2,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요? ㉠ 1.6 + 3.6 ㉡ 4.3 + 0.6 ㉢ 2.7 + 2.4 ㉣ 3.2 + 1.8',ARRAY['M4-2-u3-X11','M4-2-u3-X20']::text[],false,'{"seq":1,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요? ㉠ 1.6 + 3.6 ㉡ 4.3 + 0.6 ㉢ 2.7 + 2.4 ㉣ 3.2 + 1.8","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M4-2-u3-X11"},{"t":"㉢","mis":"M4-2-u3-X20"},{"t":"㉣","mis":"M4-2-u3-X20"}],"explanation":["㉠ 5.2, ㉡ 4.9, ㉢ 5.1, ㉣ 5예요.","받아올림을 빠뜨리면 ㉡이 가장 커 보여요.","가장 큰 것은 ㉠ 1.6 + 3.6 = 5.2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#2','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',2,'sa','auto','1.7 + 3.8을 계산하면 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u3-C5","difficulty":2,"kind":"sa","stem":"1.7 + 3.8을 계산하면 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["1.7은 0.1이 17개, 3.8은 0.1이 38개예요.","17 + 38 = 55예요.","1.7 + 3.8 = 5.5 — 0.1이 55개예요."],"variant_rule":{"alt":[{"stem":"2.4 + 7.9를 계산하면 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["103"],"explanation":["2.4는 0.1이 24개, 7.9는 0.1이 79개예요.","24 + 79 = 103이에요.","2.4 + 7.9 = 10.3 — 0.1이 103개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#3','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',3,'mc','auto','지유의 의견 — 「1.3 + 0.9 ○ 1.□ + 0.1」에서 □에 1부터 9까지 하나씩 넣어 보면 어떨까? ○ 안에 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X18']::text[],false,'{"seq":3,"concept":"M4-2-u3-C5","difficulty":3,"kind":"mc","stem":"지유의 의견 — 「1.3 + 0.9 ○ 1.□ + 0.1」에서 □에 1부터 9까지 하나씩 넣어 보면 어떨까? ○ 안에 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X11"},{"t":"=","mis":"M4-2-u3-X18"},{"t":"알 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["1.3 + 0.9 = 2.2예요.","□에 가장 큰 수 9를 넣어도 1.9 + 0.1 = 2예요.","그래서 1부터 9까지 넣어 보지 않아도 1.3 + 0.9가 항상 더 커요(>)."],"asset":{"type":"speech","turns":[{"who":"지유","text":"□에 1부터 9까지 하나씩 넣어 보면 어떨까?"},{"who":"나","text":"1부터 9까지 하나씩 넣어 볼 필요가 없어. 왜냐하면 …"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#4','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',3,'mc','auto','학교에서 공원까지의 거리는 3.4 km이고, 공원에서 시장까지의 거리는 6.2 km예요. 학교에서 공원을 지나 시장까지 간 거리는 몇 km인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":4,"concept":"M4-2-u3-C5","difficulty":3,"kind":"mc","stem":"학교에서 공원까지의 거리는 3.4 km이고, 공원에서 시장까지의 거리는 6.2 km예요. 학교에서 공원을 지나 시장까지 간 거리는 몇 km인가요?","options":[{"t":"9.6 km","correct":true},{"t":"2.8 km","mis":"M4-2-u3-X16"},{"t":"96 km","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 34 + 62 = 96이에요.","3.4 + 6.2 = 9.6 km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#5','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',3,'sa','auto','3.8 + 4.9를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u3-C5","difficulty":3,"kind":"sa","stem":"3.8 + 4.9를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 8 + 9 = 17 — 7을 쓰고 일의 자리로 1을 받아올려요.","3.8 + 4.9 = 8.7 — ?는 일의 자리 숫자 8이에요."],"asset":{"type":"expr_grid","rows":[["","3",".","8"],["+","4",".","9"],["","?",".","7"]]},"variant_rule":{"alt":[{"stem":"2.4 + 7.9를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 4 + 9 = 13 — 3을 쓰고 일의 자리로 1을 받아올려요.","2.4 + 7.9 = 10.3 — ?는 십의 자리 숫자 1이에요."],"asset":{"type":"expr_grid","rows":[["","","2",".","4"],["+","","7",".","9"],["","?","0",".","3"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#6','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',3,'mc','auto','이야기 만들기 — 길이가 1.3 m인 끈과 1.2 m인 끈을 겹치지 않게 이어 붙였어요. 이은 끈의 길이는 모두 몇 m인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":6,"concept":"M4-2-u3-C5","difficulty":3,"kind":"mc","stem":"이야기 만들기 — 길이가 1.3 m인 끈과 1.2 m인 끈을 겹치지 않게 이어 붙였어요. 이은 끈의 길이는 모두 몇 m인가요?","options":[{"t":"2.5 m","correct":true},{"t":"0.1 m","mis":"M4-2-u3-X16"},{"t":"25 m","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 13 + 12 = 25예요.","1.3 + 1.2 = 2.5 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#7','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',3,'ox','auto','「소수 한 자리 수의 덧셈은 소수점의 위치를 맞추어 자연수의 덧셈과 같은 방법으로 받아올림을 생각하여 계산해요.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M4-2-u3-X10']::text[],false,'{"seq":7,"concept":"M4-2-u3-C5","difficulty":3,"kind":"ox","stem":"「소수 한 자리 수의 덧셈은 소수점의 위치를 맞추어 자연수의 덧셈과 같은 방법으로 받아올림을 생각하여 계산해요.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"O","reason_options":[{"t":"0.1이 10개 모이면 1이 되므로 자연수처럼 받아올림하면 돼요","correct":true},{"t":"소수는 받아올림을 하지 않고 같은 자리의 합을 그대로 써요","mis":"M4-2-u3-X10"}],"mis":"M4-2-u3-X10","explanation":["세로로 쓸 때는 소수점의 위치를 맞추어요.","소수 첫째 자리의 합이 10이면 일의 자리로 1을 받아올려요.","1.7 + 0.6 = 2.3 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#8','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',4,'essay','teacher','0.3 + 0.5를 모눈종이를 이용하는 방법과 0.1의 개수를 이용하는 방법으로 각각 계산하고 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C5","difficulty":4,"kind":"essay","stem":"0.3 + 0.5를 모눈종이를 이용하는 방법과 0.1의 개수를 이용하는 방법으로 각각 계산하고 설명해 보세요.","answer_guide":{"answer":"모눈종이: 한 칸이 0.1이므로 0.3은 3칸, 0.5는 5칸을 색칠하면 모두 8칸이므로 0.3 + 0.5 = 0.8이다. 0.1의 개수: 0.3은 0.1이 3개, 0.5는 0.1이 5개이므로 0.3 + 0.5는 0.1이 8개인 0.8이다.","scoring_points":["모눈종이로 8칸을 설명했는가","0.1의 개수(3 + 5 = 8)로 설명했는가","0.8을 바르게 구했는가"]},"explanation":["모눈종이 한 칸은 0.1이에요.","3칸 + 5칸 = 8칸이에요.","0.3 + 0.5 = 0.8이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,10],[0,10]],"hi":true},{"p":[[1,0],[2,0],[2,10],[1,10]],"hi":true},{"p":[[2,0],[3,0],[3,10],[2,10]],"hi":true},{"p":[[3,0],[4,0],[4,10],[3,10]],"hi":true},{"p":[[4,0],[5,0],[5,10],[4,10]],"hi":true},{"p":[[5,0],[6,0],[6,10],[5,10]],"hi":true},{"p":[[6,0],[7,0],[7,10],[6,10]],"hi":true},{"p":[[7,0],[8,0],[8,10],[7,10]],"hi":true},{"p":[[8,0],[9,0],[9,10],[8,10]]},{"p":[[9,0],[10,0],[10,10],[9,10]]}],"u":16}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#9','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',4,'essay','teacher','1.7 + 0.6을 수직선을 이용하는 방법과 세로로 계산하는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C5","difficulty":4,"kind":"essay","stem":"1.7 + 0.6을 수직선을 이용하는 방법과 세로로 계산하는 방법으로 설명해 보세요.","answer_guide":{"answer":"수직선: 작은 눈금 한 칸이 0.1이므로 0에서 1.7만큼 간 다음 0.6만큼 오른쪽으로 더 가면 2.3이다. 세로: 소수점의 위치를 맞추어 쓰고 소수 첫째 자리 7 + 6 = 13에서 3을 쓰고 일의 자리로 1을 받아올려 1 + 1 = 2이므로 2.3이다.","scoring_points":["수직선에서 0.6만큼 더 간 곳 2.3을 썼는가","소수점을 맞추어 세로로 썼는가","받아올림을 바르게 설명했는가"]},"explanation":["수직선의 작은 눈금 한 칸은 0.1이에요.","7 + 6 = 13 — 3을 쓰고 1을 받아올려요.","1.7 + 0.6 = 2.3이에요."],"asset":{"type":"expr_grid","rows":[["","1",".","7"],["+","0",".","6"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L06_challenge#10','math',4,2,'u3','L06','tb_g4_2_math_u3_L06_challenge','lesson_challenge','M4-2-u3-C5',4,'essay','teacher','3.4 + 6.2에 알맞은 생활 속 문제를 만들고 해결해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C5","difficulty":4,"kind":"essay","stem":"3.4 + 6.2에 알맞은 생활 속 문제를 만들고 해결해 보세요.","answer_guide":{"answer":"예: 학교에서 공원까지의 거리는 3.4 km이고 공원에서 시장까지의 거리는 6.2 km이다. 학교에서 공원을 지나 시장까지 간 거리는 몇 km일까? 3.4 + 6.2 = 9.6이므로 9.6 km이다.","scoring_points":["3.4 + 6.2가 되는 생활 속 상황을 만들었는가","묻는 것이 덧셈(모두·지나서)으로 분명한가","9.6을 바르게 구했는가"]},"explanation":["두 양을 모으는 상황이면 덧셈이에요.","3.4 + 6.2 — 0.1이 34개 + 62개 = 96개예요.","3.4 + 6.2 = 9.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
