INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_basic#4','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_basic','lesson_basic','M4-2-u3-C6',1,'mc','auto','수직선에서 0부터 0.84만큼 오른쪽으로 간 다음 0.3만큼 오른쪽으로 더 갔어요. 0.84 + 0.3은 얼마인가요?',ARRAY['M4-2-u3-X10','M4-2-u3-X12','M4-2-u3-X16']::text[],false,'{"seq":4,"concept":"M4-2-u3-C6","difficulty":1,"kind":"mc","stem":"수직선에서 0부터 0.84만큼 오른쪽으로 간 다음 0.3만큼 오른쪽으로 더 갔어요. 0.84 + 0.3은 얼마인가요?","options":[{"t":"1.14","correct":true},{"t":"0.114","mis":"M4-2-u3-X10"},{"t":"0.87","mis":"M4-2-u3-X12"},{"t":"0.54","mis":"M4-2-u3-X16"}],"explanation":["수직선의 작은 눈금 한 칸은 0.01 — 0.3은 작은 눈금 30칸이에요.","소수 첫째 자리: 8 + 3 = 11 — 1을 쓰고 일의 자리로 1을 받아올려요.","0.84 + 0.3 = 1.14예요."],"asset":{"type":"number_line","cells":["0","…","0.84","…","?"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
