INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_basic#8','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_basic','lesson_basic','M4-2-u3-C6',2,'sa','auto','5.13 + 1.24를 계산하면 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u3-C6","difficulty":2,"kind":"sa","stem":"5.13 + 1.24를 계산하면 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["637"],"explanation":["5.13은 0.01이 513개, 1.24는 0.01이 124개예요.","513 + 124 = 637이에요.","5.13 + 1.24 = 6.37 — 0.01이 637개예요."],"variant_rule":{"alt":[{"stem":"1.59 + 2.89를 계산하면 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["448"],"explanation":["1.59는 0.01이 159개, 2.89는 0.01이 289개예요.","159 + 289 = 448이에요.","1.59 + 2.89 = 4.48 — 0.01이 448개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_basic#9','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_basic','lesson_basic','M4-2-u3-C6',2,'error','auto','5.1 + 4.26 = 4.77 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X12','M4-2-u3-X11','M4-2-u3-X10']::text[],false,'{"seq":9,"concept":"M4-2-u3-C6","difficulty":2,"kind":"error","stem":"5.1 + 4.26 = 4.77 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림한 1을 윗자리에 더하지 않았어요","mis":"M4-2-u3-X11"},{"t":"같은 자리의 합이 10이 넘었는데 그 합을 그 자리에 그대로 썼어요","mis":"M4-2-u3-X10"}],"explanation":["틀린 답 4.77: 소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요.","소수점을 맞추어 같은 자리끼리 더하고, 받아올림을 생각해요.","바르게 계산하면 5.1 + 4.26 = 9.36이에요."],"asset":{"type":"expr_grid","rows":[["","","5",".","1"],["+","4",".","2","6"],["","4",".","7","7"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_basic#10','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_basic','lesson_basic','M4-2-u3-C6',3,'error','auto','2.53 + 0.69 = 2.12 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X12','M4-2-u3-X10']::text[],false,'{"seq":10,"concept":"M4-2-u3-C6","difficulty":3,"kind":"error","stem":"2.53 + 0.69 = 2.12 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"받아올림한 1을 윗자리에 더하지 않았어요","correct":true,"mis_target":"M4-2-u3-X11"},{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","mis":"M4-2-u3-X12"},{"t":"같은 자리의 합이 10이 넘었는데 그 합을 그 자리에 그대로 썼어요","mis":"M4-2-u3-X10"}],"explanation":["틀린 답 2.12: 받아올림한 1을 윗자리에 더하지 않았어요.","소수점을 맞추어 같은 자리끼리 더하고, 받아올림을 생각해요.","바르게 계산하면 2.53 + 0.69 = 3.22예요."],"asset":{"type":"expr_grid","rows":[["","2",".","5","3"],["+","0",".","6","9"],["","2",".","1","2"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#1','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',2,'mc','auto','3.01, 2.99, 3.1 가운데 가장 큰 수와 가장 작은 수의 합은 얼마인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X12','M4-2-u3-X17']::text[],false,'{"seq":1,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"3.01, 2.99, 3.1 가운데 가장 큰 수와 가장 작은 수의 합은 얼마인가요?","options":[{"t":"6.09","correct":true},{"t":"6","mis":"M4-2-u3-X07"},{"t":"3.3","mis":"M4-2-u3-X12"},{"t":"6.11","mis":"M4-2-u3-X17"}],"explanation":["가장 큰 수는 3.1, 가장 작은 수는 2.99예요(3.01 < 3.1).","자리를 맞추면 3.10 + 2.99예요.","3.1 + 2.99 = 6.09예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#2','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',2,'mc','auto','계산 결과를 비교하여 ○ 안에 알맞은 것을 고르세요. 6.32 + 4.09 ○ 4.1 + 6.31',ARRAY['M4-2-u3-X12','M4-2-u3-X21']::text[],false,'{"seq":2,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"계산 결과를 비교하여 ○ 안에 알맞은 것을 고르세요. 6.32 + 4.09 ○ 4.1 + 6.31","options":[{"t":"=","correct":true},{"t":">","mis":"M4-2-u3-X12"},{"t":"<","mis":"M4-2-u3-X21"}],"explanation":["6.32 + 4.09 = 10.41이에요.","4.1 + 6.31 = 10.41이에요.","두 계산 결과가 같아요(=)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#3','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',3,'sa','auto','5.□6 + 3.41 = □.17 — 앞의 □(소수 첫째 자리)에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u3-C6","difficulty":3,"kind":"sa","stem":"5.□6 + 3.41 = □.17 — 앞의 □(소수 첫째 자리)에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["소수 둘째 자리: 6 + 1 = 7이에요.","소수 첫째 자리: □ + 4 = 11이어야 1을 쓰고 받아올려요 — □ = 7.","5.76 + 3.41 = 9.17이에요."],"asset":{"type":"expr_grid","rows":[["","5",".","?","6"],["+","3",".","4","1"],["","□",".","1","7"]]},"variant_rule":{"alt":[{"stem":"5.□6 + 3.41 = □.17 — 뒤의 □(일의 자리)에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["소수 첫째 자리에서 일의 자리로 1을 받아올렸어요.","일의 자리: 1 + 5 + 3 = 9예요.","5.76 + 3.41 = 9.17 — □ = 9예요."],"asset":{"type":"expr_grid","rows":[["","5",".","□","6"],["+","3",".","4","1"],["","?",".","1","7"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#4','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',3,'mc','auto','재활용 종이를 모았더니 신문지의 무게는 2.16 kg이고, 종이 상자의 무게는 4.82 kg이었어요. 모은 재활용 종이의 무게는 모두 몇 kg인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":4,"concept":"M4-2-u3-C6","difficulty":3,"kind":"mc","stem":"재활용 종이를 모았더니 신문지의 무게는 2.16 kg이고, 종이 상자의 무게는 4.82 kg이었어요. 모은 재활용 종이의 무게는 모두 몇 kg인가요?","options":[{"t":"6.98 kg","correct":true},{"t":"2.66 kg","mis":"M4-2-u3-X16"},{"t":"698 kg","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.01의 개수로 보면 216 + 482 = 698이에요.","2.16 + 4.82 = 6.98 kg이에요."],"variant_rule":{"alt":[{"stem":"물건을 담은 장바구니의 무게가 1.5 kg이었어요. 장바구니에 과일 1.28 kg을 더 담았다면 장바구니의 무게는 모두 몇 kg인가요?","options":[{"t":"2.78 kg","correct":true},{"t":"1.43 kg","mis":"M4-2-u3-X12"},{"t":"0.22 kg","mis":"M4-2-u3-X16"},{"t":"278 kg","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.01의 개수로 보면 150 + 128 = 278이에요.","1.5 + 1.28 = 2.78 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#5','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',3,'sa','auto','수학에 퐁당 — 1.59 + 2.89를 0.01의 개수를 이용하여 구하려고 해요. 1.59 + 2.89는 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u3-C6","difficulty":3,"kind":"sa","stem":"수학에 퐁당 — 1.59 + 2.89를 0.01의 개수를 이용하여 구하려고 해요. 1.59 + 2.89는 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["448"],"explanation":["1.59는 0.01이 159개, 2.89는 0.01이 289개예요.","159 + 289 = 448이에요.","1.59 + 2.89는 0.01이 448개 — 4.48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#6','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',3,'error','auto','3.09 + 1.07 = 4.016 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X10','M4-2-u3-X12','M4-2-u3-X11']::text[],false,'{"seq":6,"concept":"M4-2-u3-C6","difficulty":3,"kind":"error","stem":"3.09 + 1.07 = 4.016 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 자리의 합이 10이 넘었는데 그 합을 그 자리에 그대로 썼어요","correct":true,"mis_target":"M4-2-u3-X10"},{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","mis":"M4-2-u3-X12"},{"t":"받아올림한 1을 윗자리에 더하지 않았어요","mis":"M4-2-u3-X11"}],"explanation":["틀린 답 4.016: 같은 자리의 합이 10이 넘었는데 그 합을 그 자리에 그대로 썼어요.","소수점을 맞추어 같은 자리끼리 더하고, 받아올림을 생각해요.","바르게 계산하면 3.09 + 1.07 = 4.16이에요."],"asset":{"type":"expr_grid","rows":[["","3",".","0","9",""],["+","1",".","0","7",""],["","4",".","0","1","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#7','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',3,'mc','auto','5.28 + 6.94를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":7,"concept":"M4-2-u3-C6","difficulty":3,"kind":"mc","stem":"5.28 + 6.94를 계산한 값은 얼마인가요?","options":[{"t":"12.22","correct":true},{"t":"11.12","mis":"M4-2-u3-X11"},{"t":"1.66","mis":"M4-2-u3-X16"},{"t":"1222","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 8 + 4 = 12 — 2를 쓰고 소수 첫째 자리로 1을 받아올려요.","5.28 + 6.94 = 12.22예요."],"asset":{"type":"expr_grid","rows":[["","","5",".","2","8"],["+","","6",".","9","4"],["","?","?",".","?","?"]]},"variant_rule":{"alt":[{"stem":"2.62 + 1.27을 계산한 값은 얼마인가요?","options":[{"t":"3.89","correct":true},{"t":"1.35","mis":"M4-2-u3-X16"},{"t":"389","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.01의 개수로 보면 262 + 127 = 389예요.","2.62 + 1.27 = 3.89예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#8','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',4,'essay','teacher','질문 — 소수의 덧셈을 세로로 써서 계산할 때 수를 오른쪽 끝에 맞추어 쓰면 왜 안 되는지 5.1 + 4.26을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"질문 — 소수의 덧셈을 세로로 써서 계산할 때 수를 오른쪽 끝에 맞추어 쓰면 왜 안 되는지 5.1 + 4.26을 예로 들어 설명해 보세요.","answer_guide":{"answer":"오른쪽 끝을 맞추면 5.1의 1(소수 첫째 자리)과 4.26의 6(소수 둘째 자리)처럼 자릿값이 다른 숫자끼리 같은 줄에 와서 4.77처럼 틀린 답이 나온다. 같은 자리 수끼리 더해야 하므로 소수점을 기준으로 맞추어 쓰면 5.1 + 4.26 = 9.36이다.","scoring_points":["자릿값이 다른 숫자끼리 더해진다고 썼는가","소수점을 맞추어야 한다고 썼는가","9.36을 바르게 구했는가"]},"explanation":["오른쪽 끝을 맞추면 4.77이라는 틀린 답이 나와요.","소수점을 맞추면 5.10 + 4.26이에요.","5.1 + 4.26 = 9.36이에요."],"asset":{"type":"expr_grid","rows":[["","","5",".","1"],["+","4",".","2","6"],["","4",".","7","7"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#9','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',4,'essay','teacher','수학에 퐁당 — 1.59 + 2.89를 0.01의 개수를 이용하는 방법과 세로로 계산하는 방법, 두 가지로 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"수학에 퐁당 — 1.59 + 2.89를 0.01의 개수를 이용하는 방법과 세로로 계산하는 방법, 두 가지로 구해 보세요.","answer_guide":{"answer":"방법 1: 1.59는 0.01이 159개, 2.89는 0.01이 289개이다. 1.59 + 2.89는 0.01이 448개이므로 4.48이다. 방법 2: 소수점을 맞추어 세로로 쓰고 소수 둘째 자리 9 + 9 = 18에서 1을 받아올리고, 소수 첫째 자리 1 + 5 + 8 = 14에서 1을 받아올려 1 + 1 + 2 = 4이므로 4.48이다.","scoring_points":["0.01의 개수로 448개를 구했는가","세로 계산에서 받아올림을 두 번 바르게 했는가","4.48을 구했는가"]},"explanation":["159 + 289 = 448이에요.","소수 둘째 자리와 소수 첫째 자리에서 받아올림이 있어요.","1.59 + 2.89 = 4.48이에요."],"asset":{"type":"expr_grid","rows":[["","1",".","5","9"],["+","2",".","8","9"],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L07_challenge#10','math',4,2,'u3','L07','tb_g4_2_math_u3_L07_challenge','lesson_challenge','M4-2-u3-C6',4,'essay','teacher','0.84 + 0.3을 수직선을 이용하는 방법과 세로로 계산하는 방법으로 설명해 보세요. 자릿수가 다른 두 소수를 더할 때 조심할 점도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"0.84 + 0.3을 수직선을 이용하는 방법과 세로로 계산하는 방법으로 설명해 보세요. 자릿수가 다른 두 소수를 더할 때 조심할 점도 써 보세요.","answer_guide":{"answer":"수직선: 작은 눈금 한 칸이 0.01이므로 0에서 0.84만큼 간 다음 0.3만큼 오른쪽으로 더 가면 1.14이다. 세로: 소수점을 맞추어 0.84 + 0.30으로 쓰고 소수 첫째 자리 8 + 3 = 11에서 1을 받아올려 1.14이다. 자릿수가 다를 때 오른쪽 끝을 맞추면 0.87처럼 틀리므로 소수점을 맞추어야 한다.","scoring_points":["수직선으로 1.14를 설명했는가","소수점을 맞추고 받아올림을 설명했는가","오른쪽 끝을 맞추면 안 된다고 썼는가"]},"explanation":["0.3은 작은 눈금 30칸이에요.","8 + 3 = 11 — 1을 쓰고 일의 자리로 1을 받아올려요.","0.84 + 0.3 = 1.14예요."],"asset":{"type":"expr_grid","rows":[["","0",".","8","4"],["+","0",".","3",""],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#1','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',1,'sa','auto','수의사가 소독약 1.3 L 중에서 0.2 L를 사용했어요. 모눈종이에 1.3만큼 색칠하고 0.2만큼 ×표 했어요. 1.3 − 0.2는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u3-C7","difficulty":1,"kind":"sa","stem":"수의사가 소독약 1.3 L 중에서 0.2 L를 사용했어요. 모눈종이에 1.3만큼 색칠하고 0.2만큼 ×표 했어요. 1.3 − 0.2는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["1.3은 0.1이 13개, 0.2는 0.1이 2개예요.","13칸에서 2칸을 ×표 하면 11칸이 남아요.","1.3 − 0.2는 0.1이 11개 — 1.1이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[10,0],[10,10],[0,10]],"hi":true},{"p":[[11,0],[12,0],[12,10],[11,10]],"hi":true},{"p":[[12,0],[13,0],[13,10],[12,10]],"hi":true,"n":"×"},{"p":[[13,0],[14,0],[14,10],[13,10]],"hi":true,"n":"×"},{"p":[[14,0],[15,0],[15,10],[14,10]]},{"p":[[15,0],[16,0],[16,10],[15,10]]},{"p":[[16,0],[17,0],[17,10],[16,10]]},{"p":[[17,0],[18,0],[18,10],[17,10]]},{"p":[[18,0],[19,0],[19,10],[18,10]]},{"p":[[19,0],[20,0],[20,10],[19,10]]},{"p":[[20,0],[21,0],[21,10],[20,10]]}],"u":14},"variant_rule":{"alt":[{"stem":"수의사가 소독약 1.5 L 중에서 0.3 L를 사용했어요. 모눈종이에 1.5만큼 색칠하고 0.3만큼 ×표 했어요. 1.5 − 0.3은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1.5는 0.1이 15개, 0.3은 0.1이 3개예요.","15칸에서 3칸을 ×표 하면 12칸이 남아요.","1.5 − 0.3은 0.1이 12개 — 1.2예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[10,0],[10,10],[0,10]],"hi":true},{"p":[[11,0],[12,0],[12,10],[11,10]],"hi":true},{"p":[[12,0],[13,0],[13,10],[12,10]],"hi":true},{"p":[[13,0],[14,0],[14,10],[13,10]],"hi":true,"n":"×"},{"p":[[14,0],[15,0],[15,10],[14,10]],"hi":true,"n":"×"},{"p":[[15,0],[16,0],[16,10],[15,10]],"hi":true,"n":"×"},{"p":[[16,0],[17,0],[17,10],[16,10]]},{"p":[[17,0],[18,0],[18,10],[17,10]]},{"p":[[18,0],[19,0],[19,10],[18,10]]},{"p":[[19,0],[20,0],[20,10],[19,10]]},{"p":[[20,0],[21,0],[21,10],[20,10]]}],"u":14}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#2','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',1,'mc','auto','소독약 1.3 L 중에서 0.2 L를 사용했어요. 남은 소독약은 몇 L인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":2,"concept":"M4-2-u3-C7","difficulty":1,"kind":"mc","stem":"소독약 1.3 L 중에서 0.2 L를 사용했어요. 남은 소독약은 몇 L인가요?","options":[{"t":"1.1 L","correct":true},{"t":"1.5 L","mis":"M4-2-u3-X16"},{"t":"11 L","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 13 − 2 = 11이에요.","1.3 − 0.2 = 1.1 L예요."],"variant_rule":{"alt":[{"stem":"소독약 1.5 L 중에서 0.3 L를 사용했어요. 남은 소독약은 몇 L인가요?","options":[{"t":"1.2 L","correct":true},{"t":"1.8 L","mis":"M4-2-u3-X16"},{"t":"12 L","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 15 − 3 = 12예요.","1.5 − 0.3 = 1.2 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#3','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',1,'mc','auto','0.8 − 0.6을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":3,"concept":"M4-2-u3-C7","difficulty":1,"kind":"mc","stem":"0.8 − 0.6을 계산한 값은 얼마인가요?","options":[{"t":"0.2","correct":true},{"t":"1.4","mis":"M4-2-u3-X16"},{"t":"2","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 8 − 6 = 2예요.","0.8 − 0.6 = 0.2예요."],"variant_rule":{"alt":[{"stem":"0.8 − 0.4를 계산한 값은 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"1.2","mis":"M4-2-u3-X16"},{"t":"4","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 8 − 4 = 4예요.","0.8 − 0.4 = 0.4예요."]},{"stem":"0.9 − 0.1을 계산한 값은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1","mis":"M4-2-u3-X16"},{"t":"8","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 9 − 1 = 8이에요.","0.9 − 0.1 = 0.8이에요."]},{"stem":"1.2 − 0.7을 계산한 값은 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"1.5","mis":"M4-2-u3-X13"},{"t":"1.9","mis":"M4-2-u3-X16"},{"t":"5","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 2에서 7을 뺄 수 없어 일의 자리에서 받아내림해요 — 12 − 7 = 5.","1.2 − 0.7 = 0.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#4','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',1,'mc','auto','수직선에서 0부터 2.4만큼 오른쪽으로 간 다음 다시 1.8만큼 왼쪽으로 갔어요. 2.4 − 1.8은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":4,"concept":"M4-2-u3-C7","difficulty":1,"kind":"mc","stem":"수직선에서 0부터 2.4만큼 오른쪽으로 간 다음 다시 1.8만큼 왼쪽으로 갔어요. 2.4 − 1.8은 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"1.4","mis":"M4-2-u3-X13"},{"t":"1.6","mis":"M4-2-u3-X14"},{"t":"4.2","mis":"M4-2-u3-X16"}],"explanation":["수직선의 작은 눈금 한 칸은 0.1 — 2.4에서 왼쪽으로 18칸 가요.","소수 첫째 자리: 4에서 8을 뺄 수 없어 일의 자리에서 받아내림해요 — 14 − 8 = 6.","2.4 − 1.8 = 0.6이에요."],"asset":{"type":"number_line","cells":["0","…","?","…","2.4"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#5','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',2,'sa','auto','2.4 − 1.8을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u3-C7","difficulty":2,"kind":"sa","stem":"2.4 − 1.8을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 4에서 8을 뺄 수 없어 일의 자리에서 받아내림해요 — 14 − 8 = 6.","2.4 − 1.8 = 0.6 — ?는 소수 첫째 자리 숫자 6이에요."],"asset":{"type":"expr_grid","rows":[["","2",".","4"],["−","1",".","8"],["","0",".","?"]]},"variant_rule":{"alt":[{"stem":"7.4 − 1.9를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 4에서 9를 뺄 수 없어 일의 자리에서 받아내림해요 — 14 − 9 = 5.","7.4 − 1.9 = 5.5 — ?는 일의 자리 숫자 5예요."],"asset":{"type":"expr_grid","rows":[["","7",".","4"],["−","1",".","9"],["","?",".","5"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#6','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',2,'mc','auto','7.4 − 1.9를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":6,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"7.4 − 1.9를 계산한 값은 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"6.5","mis":"M4-2-u3-X13"},{"t":"9.3","mis":"M4-2-u3-X16"},{"t":"55","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 4에서 9를 뺄 수 없어 일의 자리에서 받아내림해요 — 14 − 9 = 5.","7.4 − 1.9 = 5.5예요."],"asset":{"type":"expr_grid","rows":[["","7",".","4"],["−","1",".","9"],["","?",".","?"]]},"variant_rule":{"alt":[{"stem":"6.5 − 5.1을 계산한 값은 얼마인가요?","options":[{"t":"1.4","correct":true},{"t":"11.6","mis":"M4-2-u3-X16"},{"t":"14","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 65 − 51 = 14예요.","6.5 − 5.1 = 1.4예요."],"asset":{"type":"expr_grid","rows":[["","6",".","5"],["−","5",".","1"],["","?",".","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#7','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',2,'mc','auto','참외가 들어 있는 바구니의 무게는 3.2 kg이에요. 빈 바구니의 무게가 0.3 kg이라면 참외의 무게는 몇 kg인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":7,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"참외가 들어 있는 바구니의 무게는 3.2 kg이에요. 빈 바구니의 무게가 0.3 kg이라면 참외의 무게는 몇 kg인가요?","options":[{"t":"2.9 kg","correct":true},{"t":"3.1 kg","mis":"M4-2-u3-X13"},{"t":"3.9 kg","mis":"M4-2-u3-X14"},{"t":"3.5 kg","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 2에서 3을 뺄 수 없어 일의 자리에서 받아내림해요 — 12 − 3 = 9.","3.2 − 0.3 = 2.9 kg이에요."],"variant_rule":{"alt":[{"stem":"물 로켓을 만들어 비행시간을 재었어요. 수진이의 로켓은 3.4초, 은우의 로켓은 4.1초였어요. 두 사람이 날린 로켓의 비행시간의 차는 몇 초인가요?","options":[{"t":"0.7초","correct":true},{"t":"1.3초","mis":"M4-2-u3-X13"},{"t":"1.7초","mis":"M4-2-u3-X14"},{"t":"7.5초","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 1에서 4를 뺄 수 없어 일의 자리에서 받아내림해요 — 11 − 4 = 7.","4.1 − 3.4 = 0.7초예요."]},{"stem":"50 m 달리기 연습에서 서준이는 10.5초, 도윤이는 11.2초를 기록했어요. 서준이는 도윤이보다 몇 초 더 빠른가요?","options":[{"t":"0.7초","correct":true},{"t":"1.3초","mis":"M4-2-u3-X13"},{"t":"1.7초","mis":"M4-2-u3-X14"},{"t":"21.7초","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 2에서 5를 뺄 수 없어 일의 자리에서 받아내림해요 — 12 − 5 = 7.","11.2 − 10.5 = 0.7초예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#8','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',2,'mc','auto','8.1 − 2.9를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":8,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"8.1 − 2.9를 계산한 값은 얼마인가요?","options":[{"t":"5.2","correct":true},{"t":"6.8","mis":"M4-2-u3-X13"},{"t":"6.2","mis":"M4-2-u3-X14"},{"t":"11","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 1에서 9를 뺄 수 없어 일의 자리에서 받아내림해요 — 11 − 9 = 2.","8.1 − 2.9 = 5.2예요."],"asset":{"type":"expr_grid","rows":[["","8",".","1"],["−","2",".","9"],["","?",".","?"]]},"variant_rule":{"alt":[{"stem":"4.7 − 0.5를 계산한 값은 얼마인가요?","options":[{"t":"4.2","correct":true},{"t":"5.2","mis":"M4-2-u3-X16"},{"t":"42","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 47 − 5 = 42예요.","4.7 − 0.5 = 4.2예요."],"asset":{"type":"expr_grid","rows":[["","4",".","7"],["−","0",".","5"],["","?",".","?"]]}},{"stem":"7.3 − 4.7을 계산한 값은 얼마인가요?","options":[{"t":"2.6","correct":true},{"t":"3.4","mis":"M4-2-u3-X13"},{"t":"3.6","mis":"M4-2-u3-X14"},{"t":"12","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 3에서 7을 뺄 수 없어 일의 자리에서 받아내림해요 — 13 − 7 = 6.","7.3 − 4.7 = 2.6이에요."],"asset":{"type":"expr_grid","rows":[["","7",".","3"],["−","4",".","7"],["","?",".","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#9','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',2,'match','auto','계산 결과를 찾아 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C7","difficulty":2,"kind":"match","stem":"계산 결과를 찾아 선으로 이어 보세요.","pairs":[{"l":"5.1 − 3.4","r":"1.7"},{"l":"4.9 − 1.2","r":"3.7"},{"l":"7.5 − 4.8","r":"2.7"}],"mis":"M4-2-u3-X14","explanation":["5.1 − 3.4: 소수 첫째 자리에서 받아내림 — 11 − 4 = 7, 4 − 3 = 1 → 1.7.","4.9 − 1.2 = 3.7(받아내림 없음)이에요.","7.5 − 4.8: 15 − 8 = 7, 6 − 4 = 2 → 2.7."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_basic#10','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_basic','lesson_basic','M4-2-u3-C7',3,'mc','auto','계산 결과가 가장 작은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X13']::text[],false,'{"seq":10,"concept":"M4-2-u3-C7","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 작은 것은 어느 것인가요?","options":[{"t":"9.6 − 5.8","correct":true},{"t":"6.7 − 2.6","mis":"M4-2-u3-X17"},{"t":"4.4 − 0.5","mis":"M4-2-u3-X13"}],"explanation":["6.7 − 2.6 = 4.1, 4.4 − 0.5 = 3.9, 9.6 − 5.8 = 3.8이에요.","받아내림을 바르게 해야 크기를 견줄 수 있어요.","가장 작은 것은 9.6 − 5.8 = 3.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#1','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',2,'mc','auto','수 카드 1, 2, 4, 5를 한 번씩만 사용하여 □.□ − □.□ 꼴의 뺄셈식을 만들려고 해요. 차가 가장 큰 뺄셈식은 어느 것인가요?',ARRAY['M4-2-u3-X20','M4-2-u3-X17']::text[],false,'{"seq":1,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"수 카드 1, 2, 4, 5를 한 번씩만 사용하여 □.□ − □.□ 꼴의 뺄셈식을 만들려고 해요. 차가 가장 큰 뺄셈식은 어느 것인가요?","options":[{"t":"5.4 − 1.2","correct":true},{"t":"4.5 − 1.2","mis":"M4-2-u3-X20"},{"t":"5.2 − 1.4","mis":"M4-2-u3-X20"},{"t":"2.4 − 1.5","mis":"M4-2-u3-X17"}],"explanation":["차가 가장 크려면 가장 큰 수에서 가장 작은 수를 빼야 해요.","가장 큰 수 5.4, 가장 작은 수 1.2예요.","5.4 − 1.2 = 4.2 — 차가 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#2','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',2,'sa','auto','7.3 − 4.7을 계산하면 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u3-C7","difficulty":2,"kind":"sa","stem":"7.3 − 4.7을 계산하면 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["7.3은 0.1이 73개, 4.7은 0.1이 47개예요.","73 − 47 = 26이에요.","7.3 − 4.7 = 2.6 — 0.1이 26개예요."],"variant_rule":{"alt":[{"stem":"8.1 − 2.9를 계산하면 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["8.1은 0.1이 81개, 2.9는 0.1이 29개예요.","81 − 29 = 52예요.","8.1 − 2.9 = 5.2 — 0.1이 52개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#3','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'mc','auto','길이가 1.4 m인 끈이 있어요. 그중에서 0.8 m를 사용한다면 남는 끈은 몇 m인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":3,"concept":"M4-2-u3-C7","difficulty":3,"kind":"mc","stem":"길이가 1.4 m인 끈이 있어요. 그중에서 0.8 m를 사용한다면 남는 끈은 몇 m인가요?","options":[{"t":"0.6 m","correct":true},{"t":"1.4 m","mis":"M4-2-u3-X13"},{"t":"1.6 m","mis":"M4-2-u3-X14"},{"t":"2.2 m","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 4에서 8을 뺄 수 없어 일의 자리에서 받아내림해요 — 14 − 8 = 6.","1.4 − 0.8 = 0.6 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#4','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'error','auto','지도서 — 7.4 − 1.9 = 6.5 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X12']::text[],false,'{"seq":4,"concept":"M4-2-u3-C7","difficulty":3,"kind":"error","stem":"지도서 — 7.4 − 1.9 = 6.5 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"뺄 수 없는 자리에서 받아내림하지 않고 큰 숫자에서 작은 숫자를 거꾸로 뺐어요","correct":true,"mis_target":"M4-2-u3-X13"},{"t":"받아내림을 하고도 윗자리에서 1을 빼지 않았어요","mis":"M4-2-u3-X14"},{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","mis":"M4-2-u3-X12"}],"explanation":["틀린 답 6.5: 뺄 수 없는 자리에서 받아내림하지 않고 큰 숫자에서 작은 숫자를 거꾸로 뺐어요.","소수점을 맞추어 같은 자리끼리 빼고, 받아내림을 생각해요.","바르게 계산하면 7.4 − 1.9 = 5.5예요."],"asset":{"type":"expr_grid","rows":[["","7",".","4"],["−","1",".","9"],["","6",".","5"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#5','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'mc','auto','이야기 만들기 — 4.5 L의 물이 있었는데 1.6 L를 마셨어요. 남은 물은 몇 L인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":5,"concept":"M4-2-u3-C7","difficulty":3,"kind":"mc","stem":"이야기 만들기 — 4.5 L의 물이 있었는데 1.6 L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"2.9 L","correct":true},{"t":"3.1 L","mis":"M4-2-u3-X13"},{"t":"3.9 L","mis":"M4-2-u3-X14"},{"t":"6.1 L","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 5에서 6을 뺄 수 없어 일의 자리에서 받아내림해요 — 15 − 6 = 9.","4.5 − 1.6 = 2.9 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#6','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'sa','auto','7.4 − 1.9를 세로로 계산해요. 소수 첫째 자리 4에서 9를 뺄 수 없어 일의 자리에서 받아내림했어요. 받아내림하고 난 일의 자리 숫자는 몇인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u3-C7","difficulty":3,"kind":"sa","stem":"7.4 − 1.9를 세로로 계산해요. 소수 첫째 자리 4에서 9를 뺄 수 없어 일의 자리에서 받아내림했어요. 받아내림하고 난 일의 자리 숫자는 몇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["일의 자리 7에서 1을 소수 첫째 자리로 받아내려요(1 = 0.1이 10개).","일의 자리는 7 − 1 = 6이 돼요.","6 − 1 = 5, 14 − 9 = 5 — 7.4 − 1.9 = 5.5예요."],"asset":{"type":"expr_grid","rows":[["","7",".","4"],["−","1",".","9"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#7','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',3,'ox','auto','「2.4 − 1.8을 세로로 계산할 때 일의 자리에서 받아내림한 1은 0.1이 10개예요.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M4-2-u3-X01']::text[],false,'{"seq":7,"concept":"M4-2-u3-C7","difficulty":3,"kind":"ox","stem":"「2.4 − 1.8을 세로로 계산할 때 일의 자리에서 받아내림한 1은 0.1이 10개예요.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"O","reason_options":[{"t":"1 = 0.1이 10개이므로 소수 첫째 자리는 10 + 4 = 14가 돼요","correct":true},{"t":"받아내림한 1은 0.1이 1개예요","mis":"M4-2-u3-X01"}],"mis":"M4-2-u3-X01","explanation":["1은 0.1이 10개예요.","소수 첫째 자리: 14 − 8 = 6이에요.","일의 자리: 1 − 1 = 0 — 2.4 − 1.8 = 0.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#8','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',4,'essay','teacher','1.3 − 0.2를 모눈종이를 이용하는 방법과 0.1의 개수를 이용하는 방법으로 각각 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C7","difficulty":4,"kind":"essay","stem":"1.3 − 0.2를 모눈종이를 이용하는 방법과 0.1의 개수를 이용하는 방법으로 각각 설명해 보세요.","answer_guide":{"answer":"모눈종이: 한 칸이 0.1이므로 1.3만큼 13칸을 색칠하고 0.2만큼 2칸을 ×표 하면 11칸이 남아 1.1이다. 0.1의 개수: 1.3은 0.1이 13개, 0.2는 0.1이 2개이므로 1.3 − 0.2는 0.1이 11개인 1.1이다.","scoring_points":["모눈종이에서 13칸 중 2칸을 지워 11칸을 설명했는가","0.1의 개수(13 − 2 = 11)로 설명했는가","1.1을 바르게 구했는가"]},"explanation":["모눈종이 한 칸은 0.1이에요.","13칸 − 2칸 = 11칸이에요.","1.3 − 0.2 = 1.1이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[10,0],[10,10],[0,10]],"hi":true},{"p":[[11,0],[12,0],[12,10],[11,10]],"hi":true},{"p":[[12,0],[13,0],[13,10],[12,10]],"hi":true,"n":"×"},{"p":[[13,0],[14,0],[14,10],[13,10]],"hi":true,"n":"×"},{"p":[[14,0],[15,0],[15,10],[14,10]]},{"p":[[15,0],[16,0],[16,10],[15,10]]},{"p":[[16,0],[17,0],[17,10],[16,10]]},{"p":[[17,0],[18,0],[18,10],[17,10]]},{"p":[[18,0],[19,0],[19,10],[18,10]]},{"p":[[19,0],[20,0],[20,10],[19,10]]},{"p":[[20,0],[21,0],[21,10],[20,10]]}],"u":14}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#9','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',4,'essay','teacher','2.4 − 1.8을 수직선을 이용하는 방법과 세로로 계산하는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C7","difficulty":4,"kind":"essay","stem":"2.4 − 1.8을 수직선을 이용하는 방법과 세로로 계산하는 방법으로 설명해 보세요.","answer_guide":{"answer":"수직선: 작은 눈금 한 칸이 0.1이므로 0에서 2.4만큼 오른쪽으로 간 다음 다시 1.8만큼 왼쪽으로 가면 0.6이다. 세로: 소수점을 맞추어 쓰고 소수 첫째 자리 4에서 8을 뺄 수 없으므로 일의 자리에서 받아내림하여 14 − 8 = 6, 일의 자리는 1 − 1 = 0이므로 0.6이다.","scoring_points":["수직선에서 왼쪽으로 1.8만큼 간 곳 0.6을 썼는가","받아내림(14 − 8 = 6)을 설명했는가","0.6을 바르게 구했는가"]},"explanation":["뺄셈은 수직선에서 왼쪽으로 가요.","14 − 8 = 6, 1 − 1 = 0이에요.","2.4 − 1.8 = 0.6이에요."],"asset":{"type":"expr_grid","rows":[["","2",".","4"],["−","1",".","8"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L08_challenge#10','math',4,2,'u3','L08','tb_g4_2_math_u3_L08_challenge','lesson_challenge','M4-2-u3-C7',4,'essay','teacher','1.4 − 0.8에 알맞은 생활 속 문제를 만들고 해결해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C7","difficulty":4,"kind":"essay","stem":"1.4 − 0.8에 알맞은 생활 속 문제를 만들고 해결해 보세요.","answer_guide":{"answer":"예: 길이가 1.4 m인 끈이 있다. 그중에서 0.8 m를 사용한다면 남는 끈은 몇 m일까? 1.4 − 0.8 = 0.6이므로 0.6 m이다.","scoring_points":["1.4 − 0.8이 되는 생활 속 상황을 만들었는가","묻는 것이 뺄셈(남는·차)으로 분명한가","0.6을 바르게 구했는가"]},"explanation":["덜어 내거나 차를 구하는 상황이면 뺄셈이에요.","0.1이 14개 − 8개 = 6개예요.","1.4 − 0.8 = 0.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
