INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_basic#2','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_basic','lesson_basic','M4-2-u3-C8',1,'mc','auto','참수리가 어제는 0.43 m, 오늘은 0.95 m를 날아올랐어요. 오늘은 어제보다 몇 m 더 날아올랐나요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],true,'{"seq":2,"concept":"M4-2-u3-C8","difficulty":1,"kind":"mc","stem":"참수리가 어제는 0.43 m, 오늘은 0.95 m를 날아올랐어요. 오늘은 어제보다 몇 m 더 날아올랐나요?","options":[{"t":"0.52 m","correct":true},{"t":"1.38 m","mis":"M4-2-u3-X16"},{"t":"52 m","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.01의 개수로 보면 95 − 43 = 52예요.","0.95 − 0.43 = 0.52 m예요."],"variant_rule":{"alt":[{"stem":"참수리가 어제는 0.56 m, 오늘은 0.98 m를 날아올랐어요. 오늘은 어제보다 몇 m 더 날아올랐나요?","options":[{"t":"0.42 m","correct":true},{"t":"1.54 m","mis":"M4-2-u3-X16"},{"t":"42 m","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.01의 개수로 보면 98 − 56 = 42예요.","0.98 − 0.56 = 0.42 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
