INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#2','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',2,'mc','auto','계산 결과를 비교하여 ○ 안에 알맞은 것을 고르세요. 5.76 − 2.3 ○ 7.14 − 4.3',ARRAY['M4-2-u3-X12','M4-2-u3-X18']::text[],false,'{"seq":2,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"계산 결과를 비교하여 ○ 안에 알맞은 것을 고르세요. 5.76 − 2.3 ○ 7.14 − 4.3","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X12"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["5.76 − 2.3 = 3.46이에요.","7.14 − 4.3 = 2.84예요.","3.46 > 2.84 — 오른쪽 끝을 맞추면 거꾸로 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#3','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'mc','auto','리본을 선물 포장하는 데에 1.95 m, 꽃 만드는 데에 2.63 m 사용했어요. 리본을 어느 것에 몇 m 더 많이 사용했나요?',ARRAY['M4-2-u3-X17','M4-2-u3-X16','M4-2-u3-X13']::text[],false,'{"seq":3,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"리본을 선물 포장하는 데에 1.95 m, 꽃 만드는 데에 2.63 m 사용했어요. 리본을 어느 것에 몇 m 더 많이 사용했나요?","options":[{"t":"꽃 만들기에 0.68 m","correct":true},{"t":"선물 포장에 0.68 m","mis":"M4-2-u3-X17"},{"t":"꽃 만들기에 4.58 m","mis":"M4-2-u3-X16"},{"t":"꽃 만들기에 1.32 m","mis":"M4-2-u3-X13"}],"explanation":["2.63 > 1.95 — 꽃 만들기에 더 많이 사용했어요.","2.63 − 1.95: 소수 둘째·첫째 자리에서 받아내림해요.","2.63 − 1.95 = 0.68 — 꽃 만들기에 0.68 m 더 사용했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#4','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'mc','auto','㉠과 ㉡의 차는 얼마인가요? ㉠ 0.01이 283개인 수 ㉡ 1이 4개, 0.1이 3개, 0.01이 9개인 수',ARRAY['M4-2-u3-X14','M4-2-u3-X16','M4-2-u3-X20']::text[],false,'{"seq":4,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"㉠과 ㉡의 차는 얼마인가요? ㉠ 0.01이 283개인 수 ㉡ 1이 4개, 0.1이 3개, 0.01이 9개인 수","options":[{"t":"1.56","correct":true},{"t":"2.56","mis":"M4-2-u3-X14"},{"t":"7.22","mis":"M4-2-u3-X16"},{"t":"1.46","mis":"M4-2-u3-X20"}],"explanation":["㉠ 0.01이 283개인 수는 2.83이에요.","㉡ 1이 4개, 0.1이 3개, 0.01이 9개인 수는 4.39예요.","4.39 − 2.83 = 1.56이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#5','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'sa','auto','9.28 − 5.79를 계산하면 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u3-C8","difficulty":3,"kind":"sa","stem":"9.28 − 5.79를 계산하면 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["349"],"explanation":["9.28은 0.01이 928개, 5.79는 0.01이 579개예요.","928 − 579 = 349예요.","9.28 − 5.79 = 3.49 — 0.01이 349개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#6','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'mc','auto','수학에 퐁당 — 서준이가 「나는 7.1에서 2.99 대신 먼저 3을 뺀 다음 0.01을 더했어. 그랬더니 계산 결과가 4.11이야.」라고 했어요. 서준이의 방법에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X18']::text[],false,'{"seq":6,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"수학에 퐁당 — 서준이가 「나는 7.1에서 2.99 대신 먼저 3을 뺀 다음 0.01을 더했어. 그랬더니 계산 결과가 4.11이야.」라고 했어요. 서준이의 방법에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"옳아요 — 2.99는 3보다 0.01 작으므로 3을 빼고 0.01을 더하면 돼요","correct":true},{"t":"옳지 않아요 — 3을 뺀 다음 0.01을 또 빼야 해요","mis":"M4-2-u3-X16"},{"t":"옳지 않아요 — 소수와 자연수는 섞어 뺄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["2.99 = 3 − 0.01이에요.","3을 빼면 0.01을 더 뺀 셈이라 다시 0.01을 더해요.","7.1 − 3 + 0.01 = 4.11 = 7.1 − 2.99 — 옳아요."],"asset":{"type":"speech","turns":[{"who":"서준","text":"나는 7.1에서 2.99 대신 먼저 3을 뺀 다음 0.01을 더했어. 그랬더니 계산 결과가 4.11이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#7','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',3,'mc','auto','지도서 오류 — 21 − 0.65를 바르게 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X15','M4-2-u3-X14']::text[],true,'{"seq":7,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"지도서 오류 — 21 − 0.65를 바르게 계산한 값은 얼마인가요?","options":[{"t":"20.35","correct":true},{"t":"21.65","mis":"M4-2-u3-X15"},{"t":"21.45","mis":"M4-2-u3-X14"}],"explanation":["빼지는 수 21을 21.00으로 보고 소수점을 맞추어요.","소수 둘째·첫째 자리 모두 받아내림해요 — 10 − 5 = 5, 9 − 6 = 3.","21 − 0.65 = 20.35 — 21.65는 0.65를 그대로 내려 쓴 오류예요."],"asset":{"type":"expr_grid","rows":[["","2","1","","",""],["−","","0",".","6","5"],["","2","1",".","6","5"]]},"variant_rule":{"alt":[{"stem":"지도서 오류 — 35.7 − 11.92를 바르게 계산한 값은 얼마인가요?","options":[{"t":"23.78","correct":true},{"t":"23.82","mis":"M4-2-u3-X15"},{"t":"24.22","mis":"M4-2-u3-X13"},{"t":"24.88","mis":"M4-2-u3-X14"}],"explanation":["빼지는 수 35.7을 35.70으로 보고 소수점을 맞추어요.","소수 둘째 자리: 10 − 2 = 8, 소수 첫째 자리: 16 − 9 = 7이에요.","35.7 − 11.92 = 23.78 — 23.82는 2를 그대로 내려 쓴 오류예요."],"asset":{"type":"expr_grid","rows":[["","3","5",".","7",""],["−","1","1",".","9","2"],["","2","3",".","8","2"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#8','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',4,'essay','teacher','35.7 − 11.92를 계산하려고 해요. 35.7을 35.70으로 보면 무엇이 좋은지 설명하고, 받아내림 과정을 써서 답을 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C8","difficulty":4,"kind":"essay","stem":"35.7 − 11.92를 계산하려고 해요. 35.7을 35.70으로 보면 무엇이 좋은지 설명하고, 받아내림 과정을 써서 답을 구해 보세요.","answer_guide":{"answer":"35.7의 소수점 오른쪽 끝에 0을 붙여 35.70으로 써도 크기는 같다. 0을 붙이면 빼는 수와 소수점 아래 자릿수가 같아져 소수 둘째 자리에서 받아내림이 필요하다는 것이 보인다. 소수 둘째 자리 10 − 2 = 8, 소수 첫째 자리 16 − 9 = 7, 일의 자리 4 − 1 = 3, 십의 자리 3 − 1 = 2이므로 35.7 − 11.92 = 23.78이다.","scoring_points":["0을 붙여도 크기가 같다고 썼는가","자릿수를 맞추면 받아내림이 보인다고 썼는가","23.78을 바르게 구했는가"]},"explanation":["35.7 = 35.70이에요.","빈 자리를 0으로 보면 2를 그대로 내려 쓰는 실수를 막아요.","35.7 − 11.92 = 23.78이에요."],"asset":{"type":"expr_grid","rows":[["","3","5",".","7",""],["−","1","1",".","9","2"],["","?","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#9','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',4,'essay','teacher','서준이는 7.1 − 2.99를 「7.1에서 3을 뺀 다음 0.01을 더해서」 4.11로 구했어요. 이 방법이 옳은지 판단하고 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C8","difficulty":4,"kind":"essay","stem":"서준이는 7.1 − 2.99를 「7.1에서 3을 뺀 다음 0.01을 더해서」 4.11로 구했어요. 이 방법이 옳은지 판단하고 그 까닭을 써 보세요.","answer_guide":{"answer":"옳다. 2.99는 3보다 0.01만큼 더 작으므로 7.1에서 3을 빼면 0.01을 더 뺀 것이 된다. 그래서 7.1 − 3 = 4.1에 0.01을 더하면 4.11이고, 이것은 7.1 − 2.99 = 4.11과 같다.","scoring_points":["옳다고 판단했는가","2.99가 3보다 0.01 작다고 썼는가","0.01을 더해야 하는 까닭을 썼는가"]},"explanation":["2.99 = 3 − 0.01이에요.","7.1 − 3 = 4.1이에요.","4.1 + 0.01 = 4.11 — 7.1 − 2.99 = 4.11과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L09_challenge#10','math',4,2,'u3','L09','tb_g4_2_math_u3_L09_challenge','lesson_challenge','M4-2-u3-C8',4,'essay','teacher','1.2 − 0.36을 수직선을 이용하는 방법과 세로로 계산하는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C8","difficulty":4,"kind":"essay","stem":"1.2 − 0.36을 수직선을 이용하는 방법과 세로로 계산하는 방법으로 설명해 보세요.","answer_guide":{"answer":"수직선: 작은 눈금 한 칸이 0.01이므로 0에서 1.2만큼 간 다음 다시 0.36만큼 왼쪽으로 가면 0.84이다. 세로: 1.2를 1.20으로 보고 소수점을 맞추어 쓴다. 소수 둘째 자리 0에서 6을 뺄 수 없어 받아내림하여 10 − 6 = 4, 소수 첫째 자리 11 − 3 = 8, 일의 자리 0이므로 0.84이다.","scoring_points":["수직선에서 왼쪽으로 0.36만큼 간 곳 0.84를 썼는가","1.2를 1.20으로 보고 받아내림을 설명했는가","0.84를 바르게 구했는가"]},"explanation":["1.2 = 1.20이에요.","10 − 6 = 4, 11 − 3 = 8이에요.","1.2 − 0.36 = 0.84예요."],"asset":{"type":"expr_grid","rows":[["","1",".","2",""],["−","0",".","3","6"],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#1','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',1,'mc','auto','수영 대회의 혼계영은 몇 명의 선수가 어떤 순서로 헤엄치는 경기인가요?',ARRAY['M4-2-u3-X17']::text[],false,'{"seq":1,"concept":"M4-2-u3-C9","difficulty":1,"kind":"mc","stem":"수영 대회의 혼계영은 몇 명의 선수가 어떤 순서로 헤엄치는 경기인가요?","options":[{"t":"4명 — 배영, 평영, 접영, 자유형","correct":true},{"t":"4명 — 접영, 배영, 평영, 자유형","mis":"M4-2-u3-X17"},{"t":"1명 — 배영, 평영, 접영, 자유형","mis":"M4-2-u3-X17"}],"explanation":["혼계영은 4명의 선수가 이어서 헤엄치는 단체전이에요.","순서는 배영, 평영, 접영, 자유형이에요.","접영, 배영, 평영, 자유형 순서로 한 선수가 헤엄치는 것은 개인 혼영이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#2','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',1,'mc','auto','지난 대회 두 팀의 혼계영 200 m 기록은 돌고래 팀 148.89초, 아기 상어 팀 150.21초예요. 어느 팀이 더 빠른가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X18']::text[],false,'{"seq":2,"concept":"M4-2-u3-C9","difficulty":1,"kind":"mc","stem":"지난 대회 두 팀의 혼계영 200 m 기록은 돌고래 팀 148.89초, 아기 상어 팀 150.21초예요. 어느 팀이 더 빠른가요?","options":[{"t":"돌고래 팀","correct":true},{"t":"아기 상어 팀","mis":"M4-2-u3-X17"},{"t":"두 팀이 똑같이 빨라요","mis":"M4-2-u3-X18"}],"explanation":["기록은 시간이므로 작을수록 빨라요.","148.89 < 150.21이에요.","돌고래 팀이 더 빨라요."],"asset":{"type":"expr_grid","rows":[["팀","배영","평영","접영","자유형"],["돌고래","39.28","42.43","35.7","31.48"],["아기 상어","40.24","42.53","35.26","32.18"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#3','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C10',1,'mc','auto','선수들의 영법별 기록표예요(단위: 초). 평영에서 기록이 가장 빠른 선수는 누구인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X20']::text[],true,'{"seq":3,"concept":"M4-2-u3-C10","difficulty":1,"kind":"mc","stem":"선수들의 영법별 기록표예요(단위: 초). 평영에서 기록이 가장 빠른 선수는 누구인가요?","options":[{"t":"채원","correct":true},{"t":"건우","mis":"M4-2-u3-X17"},{"t":"서준","mis":"M4-2-u3-X20"},{"t":"지유","mis":"M4-2-u3-X20"}],"explanation":["기록은 작을수록 빨라요.","평영 — 서준 41.93초, 지유 42.19초, 채원 41.33초, 건우 43.03초예요.","가장 작은 기록은 채원의 41.33초예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]},"variant_rule":{"alt":[{"stem":"선수들의 영법별 기록표예요(단위: 초). 접영에서 기록이 가장 빠른 선수는 누구인가요?","options":[{"t":"건우","correct":true},{"t":"채원","mis":"M4-2-u3-X17"},{"t":"지유","mis":"M4-2-u3-X20"},{"t":"서준","mis":"M4-2-u3-X20"}],"explanation":["기록은 작을수록 빨라요.","접영 — 서준 35.76초, 지유 35.01초, 채원 36.18초, 건우 34.62초예요.","가장 작은 기록은 건우의 34.62초예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}},{"stem":"선수들의 영법별 기록표예요(단위: 초). 자유형에서 기록이 가장 빠른 선수는 누구인가요?","options":[{"t":"지유","correct":true},{"t":"채원","mis":"M4-2-u3-X17"},{"t":"건우","mis":"M4-2-u3-X20"},{"t":"서준","mis":"M4-2-u3-X20"}],"explanation":["기록은 작을수록 빨라요.","자유형 — 서준 32.52초, 지유 31.86초, 채원 33.23초, 건우 32.35초예요.","가장 작은 기록은 지유의 31.86초예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#4','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C10',1,'sa','auto','혼계영 200 m 예선 경기 안내 — 「혼계영 200 m 예선 통과 기준은 150초입니다.」 예선을 통과하려면 네 선수의 기록의 합이 몇 초보다 빨라야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M4-2-u3-C10","difficulty":1,"kind":"sa","stem":"혼계영 200 m 예선 경기 안내 — 「혼계영 200 m 예선 통과 기준은 150초입니다.」 예선을 통과하려면 네 선수의 기록의 합이 몇 초보다 빨라야 하나요? 숫자로 쓰세요.","answer":["150"],"explanation":["안내문에서 통과 기준을 찾아요.","기록은 작을수록 빠르므로 합이 150초보다 작아야 해요.","150초보다 빨라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#5','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',2,'mc','auto','돌고래 팀의 혼계영 200 m 기록(배영, 평영, 접영, 자유형 기록의 합)은 몇 초인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X12','M4-2-u3-X17']::text[],true,'{"seq":5,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"돌고래 팀의 혼계영 200 m 기록(배영, 평영, 접영, 자유형 기록의 합)은 몇 초인가요?","options":[{"t":"148.89초","correct":true},{"t":"148.79초","mis":"M4-2-u3-X11"},{"t":"116.76초","mis":"M4-2-u3-X12"},{"t":"150.21초","mis":"M4-2-u3-X17"}],"explanation":["39.28 + 42.43 = 81.71이에요.","81.71 + 35.7 = 117.41이에요.","117.41 + 31.48 = 148.89 — 148.89초예요."],"asset":{"type":"expr_grid","rows":[["팀","배영","평영","접영","자유형"],["돌고래","39.28","42.43","35.7","31.48"],["아기 상어","40.24","42.53","35.26","32.18"]]},"variant_rule":{"alt":[{"stem":"아기 상어 팀의 혼계영 200 m 기록(배영, 평영, 접영, 자유형 기록의 합)은 몇 초인가요?","options":[{"t":"150.21초","correct":true},{"t":"150.01초","mis":"M4-2-u3-X11"},{"t":"148.89초","mis":"M4-2-u3-X17"}],"explanation":["40.24 + 42.53 = 82.77이에요.","82.77 + 35.26 = 118.03이에요.","118.03 + 32.18 = 150.21 — 150.21초예요."],"asset":{"type":"expr_grid","rows":[["팀","배영","평영","접영","자유형"],["돌고래","39.28","42.43","35.7","31.48"],["아기 상어","40.24","42.53","35.26","32.18"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#6','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',2,'mc','auto','두 팀의 기록을 비교해 보세요. 어느 팀이 몇 초 더 빠른가요? (돌고래 148.89초, 아기 상어 150.21초)',ARRAY['M4-2-u3-X17','M4-2-u3-X16','M4-2-u3-X14']::text[],false,'{"seq":6,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"두 팀의 기록을 비교해 보세요. 어느 팀이 몇 초 더 빠른가요? (돌고래 148.89초, 아기 상어 150.21초)","options":[{"t":"돌고래 팀이 1.32초","correct":true},{"t":"아기 상어 팀이 1.32초","mis":"M4-2-u3-X17"},{"t":"돌고래 팀이 299.1초","mis":"M4-2-u3-X16"},{"t":"돌고래 팀이 12.42초","mis":"M4-2-u3-X14"}],"explanation":["148.89 < 150.21 — 돌고래 팀이 더 빨라요.","기록의 차는 뺄셈으로 구해요.","150.21 − 148.89 = 1.32 — 돌고래 팀이 1.32초 더 빨라요."],"asset":{"type":"expr_grid","rows":[["팀","배영","평영","접영","자유형"],["돌고래","39.28","42.43","35.7","31.48"],["아기 상어","40.24","42.53","35.26","32.18"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#7','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',2,'mc','auto','출전 선수 명단을 배영 서준, 평영 채원, 접영 건우, 자유형 지유로 구성했어요. 네 선수의 기록의 합은 몇 초인가요?',ARRAY['M4-2-u3-X19','M4-2-u3-X11','M4-2-u3-X17']::text[],false,'{"seq":7,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"출전 선수 명단을 배영 서준, 평영 채원, 접영 건우, 자유형 지유로 구성했어요. 네 선수의 기록의 합은 몇 초인가요?","options":[{"t":"147.13초","correct":true},{"t":"147.37초","mis":"M4-2-u3-X19"},{"t":"147.03초","mis":"M4-2-u3-X11"},{"t":"148.89초","mis":"M4-2-u3-X17"}],"explanation":["39.32 + 41.33 = 80.65예요.","80.65 + 34.62 + 31.86을 차례로 더해요.","39.32 + 41.33 + 34.62 + 31.86 = 147.13 — 147.13초예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#8','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C10',2,'mc','auto','네 선수의 기록의 합 147.13초를 예선 통과 기준 150초와 비교한 것으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":8,"concept":"M4-2-u3-C10","difficulty":2,"kind":"mc","stem":"네 선수의 기록의 합 147.13초를 예선 통과 기준 150초와 비교한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"147.13 < 150이므로 통과 기준보다 더 빨라요","correct":true},{"t":"147.13 > 150이므로 통과 기준보다 느려요","mis":"M4-2-u3-X07"},{"t":"소수와 자연수라서 견줄 수 없어요","mis":"M4-2-u3-X18"}],"explanation":["자연수 부분을 먼저 견주면 147 < 150이에요.","기록이 작을수록 빨라요.","147.13 < 150 — 예선 통과 기준보다 더 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#9','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C10',2,'mc','auto','채원이는 배영과 평영에서 모두 가장 빨라요. 한 선수는 한 영법만 헤엄칠 수 있어요. 배영 서준·평영 채원(39.32 + 41.33)과 배영 채원·평영 서준(38.96 + 41.93) 중 어떻게 정하는 것이 더 빠른가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X19']::text[],false,'{"seq":9,"concept":"M4-2-u3-C10","difficulty":2,"kind":"mc","stem":"채원이는 배영과 평영에서 모두 가장 빨라요. 한 선수는 한 영법만 헤엄칠 수 있어요. 배영 서준·평영 채원(39.32 + 41.33)과 배영 채원·평영 서준(38.96 + 41.93) 중 어떻게 정하는 것이 더 빠른가요?","options":[{"t":"배영 서준, 평영 채원 — 80.65초","correct":true},{"t":"배영 채원, 평영 서준 — 80.89초","mis":"M4-2-u3-X17"},{"t":"채원이가 배영과 평영을 모두 헤엄쳐요","mis":"M4-2-u3-X19"}],"explanation":["39.32 + 41.33 = 80.65예요.","38.96 + 41.93 = 80.89예요.","80.65 < 80.89 — 서준이를 배영에, 채원이를 평영에 정해요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_basic#10','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_basic','lesson_basic','M4-2-u3-C9',3,'mc','auto','『수학익힘』 개인 혼영 200 m — 은비의 기록은 176.89초, 건우의 기록은 175.69초예요. 누가 몇 초 더 빠른가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X16','M4-2-u3-X12']::text[],false,'{"seq":10,"concept":"M4-2-u3-C9","difficulty":3,"kind":"mc","stem":"『수학익힘』 개인 혼영 200 m — 은비의 기록은 176.89초, 건우의 기록은 175.69초예요. 누가 몇 초 더 빠른가요?","options":[{"t":"건우가 1.2초","correct":true},{"t":"은비가 1.2초","mis":"M4-2-u3-X17"},{"t":"건우가 352.58초","mis":"M4-2-u3-X16"},{"t":"건우가 0.12초","mis":"M4-2-u3-X12"}],"explanation":["176.89 > 175.69 — 기록이 더 작은 건우가 빨라요.","두 기록의 차를 구해요.","176.89 − 175.69 = 1.2 — 건우가 1.2초 더 빨라요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#1','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',2,'mc','auto','개인 혼영은 한 선수가 각 영법으로 같은 거리를 차례로 이어서 헤엄치는 경기예요. 『수학익힘』의 개인 혼영 영법 순서로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17']::text[],false,'{"seq":1,"concept":"M4-2-u3-C9","difficulty":2,"kind":"mc","stem":"개인 혼영은 한 선수가 각 영법으로 같은 거리를 차례로 이어서 헤엄치는 경기예요. 『수학익힘』의 개인 혼영 영법 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"접영, 배영, 평영, 자유형","correct":true},{"t":"배영, 평영, 접영, 자유형","mis":"M4-2-u3-X17"},{"t":"자유형, 평영, 배영, 접영","mis":"M4-2-u3-X17"}],"explanation":["혼계영은 네 선수가 배영, 평영, 접영, 자유형 순서로 헤엄쳐요.","개인 혼영은 한 선수가 접영, 배영, 평영, 자유형 순서로 헤엄쳐요.","기록표의 영법 순서를 확인해요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#2','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',2,'sa','auto','개인 혼영 기록표에서 은비는 건우보다 배영에서 몇 초 더 빠른가요? 0.01초가 몇 개인지 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u3-C9","difficulty":2,"kind":"sa","stem":"개인 혼영 기록표에서 은비는 건우보다 배영에서 몇 초 더 빠른가요? 0.01초가 몇 개인지 숫자로 쓰세요.","answer":["29"],"explanation":["배영 — 은비 44.99초, 건우 45.28초예요.","45.28 − 44.99 = 0.29예요.","은비가 0.29초 더 빨라요 — 0.01초가 29개예요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]},"variant_rule":{"alt":[{"stem":"개인 혼영 기록표에서 건우는 은비보다 평영에서 몇 초 더 빠른가요? 0.01초가 몇 개인지 숫자로 쓰세요.","answer":["54"],"explanation":["평영 — 은비 48.27초, 건우 47.73초예요.","48.27 − 47.73 = 0.54예요.","건우가 0.54초 더 빨라요 — 0.01초가 54개예요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#3','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',3,'mc','auto','은비의 개인 혼영 200 m 기록(접영, 배영, 평영, 자유형 기록의 합)은 몇 초인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X17']::text[],true,'{"seq":3,"concept":"M4-2-u3-C9","difficulty":3,"kind":"mc","stem":"은비의 개인 혼영 200 m 기록(접영, 배영, 평영, 자유형 기록의 합)은 몇 초인가요?","options":[{"t":"176.89초","correct":true},{"t":"176.79초","mis":"M4-2-u3-X11"},{"t":"175.69초","mis":"M4-2-u3-X17"}],"explanation":["42.71 + 44.99 = 87.7이에요.","87.7 + 48.27 = 135.97이에요.","135.97 + 40.92 = 176.89 — 176.89초예요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]},"variant_rule":{"alt":[{"stem":"건우의 개인 혼영 200 m 기록(접영, 배영, 평영, 자유형 기록의 합)은 몇 초인가요?","options":[{"t":"175.69초","correct":true},{"t":"175.59초","mis":"M4-2-u3-X11"},{"t":"176.89초","mis":"M4-2-u3-X17"}],"explanation":["41.45 + 45.28 = 86.73이에요.","86.73 + 47.73 = 134.46이에요.","134.46 + 41.23 = 175.69 — 175.69초예요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#4','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',3,'mc','auto','해결 방안 2 — 은비는 배영과 자유형에서 0.29 + 0.31 = 0.6(초), 건우는 접영과 평영에서 1.26 + 0.54 = 1.8(초) 더 빨라요. 누가 몇 초 더 빠른가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X16','M4-2-u3-X20']::text[],false,'{"seq":4,"concept":"M4-2-u3-C9","difficulty":3,"kind":"mc","stem":"해결 방안 2 — 은비는 배영과 자유형에서 0.29 + 0.31 = 0.6(초), 건우는 접영과 평영에서 1.26 + 0.54 = 1.8(초) 더 빨라요. 누가 몇 초 더 빠른가요?","options":[{"t":"건우가 1.2초","correct":true},{"t":"은비가 1.2초","mis":"M4-2-u3-X17"},{"t":"건우가 2.4초","mis":"M4-2-u3-X16"},{"t":"건우가 1.8초","mis":"M4-2-u3-X20"}],"explanation":["영법별 차를 더해 두 사람이 빠른 만큼을 견주어요.","1.8 > 0.6 — 건우가 더 빨라요.","1.8 − 0.6 = 1.2 — 기록의 합으로 구한 결과와 같아요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#5','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',3,'mc','auto','해결 방안 1처럼 영법별로 가장 빠른 선수만 고르면 배영 채원, 평영 채원, 접영 건우, 자유형 지유가 돼요. 이 명단의 문제점은 무엇인가요?',ARRAY['M4-2-u3-X19','M4-2-u3-X07']::text[],false,'{"seq":5,"concept":"M4-2-u3-C10","difficulty":3,"kind":"mc","stem":"해결 방안 1처럼 영법별로 가장 빠른 선수만 고르면 배영 채원, 평영 채원, 접영 건우, 자유형 지유가 돼요. 이 명단의 문제점은 무엇인가요?","options":[{"t":"채원이가 두 영법에 겹쳐 한 선수가 한 영법만 헤엄친다는 조건에 맞지 않아요","correct":true},{"t":"네 영법에서 가장 빠른 선수를 골랐으니 문제가 없어요","mis":"M4-2-u3-X19"},{"t":"기록의 합이 150초보다 커져요","mis":"M4-2-u3-X07"}],"explanation":["혼계영은 네 선수가 한 영법씩 맡아요.","채원이가 배영과 평영에서 모두 가장 빨라 두 번 들어갔어요.","두 번째로 빠른 선수와 짝의 합을 견주어 다시 정해야 해요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#6','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',3,'mc','auto','명단 ㉮ 서준·채원·건우·지유(147.13초)와 명단 ㉯ 채원·서준·건우·지유(147.37초)를 비교했어요. 기록이 더 좋은 명단과 두 기록의 차로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X16','M4-2-u3-X18']::text[],false,'{"seq":6,"concept":"M4-2-u3-C10","difficulty":3,"kind":"mc","stem":"명단 ㉮ 서준·채원·건우·지유(147.13초)와 명단 ㉯ 채원·서준·건우·지유(147.37초)를 비교했어요. 기록이 더 좋은 명단과 두 기록의 차로 알맞은 것은 어느 것인가요?","options":[{"t":"㉮ — 0.24초","correct":true},{"t":"㉯ — 0.24초","mis":"M4-2-u3-X17"},{"t":"㉮ — 294.5초","mis":"M4-2-u3-X16"},{"t":"두 명단 모두 통과하니 같아요","mis":"M4-2-u3-X18"}],"explanation":["두 명단 모두 150초보다 빨라 예선은 통과해요.","147.13 < 147.37 — ㉮가 더 빨라요.","147.37 − 147.13 = 0.24 — ㉮가 0.24초 더 빨라요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#7','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',3,'sa','auto','가장 빠른 명단의 기록 147.13초는 예선 통과 기준 150초보다 몇 초 빠른가요? 0.01초가 몇 개인지 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u3-C10","difficulty":3,"kind":"sa","stem":"가장 빠른 명단의 기록 147.13초는 예선 통과 기준 150초보다 몇 초 빠른가요? 0.01초가 몇 개인지 숫자로 쓰세요.","answer":["287"],"explanation":["150 = 150.00으로 보고 소수점을 맞추어요.","150 − 147.13 = 2.87이에요.","2.87초 — 0.01초가 287개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#8','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',4,'essay','teacher','내가 수영 감독이라면! 선수들의 영법별 기록표를 보고 혼계영 200 m 출전 선수 명단(배영, 평영, 접영, 자유형)을 쓰고, 기록의 합을 예선 통과 기준 150초와 비교하여 나의 전략을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u3-C10","difficulty":4,"kind":"essay","stem":"내가 수영 감독이라면! 선수들의 영법별 기록표를 보고 혼계영 200 m 출전 선수 명단(배영, 평영, 접영, 자유형)을 쓰고, 기록의 합을 예선 통과 기준 150초와 비교하여 나의 전략을 설명해 보세요.","answer_guide":{"answer":"예: 배영 서준, 평영 채원, 접영 건우, 자유형 지유. 39.32 + 41.33 + 34.62 + 31.86 = 147.13(초)이고 147.13 < 150이므로 예선 통과 기준보다 더 빠르다. 전략: 영법별로 가장 빠른 선수를 정했는데 채원이가 배영과 평영에서 모두 가장 빨라서 두 번째로 빠른 서준이와의 기록을 비교(80.65초 < 80.89초)한 후 서준이를 배영에, 채원이를 평영에 정했다.","scoring_points":["한 선수가 한 영법씩 네 명을 모두 배치했는가","기록의 합을 바르게 구하고 150초와 비교했는가","명단을 정한 전략(가장 빠른 선수·두 번째 선수와의 합 비교 등)을 설명했는가"]},"explanation":["영법별로 가장 빠른 선수에 ○, 두 번째로 빠른 선수에 △ 표시해 보아요.","채원이가 겹치면 39.32 + 41.33 = 80.65와 38.96 + 41.93 = 80.89를 견주어요.","서준·채원·건우·지유 순 147.13초 < 150초예요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#9','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C9',4,'essay','teacher','지난 대회 두 팀의 혼계영 200 m 기록을 각각 구하고, 어느 팀이 몇 초 더 빠른지 식을 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u3-C9","difficulty":4,"kind":"essay","stem":"지난 대회 두 팀의 혼계영 200 m 기록을 각각 구하고, 어느 팀이 몇 초 더 빠른지 식을 써서 설명해 보세요.","answer_guide":{"answer":"돌고래 팀: 39.28 + 42.43 + 35.7 + 31.48 = 148.89(초). 아기 상어 팀: 40.24 + 42.53 + 35.26 + 32.18 = 150.21(초). 148.89 < 150.21이므로 돌고래 팀이 150.21 − 148.89 = 1.32(초) 더 빠르다.","scoring_points":["두 팀의 기록을 덧셈으로 바르게 구했는가","기록이 작을수록 빠르다는 것을 알고 견주었는가","뺄셈으로 1.32초를 구했는가"]},"explanation":["기록의 합은 덧셈, 기록의 차는 뺄셈으로 구해요.","35.7은 35.70으로 보고 소수점을 맞추어 더해요.","돌고래 팀이 1.32초 더 빨라요."],"asset":{"type":"expr_grid","rows":[["팀","배영","평영","접영","자유형"],["돌고래","39.28","42.43","35.7","31.48"],["아기 상어","40.24","42.53","35.26","32.18"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_L10_challenge#10','math',4,2,'u3','L10','tb_g4_2_math_u3_L10_challenge','lesson_challenge','M4-2-u3-C10',4,'essay','teacher','친구들이 작성한 명단과 비교하면서 「기록이 가장 좋게 나오도록 구성하기」와 「예선이므로 통과 기준 150초만 넘지 않게 구성하기」 두 전략의 좋은 점을 각각 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u3-C10","difficulty":4,"kind":"essay","stem":"친구들이 작성한 명단과 비교하면서 「기록이 가장 좋게 나오도록 구성하기」와 「예선이므로 통과 기준 150초만 넘지 않게 구성하기」 두 전략의 좋은 점을 각각 써 보세요.","answer_guide":{"answer":"예: 기록이 가장 좋게 구성하면(서준·채원·건우·지유, 147.13초) 예선에서 가장 좋은 기록으로 통과할 수 있다. 통과 기준만 넘지 않게 구성하면(예: 채원·서준·건우·지유, 147.37초) 150초보다 빠르므로 예선을 통과하면서 여러 선수에게 기회를 주거나 결선을 위해 힘을 아낄 수 있다.","scoring_points":["첫째 전략의 좋은 점을 기록(147.13초)과 함께 썼는가","둘째 전략도 150초보다 빠른지 확인했는가","두 전략을 견주어 자기 생각을 썼는가"]},"explanation":["두 명단 모두 150초보다 빨라요.","147.13 < 147.37 < 150이에요.","전략에 따라 명단이 달라질 수 있어요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#1','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C1',1,'blank','auto','정리 — 분수 ⟨1/100⟩은 소수로 □(이)라 쓰고 영 점 영일이라고 읽어요. □에 알맞은 수는 무엇인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X04']::text[],false,'{"seq":1,"concept":"M4-2-u3-C1","difficulty":1,"kind":"blank","stem":"정리 — 분수 ⟨1/100⟩은 소수로 □(이)라 쓰고 영 점 영일이라고 읽어요. □에 알맞은 수는 무엇인가요?","options":[{"t":"0.01","correct":true},{"t":"0.1","mis":"M4-2-u3-X01"},{"t":"0.001","mis":"M4-2-u3-X01"},{"t":"100","mis":"M4-2-u3-X04"}],"explanation":["정리 — 소수 두 자리 수·세 자리 수, 소수 사이의 관계, 크기 비교, 덧셈과 뺄셈을 되짚어요.","⟨1/100⟩ = 0.01, ⟨1/1000⟩ = 0.001이에요.","□에 알맞은 것은 0.01이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#2','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C1',1,'mc','auto','1이 3개, 0.1이 5개, 0.01이 6개인 수는 얼마인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X01']::text[],false,'{"seq":2,"concept":"M4-2-u3-C1","difficulty":1,"kind":"mc","stem":"1이 3개, 0.1이 5개, 0.01이 6개인 수는 얼마인가요?","options":[{"t":"3.56","correct":true},{"t":"3.65","mis":"M4-2-u3-X03"},{"t":"35.6","mis":"M4-2-u3-X03"},{"t":"0.356","mis":"M4-2-u3-X01"}],"explanation":["자리마다 숫자를 차례로 써요 — 일의 자리 3, 소수 첫째 자리 5, 소수 둘째 자리 6.","3 + 0.5 + 0.06 = 3.56.","1이 3개, 0.1이 5개, 0.01이 6개인 수는 3.56이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#3','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C3',1,'mc','auto','8.03의 10배는 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06','M4-2-u3-X09']::text[],false,'{"seq":3,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"8.03의 10배는 얼마인가요?","options":[{"t":"80.3","correct":true},{"t":"0.803","mis":"M4-2-u3-X05"},{"t":"803","mis":"M4-2-u3-X06"},{"t":"8.030","mis":"M4-2-u3-X09"}],"explanation":["10배를 하면 소수점을 기준으로 숫자가 왼쪽으로 한 자리씩 옮겨 가요.","8.03의 숫자를 왼쪽으로 한 자리 옮겨요.","8.03의 10배는 80.3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#4','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C5',1,'mc','auto','2.9 + 0.4를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],true,'{"seq":4,"concept":"M4-2-u3-C5","difficulty":1,"kind":"mc","stem":"2.9 + 0.4를 계산한 값은 얼마인가요?","options":[{"t":"3.3","correct":true},{"t":"2.3","mis":"M4-2-u3-X11"},{"t":"2.13","mis":"M4-2-u3-X10"},{"t":"2.5","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 9 + 4 = 13 — 3을 쓰고 일의 자리로 1을 받아올려요.","2.9 + 0.4 = 3.3이에요."],"variant_rule":{"alt":[{"stem":"1.55 + 4.7을 계산한 값은 얼마인가요?","options":[{"t":"6.25","correct":true},{"t":"5.25","mis":"M4-2-u3-X11"},{"t":"5.125","mis":"M4-2-u3-X10"},{"t":"2.02","mis":"M4-2-u3-X12"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 5 + 7 = 12 — 2를 쓰고 일의 자리로 1을 받아올려요.","1.55 + 4.7 = 6.25예요."],"asset":{"type":"expr_grid","rows":[["","1",".","5","5"],["+","4",".","7",""],["","?",".","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#5','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C4',1,'mc','auto','0.716, 0.62, 0.618, 0.713을 작은 수부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X17','M4-2-u3-X08']::text[],false,'{"seq":5,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"0.716, 0.62, 0.618, 0.713을 작은 수부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"0.618, 0.62, 0.713, 0.716","correct":true},{"t":"0.62, 0.618, 0.713, 0.716","mis":"M4-2-u3-X07"},{"t":"0.716, 0.713, 0.62, 0.618","mis":"M4-2-u3-X17"},{"t":"0.618, 0.713, 0.716, 0.62","mis":"M4-2-u3-X08"}],"explanation":["두 수씩 크기를 비교해요 — 0.62 > 0.618(소수 둘째 자리 2 > 1).","0.716 > 0.713(소수 셋째 자리 6 > 3), 0.713 > 0.62(소수 첫째 자리 7 > 6)이에요.","작은 수부터 0.618, 0.62, 0.713, 0.716이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#6','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C4',1,'mc','auto','5장의 카드 1, 5, 7, 9, 「.」을 한 번씩만 사용하여 소수 세 자리 수를 만들려고 해요. 만들 수 있는 소수 세 자리 수 중에서 9.57보다 큰 수를 모두 쓴 것은 어느 것인가요?',ARRAY['M4-2-u3-X20','M4-2-u3-X07']::text[],false,'{"seq":6,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"5장의 카드 1, 5, 7, 9, 「.」을 한 번씩만 사용하여 소수 세 자리 수를 만들려고 해요. 만들 수 있는 소수 세 자리 수 중에서 9.57보다 큰 수를 모두 쓴 것은 어느 것인가요?","options":[{"t":"9.571, 9.715, 9.751","correct":true},{"t":"9.571, 9.715","mis":"M4-2-u3-X20"},{"t":"9.517, 9.571, 9.715, 9.751","mis":"M4-2-u3-X07"},{"t":"9.751","mis":"M4-2-u3-X20"}],"explanation":["9.57보다 크려면 일의 자리에 9, 소수 첫째 자리에 5 이상이 와야 해요 — 소수 첫째 자리에 1은 올 수 없어요.","9.5□□: 9.571(9.517은 9.57보다 작아요), 9.7□□: 9.715, 9.751이에요.","9.571, 9.715, 9.751이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#7','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C8',1,'sa','auto','8.1□ − □.52 = 7.□9 — 소수 둘째 자리의 □(빼지는 수)에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u3-C8","difficulty":1,"kind":"sa","stem":"8.1□ − □.52 = 7.□9 — 소수 둘째 자리의 □(빼지는 수)에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["소수 둘째 자리에서 2를 뺐는데 9가 나왔으니 받아내림을 했어요.","10 + □ − 2 = 9 → □ = 1이에요.","8.11 − 0.52 = 7.59예요."],"asset":{"type":"expr_grid","rows":[["","8",".","1","?"],["−","□",".","5","2"],["","7",".","□","9"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#8','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C1',1,'mc','auto','작년에 1.6 m였던 나무의 키를 오늘 재어 보니 작년보다 52 cm가 더 자랐어요. 오늘 잰 나무의 키는 몇 m인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X12']::text[],false,'{"seq":8,"concept":"M4-2-u3-C1","difficulty":1,"kind":"mc","stem":"작년에 1.6 m였던 나무의 키를 오늘 재어 보니 작년보다 52 cm가 더 자랐어요. 오늘 잰 나무의 키는 몇 m인가요?","options":[{"t":"2.12 m","correct":true},{"t":"1.12 m","mis":"M4-2-u3-X11"},{"t":"1.112 m","mis":"M4-2-u3-X10"},{"t":"0.68 m","mis":"M4-2-u3-X12"}],"explanation":["52 cm = 0.52 m — 단위를 m로 맞추어요.","소수 첫째 자리: 6 + 5 = 11 — 1을 쓰고 일의 자리로 1을 받아올려요.","1.6 + 0.52 = 2.12 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#9','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C2',2,'mc','auto','0.147을 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X03']::text[],false,'{"seq":9,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"0.147을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"영 점 일사칠","correct":true},{"t":"영 점 백사십칠","mis":"M4-2-u3-X02"},{"t":"영 점 영일사칠","mis":"M4-2-u3-X03"},{"t":"일 점 사칠","mis":"M4-2-u3-X03"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 영.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","0.147 → 영 점 일사칠."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#10','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C1',2,'mc','auto','탁자의 가로 길이가 237 cm예요. 탁자의 가로 길이는 몇 m인가요?',ARRAY['M4-2-u3-X04']::text[],false,'{"seq":10,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"탁자의 가로 길이가 237 cm예요. 탁자의 가로 길이는 몇 m인가요?","options":[{"t":"2.37 m","correct":true},{"t":"23.7 m","mis":"M4-2-u3-X04"},{"t":"0.237 m","mis":"M4-2-u3-X04"},{"t":"237 m","mis":"M4-2-u3-X04"}],"explanation":["1 m = 100 cm이므로 1 cm = 0.01 m예요.","237 cm는 0.01 m가 237개예요.","237 cm = 2.37 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#11','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C3',2,'mc','auto','공 한 개의 무게는 5.3 g이에요. 공 100개의 무게를 구하려고 해요. 5.3 g의 100배는 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],false,'{"seq":11,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"공 한 개의 무게는 5.3 g이에요. 공 100개의 무게를 구하려고 해요. 5.3 g의 100배는 얼마인가요?","options":[{"t":"530 g","correct":true},{"t":"0.053 g","mis":"M4-2-u3-X05"},{"t":"5300 g","mis":"M4-2-u3-X06"},{"t":"53 g","mis":"M4-2-u3-X06"}],"explanation":["100배를 하면 소수점을 기준으로 숫자가 왼쪽으로 두 자리씩 옮겨 가요.","5.3의 숫자를 왼쪽으로 두 자리 옮겨요.","5.3 g의 100배는 530 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#12','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C4',2,'mc','auto','두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.483 ○ 0.487',ARRAY['M4-2-u3-X21','M4-2-u3-X18']::text[],false,'{"seq":12,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.483 ○ 0.487","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X21"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 셋째 자리 숫자를 견주면 3 < 7이에요.","0.483 < 0.487."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#13','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C5',2,'mc','auto','0.6 + 0.3을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":13,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"0.6 + 0.3을 계산한 값은 얼마인가요?","options":[{"t":"0.9","correct":true},{"t":"0.3","mis":"M4-2-u3-X16"},{"t":"9","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.1의 개수로 보면 6 + 3 = 9예요.","0.6 + 0.3 = 0.9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#14','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C6',2,'mc','auto','2.62 + 1.27을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":14,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"2.62 + 1.27을 계산한 값은 얼마인가요?","options":[{"t":"3.89","correct":true},{"t":"1.35","mis":"M4-2-u3-X16"},{"t":"389","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.01의 개수로 보면 262 + 127 = 389예요.","2.62 + 1.27 = 3.89예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#15','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C7',2,'mc','auto','0.9 − 0.1을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":15,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"0.9 − 0.1을 계산한 값은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1","mis":"M4-2-u3-X16"},{"t":"8","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 9 − 1 = 8이에요.","0.9 − 0.1 = 0.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#16','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C8',2,'mc','auto','0.86 − 0.31을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":16,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"0.86 − 0.31을 계산한 값은 얼마인가요?","options":[{"t":"0.55","correct":true},{"t":"1.17","mis":"M4-2-u3-X16"},{"t":"55","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.01의 개수로 보면 86 − 31 = 55예요.","0.86 − 0.31 = 0.55예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#17','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C5',3,'mc','auto','모은 재활용 종이의 무게는 2.8 kg이고, 유리의 무게는 종이의 무게보다 0.4 kg 더 무거워요. 모은 재활용 유리의 무게는 몇 kg인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],false,'{"seq":17,"concept":"M4-2-u3-C5","difficulty":3,"kind":"mc","stem":"모은 재활용 종이의 무게는 2.8 kg이고, 유리의 무게는 종이의 무게보다 0.4 kg 더 무거워요. 모은 재활용 유리의 무게는 몇 kg인가요?","options":[{"t":"3.2 kg","correct":true},{"t":"2.2 kg","mis":"M4-2-u3-X11"},{"t":"2.12 kg","mis":"M4-2-u3-X10"},{"t":"2.4 kg","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 8 + 4 = 12 — 2를 쓰고 일의 자리로 1을 받아올려요.","2.8 + 0.4 = 3.2 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#18','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C7',3,'mc','auto','수진이가 날린 로켓의 비행시간은 3.4초, 은우가 날린 로켓의 비행시간은 4.1초였어요. 두 로켓의 비행시간의 차는 몇 초인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":18,"concept":"M4-2-u3-C7","difficulty":3,"kind":"mc","stem":"수진이가 날린 로켓의 비행시간은 3.4초, 은우가 날린 로켓의 비행시간은 4.1초였어요. 두 로켓의 비행시간의 차는 몇 초인가요?","options":[{"t":"0.7초","correct":true},{"t":"1.3초","mis":"M4-2-u3-X13"},{"t":"1.7초","mis":"M4-2-u3-X14"},{"t":"7.5초","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 1에서 4를 뺄 수 없어 일의 자리에서 받아내림해요 — 11 − 4 = 7.","4.1 − 3.4 = 0.7초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#19','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C6',3,'error','auto','5.1 + 4.26 = 4.77 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X12','M4-2-u3-X11','M4-2-u3-X10']::text[],false,'{"seq":19,"concept":"M4-2-u3-C6","difficulty":3,"kind":"error","stem":"5.1 + 4.26 = 4.77 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"받아올림한 1을 윗자리에 더하지 않았어요","mis":"M4-2-u3-X11"},{"t":"같은 자리의 합이 10이 넘었는데 그 합을 그 자리에 그대로 썼어요","mis":"M4-2-u3-X10"}],"explanation":["틀린 답 4.77: 소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요.","소수점을 맞추어 같은 자리끼리 더하고, 받아올림을 생각해요.","바르게 계산하면 5.1 + 4.26 = 9.36이에요."],"asset":{"type":"expr_grid","rows":[["","","5",".","1"],["+","4",".","2","6"],["","4",".","7","7"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#20','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C9',3,'mc','auto','두 팀의 혼계영 200 m 기록표예요. 어느 팀이 몇 초 더 빠른가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X16']::text[],false,'{"seq":20,"concept":"M4-2-u3-C9","difficulty":3,"kind":"mc","stem":"두 팀의 혼계영 200 m 기록표예요. 어느 팀이 몇 초 더 빠른가요?","options":[{"t":"돌고래 팀이 1.32초","correct":true},{"t":"아기 상어 팀이 1.32초","mis":"M4-2-u3-X17"},{"t":"돌고래 팀이 299.1초","mis":"M4-2-u3-X16"}],"explanation":["돌고래 팀 148.89초, 아기 상어 팀 150.21초예요.","기록이 작을수록 빨라요.","150.21 − 148.89 = 1.32 — 돌고래 팀이 1.32초 더 빨라요."],"asset":{"type":"expr_grid","rows":[["팀","배영","평영","접영","자유형"],["돌고래","39.28","42.43","35.7","31.48"],["아기 상어","40.24","42.53","35.26","32.18"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#21','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C4',3,'mc','auto','지도서 오류 1 — 0.003과 0.02 중에서 더 큰 수는 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":21,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"지도서 오류 1 — 0.003과 0.02 중에서 더 큰 수는 어느 것인가요?","options":[{"t":"0.02","correct":true},{"t":"0.003","mis":"M4-2-u3-X07"},{"t":"두 수는 크기가 같아요","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추면 0.003과 0.020이에요.","소수 둘째 자리를 견주면 0 < 2예요.","0.02가 더 커요 — 길이가 길다고 큰 수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#22','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C1',3,'sa','auto','2.58은 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M4-2-u3-C1","difficulty":3,"kind":"sa","stem":"2.58은 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["258"],"explanation":["1은 0.01이 100개예요.","2는 0.01이 200개, 0.58은 0.01이 58개예요.","2.58은 0.01이 258개인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#23','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C6',4,'essay','teacher','단원 핵심 질문 — 「소수의 덧셈과 뺄셈은 어떻게 할까요?」 이 단원에서 배운 내용으로 답을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"단원 핵심 질문 — 「소수의 덧셈과 뺄셈은 어떻게 할까요?」 이 단원에서 배운 내용으로 답을 써 보세요.","answer_guide":{"answer":"소수점의 위치를 맞추어 세로로 쓰고, 자연수의 덧셈과 뺄셈과 같은 방법으로 같은 자리 수끼리 계산한다. 덧셈은 받아올림(0.1이 10개면 1, 0.01이 10개면 0.1), 뺄셈은 받아내림을 생각한다. 자릿수가 다르면 빈 자리에 0이 있다고 생각한다.","scoring_points":["소수점의 위치를 맞추어 쓴다고 썼는가","자연수와 같은 방법(같은 자리끼리)으로 받아올림·받아내림을 한다고 썼는가","자릿수가 다를 때 빈 자리를 0으로 본다고 썼는가"]},"explanation":["소수점을 맞추면 같은 자리끼리 줄이 맞아요.","받아올림·받아내림은 자연수와 같아요.","0.84 + 0.3 = 1.14, 1.2 − 0.36 = 0.84처럼 자릿수가 다를 때 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#24','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C10',4,'essay','teacher','내가 수영 감독이라면! — 선수들의 영법별 기록표를 보고 혼계영 200 m 출전 선수 명단을 쓰고, 예선 통과 기준 150초와 비교해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u3-C10","difficulty":4,"kind":"essay","stem":"내가 수영 감독이라면! — 선수들의 영법별 기록표를 보고 혼계영 200 m 출전 선수 명단을 쓰고, 예선 통과 기준 150초와 비교해 보세요.","answer_guide":{"answer":"예: 배영 서준, 평영 채원, 접영 건우, 자유형 지유. 39.32 + 41.33 + 34.62 + 31.86 = 147.13(초)이고 147.13 < 150이므로 예선 통과 기준보다 더 빠르다.","scoring_points":["네 선수를 한 영법씩 배치했는가","기록의 합을 바르게 구했는가","150초와 비교했는가"]},"explanation":["한 선수는 한 영법만 맡아요.","39.32 + 41.33 + 34.62 + 31.86 = 147.13이에요.","147.13 < 150 — 예선 통과 기준보다 빨라요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_a#25','math',4,2,'u3','','tb_g4_2_math_u3_review_a','unit_review','M4-2-u3-C1',4,'essay','teacher','나의 성장 기록 — 이 단원을 학습하면서 생활 속에서 소수가 쓰이는 경우를 두 가지 이상 찾아 쓰고, 소수가 왜 필요한지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u3-C1","difficulty":4,"kind":"essay","stem":"나의 성장 기록 — 이 단원을 학습하면서 생활 속에서 소수가 쓰이는 경우를 두 가지 이상 찾아 쓰고, 소수가 왜 필요한지 써 보세요.","answer_guide":{"answer":"예: 음료수 갑의 들이(1.89 L), 저울에 나온 무게(4.86 g), 쇼트 트랙 기록(6분 55.968초), 수영 기록(148.89초)에 소수가 쓰인다. 1보다 작은 양이나 자연수와 자연수 사이의 양을 정확하게 나타내고 기록을 견주려면 소수가 꼭 필요하다.","scoring_points":["생활 속 소수의 예를 두 가지 이상 썼는가","소수 두 자리·세 자리 수가 쓰인 예를 바르게 읽거나 썼는가","소수가 필요한 까닭(정확하게 나타내기·견주기)을 썼는가"]},"explanation":["음료수 갑·저울·운동 경기 기록에서 소수를 찾을 수 있어요.","0.01, 0.001처럼 작은 단위로 정확하게 나타내요.","소수는 실생활에서 많이 쓰이는 꼭 필요한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#1','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C2',1,'blank','auto','정리 — 분수 ⟨1/1000⟩은 소수로 □(이)라 쓰고 영 점 영영일이라고 읽어요. □에 알맞은 수는 무엇인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X04']::text[],false,'{"seq":1,"concept":"M4-2-u3-C2","difficulty":1,"kind":"blank","stem":"정리 — 분수 ⟨1/1000⟩은 소수로 □(이)라 쓰고 영 점 영영일이라고 읽어요. □에 알맞은 수는 무엇인가요?","options":[{"t":"0.001","correct":true},{"t":"0.01","mis":"M4-2-u3-X01"},{"t":"0.1","mis":"M4-2-u3-X01"},{"t":"1000","mis":"M4-2-u3-X04"}],"explanation":["정리 — 소수 두 자리 수·세 자리 수, 소수 사이의 관계, 크기 비교, 덧셈과 뺄셈을 되짚어요.","⟨1/1000⟩ = 0.001이에요.","□에 알맞은 것은 0.001이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#2','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C2',1,'mc','auto','일의 자리 숫자가 1, 소수 첫째 자리 숫자가 7, 소수 둘째 자리 숫자가 2, 소수 셋째 자리 숫자가 9인 소수 세 자리 수는 얼마인가요?',ARRAY['M4-2-u3-X03']::text[],false,'{"seq":2,"concept":"M4-2-u3-C2","difficulty":1,"kind":"mc","stem":"일의 자리 숫자가 1, 소수 첫째 자리 숫자가 7, 소수 둘째 자리 숫자가 2, 소수 셋째 자리 숫자가 9인 소수 세 자리 수는 얼마인가요?","options":[{"t":"1.729","correct":true},{"t":"9.271","mis":"M4-2-u3-X03"},{"t":"17.29","mis":"M4-2-u3-X03"},{"t":"1.792","mis":"M4-2-u3-X03"}],"explanation":["자리 이름에 맞추어 숫자를 차례로 써요.","일의 자리 1, 소수 첫째 7, 둘째 2, 셋째 9예요.","1.729예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#3','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C3',1,'mc','auto','8.03의 ⟨1/10⟩은 얼마인가요?',ARRAY['M4-2-u3-X05']::text[],false,'{"seq":3,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"8.03의 ⟨1/10⟩은 얼마인가요?","options":[{"t":"0.803","correct":true},{"t":"80.3","mis":"M4-2-u3-X05"},{"t":"803","mis":"M4-2-u3-X05"}],"explanation":["⟨1/10⟩을 하면 소수점을 기준으로 숫자가 오른쪽으로 한 자리씩 옮겨 가요.","8.03의 숫자를 오른쪽으로 한 자리 옮겨요.","8.03의 ⟨1/10⟩은 0.803이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#4','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C6',1,'mc','auto','3.82 + 5.19를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],false,'{"seq":4,"concept":"M4-2-u3-C6","difficulty":1,"kind":"mc","stem":"3.82 + 5.19를 계산한 값은 얼마인가요?","options":[{"t":"9.01","correct":true},{"t":"8.91","mis":"M4-2-u3-X11"},{"t":"8.911","mis":"M4-2-u3-X10"},{"t":"1.37","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 2 + 9 = 11 — 1을 쓰고 소수 첫째 자리로 1을 받아올려요.","3.82 + 5.19 = 9.01이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#5','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C4',1,'mc','auto','두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.62 ○ 0.618',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":5,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.62 ○ 0.618","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X07"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 둘째 자리 숫자를 견주면 2 > 1이에요.","0.62 > 0.618."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#6','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C4',1,'sa','auto','5장의 카드 1, 5, 7, 9, 「.」을 한 번씩만 사용하여 만들 수 있는 소수 세 자리 수 중에서 9.57보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u3-C4","difficulty":1,"kind":"sa","stem":"5장의 카드 1, 5, 7, 9, 「.」을 한 번씩만 사용하여 만들 수 있는 소수 세 자리 수 중에서 9.57보다 큰 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["일의 자리는 9, 소수 첫째 자리는 5 또는 7이어야 해요.","9.517은 9.57보다 작아요.","9.571, 9.715, 9.751 — 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#7','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C8',1,'sa','auto','8.1□ − □.52 = 7.□9 — 빼는 수의 일의 자리 □에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u3-C8","difficulty":1,"kind":"sa","stem":"8.1□ − □.52 = 7.□9 — 빼는 수의 일의 자리 □에 알맞은 숫자를 쓰세요.","answer":["0"],"explanation":["소수 첫째 자리로 일의 자리에서 1을 받아내렸어요.","일의 자리: 7 − □ = 7 → □ = 0이에요.","8.11 − 0.52 = 7.59예요."],"asset":{"type":"expr_grid","rows":[["","8",".","1","□"],["−","?",".","5","2"],["","7",".","□","9"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#8','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C6',1,'mc','auto','이 단원 학습을 마치고 — 다람쥐의 몸무게가 지난달에는 0.63 kg이었는데 이번 달은 0.02 kg만큼 더 늘었어요. 이번 달 다람쥐의 몸무게는 몇 kg인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":8,"concept":"M4-2-u3-C6","difficulty":1,"kind":"mc","stem":"이 단원 학습을 마치고 — 다람쥐의 몸무게가 지난달에는 0.63 kg이었는데 이번 달은 0.02 kg만큼 더 늘었어요. 이번 달 다람쥐의 몸무게는 몇 kg인가요?","options":[{"t":"0.65 kg","correct":true},{"t":"0.61 kg","mis":"M4-2-u3-X16"},{"t":"65 kg","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.01의 개수로 보면 63 + 2 = 65예요.","0.63 + 0.02 = 0.65 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#9','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C2',2,'mc','auto','3.539를 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X03']::text[],false,'{"seq":9,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"3.539를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"삼 점 오삼구","correct":true},{"t":"삼 점 오백삼십구","mis":"M4-2-u3-X02"},{"t":"삼 점 영오삼구","mis":"M4-2-u3-X03"},{"t":"삼십오 점 삼구","mis":"M4-2-u3-X03"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 삼.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","3.539 → 삼 점 오삼구."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#10','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C2',2,'mc','auto','수박의 무게가 8459 g이에요. 수박의 무게는 몇 kg인가요?',ARRAY['M4-2-u3-X04']::text[],false,'{"seq":10,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"수박의 무게가 8459 g이에요. 수박의 무게는 몇 kg인가요?","options":[{"t":"8.459 kg","correct":true},{"t":"845.9 kg","mis":"M4-2-u3-X04"},{"t":"84.59 kg","mis":"M4-2-u3-X04"},{"t":"8459 kg","mis":"M4-2-u3-X04"}],"explanation":["1 kg = 1000 g이므로 1 g = 0.001 kg이에요.","8459 g은 0.001 kg이 8459개예요.","8459 g = 8.459 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#11','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C3',2,'mc','auto','10원짜리 동전 한 개는 1.22 g이에요. 동전 100개의 무게를 구하려고 해요. 1.22 g의 100배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],false,'{"seq":11,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"10원짜리 동전 한 개는 1.22 g이에요. 동전 100개의 무게를 구하려고 해요. 1.22 g의 100배는 얼마인가요?","options":[{"t":"122 g","correct":true},{"t":"1220 g","mis":"M4-2-u3-X06"},{"t":"12.2 g","mis":"M4-2-u3-X06"},{"t":"0.122 g","mis":"M4-2-u3-X05"}],"explanation":["100배를 하면 소수점을 기준으로 숫자가 왼쪽으로 두 자리씩 옮겨 가요.","1.22의 숫자를 왼쪽으로 두 자리 옮겨요.","1.22 g의 100배는 122 g이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#12','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C4',2,'mc','auto','두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 2.504 ○ 2.53',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":12,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 2.504 ○ 2.53","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X07"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 둘째 자리 숫자를 견주면 0 < 3이에요.","2.504 < 2.53."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#13','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C5',2,'mc','auto','1.7 + 3.8을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],false,'{"seq":13,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"1.7 + 3.8을 계산한 값은 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"4.5","mis":"M4-2-u3-X11"},{"t":"4.15","mis":"M4-2-u3-X10"},{"t":"2.1","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 7 + 8 = 15 — 5를 쓰고 일의 자리로 1을 받아올려요.","1.7 + 3.8 = 5.5예요."],"asset":{"type":"expr_grid","rows":[["","1",".","7"],["+","3",".","8"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#14','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C6',2,'mc','auto','5.28 + 6.94를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":14,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"5.28 + 6.94를 계산한 값은 얼마인가요?","options":[{"t":"12.22","correct":true},{"t":"11.12","mis":"M4-2-u3-X11"},{"t":"1.66","mis":"M4-2-u3-X16"},{"t":"1222","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 8 + 4 = 12 — 2를 쓰고 소수 첫째 자리로 1을 받아올려요.","5.28 + 6.94 = 12.22예요."],"asset":{"type":"expr_grid","rows":[["","","5",".","2","8"],["+","","6",".","9","4"],["","?","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#15','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C7',2,'mc','auto','7.3 − 4.7을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":15,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"7.3 − 4.7을 계산한 값은 얼마인가요?","options":[{"t":"2.6","correct":true},{"t":"3.4","mis":"M4-2-u3-X13"},{"t":"3.6","mis":"M4-2-u3-X14"},{"t":"12","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 3에서 7을 뺄 수 없어 일의 자리에서 받아내림해요 — 13 − 7 = 6.","7.3 − 4.7 = 2.6이에요."],"asset":{"type":"expr_grid","rows":[["","7",".","3"],["−","4",".","7"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#16','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C8',2,'mc','auto','4.76 − 2.68을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":16,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"4.76 − 2.68을 계산한 값은 얼마인가요?","options":[{"t":"2.08","correct":true},{"t":"2.12","mis":"M4-2-u3-X13"},{"t":"2.18","mis":"M4-2-u3-X14"},{"t":"7.44","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 6에서 8을 뺄 수 없어 소수 첫째 자리에서 받아내림해요 — 16 − 8 = 8.","4.76 − 2.68 = 2.08이에요."],"asset":{"type":"expr_grid","rows":[["","4",".","7","6"],["−","2",".","6","8"],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#17','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C6',3,'mc','auto','물건을 담은 장바구니의 무게가 1.5 kg이었어요. 장바구니에 과일 1.28 kg을 더 담았다면 장바구니의 무게는 모두 몇 kg인가요?',ARRAY['M4-2-u3-X12','M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":17,"concept":"M4-2-u3-C6","difficulty":3,"kind":"mc","stem":"물건을 담은 장바구니의 무게가 1.5 kg이었어요. 장바구니에 과일 1.28 kg을 더 담았다면 장바구니의 무게는 모두 몇 kg인가요?","options":[{"t":"2.78 kg","correct":true},{"t":"1.43 kg","mis":"M4-2-u3-X12"},{"t":"0.22 kg","mis":"M4-2-u3-X16"},{"t":"278 kg","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.01의 개수로 보면 150 + 128 = 278이에요.","1.5 + 1.28 = 2.78 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#18','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C8',3,'mc','auto','길이가 2.31 m인 포장지 중에서 1.4 m를 선물을 포장하는 데 사용했어요. 남은 포장지의 길이는 몇 m인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X12']::text[],false,'{"seq":18,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"길이가 2.31 m인 포장지 중에서 1.4 m를 선물을 포장하는 데 사용했어요. 남은 포장지의 길이는 몇 m인가요?","options":[{"t":"0.91 m","correct":true},{"t":"1.11 m","mis":"M4-2-u3-X13"},{"t":"1.91 m","mis":"M4-2-u3-X14"},{"t":"2.17 m","mis":"M4-2-u3-X12"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 3에서 4를 뺄 수 없어 일의 자리에서 받아내림해요 — 13 − 4 = 9.","2.31 − 1.4 = 0.91 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#19','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C8',3,'error','auto','1.05 − 0.34 = 1.71 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X14','M4-2-u3-X13','M4-2-u3-X12']::text[],false,'{"seq":19,"concept":"M4-2-u3-C8","difficulty":3,"kind":"error","stem":"1.05 − 0.34 = 1.71 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"받아내림을 하고도 윗자리에서 1을 빼지 않았어요","correct":true,"mis_target":"M4-2-u3-X14"},{"t":"뺄 수 없는 자리에서 받아내림하지 않고 큰 숫자에서 작은 숫자를 거꾸로 뺐어요","mis":"M4-2-u3-X13"},{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","mis":"M4-2-u3-X12"}],"explanation":["틀린 답 1.71: 받아내림을 하고도 윗자리에서 1을 빼지 않았어요.","소수점을 맞추어 같은 자리끼리 빼고, 받아내림을 생각해요.","바르게 계산하면 1.05 − 0.34 = 0.71이에요."],"asset":{"type":"expr_grid","rows":[["","1",".","0","5"],["−","0",".","3","4"],["","1",".","7","1"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#20','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C10',3,'mc','auto','배영 서준, 평영 채원, 접영 건우, 자유형 지유로 명단을 짜면 147.13초예요. 예선 통과 기준 150초보다 몇 초 빠른가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X16','M4-2-u3-X15']::text[],false,'{"seq":20,"concept":"M4-2-u3-C10","difficulty":3,"kind":"mc","stem":"배영 서준, 평영 채원, 접영 건우, 자유형 지유로 명단을 짜면 147.13초예요. 예선 통과 기준 150초보다 몇 초 빠른가요?","options":[{"t":"2.87초","correct":true},{"t":"17.13초","mis":"M4-2-u3-X13"},{"t":"297.13초","mis":"M4-2-u3-X16"},{"t":"3.13초","mis":"M4-2-u3-X15"}],"explanation":["150을 150.00으로 보고 소수점을 맞추어요.","소수 둘째·첫째·일의 자리에서 받아내림해요.","150 − 147.13 = 2.87 — 2.87초 빨라요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#21','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C4',3,'mc','auto','지도서 오류 1 — 0.4와 0.03 중에서 더 큰 수는 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":21,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"지도서 오류 1 — 0.4와 0.03 중에서 더 큰 수는 어느 것인가요?","options":[{"t":"0.4","correct":true},{"t":"0.03","mis":"M4-2-u3-X07"},{"t":"두 수는 크기가 같아요","mis":"M4-2-u3-X18"}],"explanation":["자리를 맞추면 0.40과 0.03이에요.","소수 첫째 자리를 견주면 4 > 0이에요.","0.4가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#22','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C2',3,'sa','auto','4.275는 0.001이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M4-2-u3-C2","difficulty":3,"kind":"sa","stem":"4.275는 0.001이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["4275"],"explanation":["1은 0.001이 1000개예요.","4는 0.001이 4000개, 0.275는 0.001이 275개예요.","4.275는 0.001이 4275개인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#23','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C6',4,'essay','teacher','질문 — 「소수의 덧셈과 뺄셈을 세로로 써서 계산할 때는 수를 오른쪽에 맞추어 쓰면 왜 안 되나요?」에 답해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"질문 — 「소수의 덧셈과 뺄셈을 세로로 써서 계산할 때는 수를 오른쪽에 맞추어 쓰면 왜 안 되나요?」에 답해 보세요.","answer_guide":{"answer":"소수는 소수점을 기준으로 오른쪽으로 소수 첫째 자리, 소수 둘째 자리, 소수 셋째 자리가 있다. 오른쪽 끝을 맞추면 자릿값이 다른 숫자끼리 같은 위치에 올 수 있다(예: 5.1 + 4.26을 4.77로 계산). 같은 자리 수끼리 더하고 빼야 하므로 소수점을 기준으로 맞추어 써야 한다(5.1 + 4.26 = 9.36).","scoring_points":["자릿값이 다른 숫자끼리 같은 위치에 온다고 썼는가","같은 자리 수끼리 계산해야 한다고 썼는가","예를 들어 바르게 설명했는가"]},"explanation":["오른쪽 끝 맞춤 → 자릿값이 엇갈려요.","소수점 맞춤 → 같은 자리끼리 줄이 맞아요.","5.1 + 4.26 = 9.36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#24','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C9',4,'essay','teacher','개인 혼영에서 은비와 건우 중 누가 몇 초 더 빠른지 두 가지 방법(기록의 합으로, 영법별 차로)으로 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u3-C9","difficulty":4,"kind":"essay","stem":"개인 혼영에서 은비와 건우 중 누가 몇 초 더 빠른지 두 가지 방법(기록의 합으로, 영법별 차로)으로 구해 보세요.","answer_guide":{"answer":"방법 1: 은비 42.71 + 44.99 + 48.27 + 40.92 = 176.89(초), 건우 41.45 + 45.28 + 47.73 + 41.23 = 175.69(초)이므로 건우가 176.89 − 175.69 = 1.2(초) 더 빠르다. 방법 2: 은비는 배영 45.28 − 44.99 = 0.29(초), 자유형 41.23 − 40.92 = 0.31(초) 더 빠르고, 건우는 접영 42.71 − 41.45 = 1.26(초), 평영 48.27 − 47.73 = 0.54(초) 더 빠르다. 0.29 + 0.31 = 0.6, 1.26 + 0.54 = 1.8이므로 건우가 1.8 − 0.6 = 1.2(초) 더 빠르다.","scoring_points":["기록의 합으로 1.2초를 구했는가","영법별 차로 1.2초를 구했는가","두 방법의 결과가 같음을 확인했는가"]},"explanation":["기록의 합을 견주거나 영법별 차를 모아 견주어요.","0.29 + 0.31 = 0.6, 1.26 + 0.54 = 1.8이에요.","1.8 − 0.6 = 1.2 — 건우가 1.2초 더 빨라요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_b#25','math',4,2,'u3','','tb_g4_2_math_u3_review_b','unit_review','M4-2-u3-C1',4,'essay','teacher','마무리 ⑦ — 작년에 1.6 m였던 나무의 키를 오늘 재어 보니 작년보다 52 cm가 더 자랐어요. 오늘 잰 나무의 키는 몇 m인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u3-C1","difficulty":4,"kind":"essay","stem":"마무리 ⑦ — 작년에 1.6 m였던 나무의 키를 오늘 재어 보니 작년보다 52 cm가 더 자랐어요. 오늘 잰 나무의 키는 몇 m인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"1 cm = 0.01 m이므로 52 cm = 0.52 m이다. 따라서 오늘 잰 나무의 키는 1.6 + 0.52 = 2.12(m)이다.","scoring_points":["52 cm를 0.52 m로 나타냈는가","1.6 + 0.52로 식을 세웠는가","2.12 m를 구했는가"]},"explanation":["단위를 m로 맞추어요 — 52 cm = 0.52 m.","1.6 = 1.60으로 보고 소수점을 맞추어요.","1.6 + 0.52 = 2.12 — 2.12 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#1','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C3',1,'blank','auto','정리 — 1, 0.1, □, 0.001은 왼쪽으로 갈수록 10배씩 커지고 오른쪽으로 갈수록 ⟨1/10⟩씩 작아져요. □에 알맞은 수는 무엇인가요?',ARRAY['M4-2-u3-X01','M4-2-u3-X06']::text[],false,'{"seq":1,"concept":"M4-2-u3-C3","difficulty":1,"kind":"blank","stem":"정리 — 1, 0.1, □, 0.001은 왼쪽으로 갈수록 10배씩 커지고 오른쪽으로 갈수록 ⟨1/10⟩씩 작아져요. □에 알맞은 수는 무엇인가요?","options":[{"t":"0.01","correct":true},{"t":"0.11","mis":"M4-2-u3-X01"},{"t":"0.001","mis":"M4-2-u3-X06"},{"t":"0.02","mis":"M4-2-u3-X01"}],"explanation":["정리 — 소수 두 자리 수·세 자리 수, 소수 사이의 관계, 크기 비교, 덧셈과 뺄셈을 되짚어요.","0.1의 ⟨1/10⟩은 0.01, 0.01의 ⟨1/10⟩은 0.001이에요.","□에 알맞은 것은 0.01이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#2','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C2',1,'mc','auto','0.001이 514개인 수는 얼마인가요?',ARRAY['M4-2-u3-X01']::text[],false,'{"seq":2,"concept":"M4-2-u3-C2","difficulty":1,"kind":"mc","stem":"0.001이 514개인 수는 얼마인가요?","options":[{"t":"0.514","correct":true},{"t":"5.14","mis":"M4-2-u3-X01"},{"t":"51.4","mis":"M4-2-u3-X01"},{"t":"514","mis":"M4-2-u3-X01"}],"explanation":["0.001이 1000개이면 1이에요.","514개는 1000개보다 적으니 1보다 작아요.","0.001이 514개인 수는 0.514예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#3','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C3',1,'mc','auto','2.51의 □배는 25.1이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X05']::text[],false,'{"seq":3,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"2.51의 □배는 25.1이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M4-2-u3-X06"},{"t":"⟨1/10⟩","mis":"M4-2-u3-X05"}],"explanation":["2.51 → 25.1: 숫자가 왼쪽으로 한 자리 옮겨 갔어요.","왼쪽으로 한 자리 = 10배예요.","2.51의 10배는 25.1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#4','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C7',1,'mc','auto','9.5 − 1.8을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],true,'{"seq":4,"concept":"M4-2-u3-C7","difficulty":1,"kind":"mc","stem":"9.5 − 1.8을 계산한 값은 얼마인가요?","options":[{"t":"7.7","correct":true},{"t":"8.3","mis":"M4-2-u3-X13"},{"t":"8.7","mis":"M4-2-u3-X14"},{"t":"11.3","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 5에서 8을 뺄 수 없어 일의 자리에서 받아내림해요 — 15 − 8 = 7.","9.5 − 1.8 = 7.7이에요."],"variant_rule":{"alt":[{"stem":"3.7 − 0.17을 계산한 값은 얼마인가요?","options":[{"t":"3.53","correct":true},{"t":"3.67","mis":"M4-2-u3-X13"},{"t":"3.63","mis":"M4-2-u3-X14"},{"t":"0.2","mis":"M4-2-u3-X12"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 0에서 7을 뺄 수 없어 소수 첫째 자리에서 받아내림해요 — 10 − 7 = 3.","3.7 − 0.17 = 3.53이에요."],"asset":{"type":"expr_grid","rows":[["","3",".","7",""],["−","0",".","1","7"],["","?",".","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#5','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C4',1,'mc','auto','정리 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 1.19 ○ 1.32',ARRAY['M4-2-u3-X21','M4-2-u3-X18']::text[],false,'{"seq":5,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"정리 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 1.19 ○ 1.32","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X21"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 첫째 자리 숫자를 견주면 1 < 3이에요.","1.19 < 1.32."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#6','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C4',1,'mc','auto','5장의 카드 1, 5, 7, 9, 「.」을 한 번씩만 사용하여 만든 소수 세 자리 수 중에서 9.57보다 큰 수 가운데 가장 작은 수는 얼마인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X07','M4-2-u3-X09']::text[],false,'{"seq":6,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"5장의 카드 1, 5, 7, 9, 「.」을 한 번씩만 사용하여 만든 소수 세 자리 수 중에서 9.57보다 큰 수 가운데 가장 작은 수는 얼마인가요?","options":[{"t":"9.571","correct":true},{"t":"9.751","mis":"M4-2-u3-X17"},{"t":"9.517","mis":"M4-2-u3-X07"},{"t":"9.57","mis":"M4-2-u3-X09"}],"explanation":["9.57보다 큰 수는 9.571, 9.715, 9.751이에요.","9.517은 소수 둘째 자리가 1 < 7이라 9.57보다 작아요.","가장 작은 수는 9.571이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#7','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C8',1,'sa','auto','8.1□ − □.52 = 7.□9 — 차의 소수 첫째 자리 □에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u3-C8","difficulty":1,"kind":"sa","stem":"8.1□ − □.52 = 7.□9 — 차의 소수 첫째 자리 □에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["소수 첫째 자리 1은 소수 둘째 자리로 받아내림해 0이 되었어요.","일의 자리에서 받아내림한 10에서 5를 빼요 — 10 − 5 = 5.","8.11 − 0.52 = 7.59 — □ = 5예요."],"asset":{"type":"expr_grid","rows":[["","8",".","1","□"],["−","□",".","5","2"],["","7",".","?","9"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#8','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C8',1,'mc','auto','이 단원 학습을 마치고 — 곰의 몸무게가 지난달은 135.12 kg이었고 이번 달은 130.32 kg이에요. 지난달보다 몇 kg 줄었나요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":8,"concept":"M4-2-u3-C8","difficulty":1,"kind":"mc","stem":"이 단원 학습을 마치고 — 곰의 몸무게가 지난달은 135.12 kg이었고 이번 달은 130.32 kg이에요. 지난달보다 몇 kg 줄었나요?","options":[{"t":"4.8 kg","correct":true},{"t":"5.2 kg","mis":"M4-2-u3-X13"},{"t":"5.8 kg","mis":"M4-2-u3-X14"},{"t":"265.44 kg","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 1에서 3을 뺄 수 없어 일의 자리에서 받아내림해요 — 11 − 3 = 8.","135.12 − 130.32 = 4.8 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#9','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C2',2,'mc','auto','2.523을 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X03']::text[],false,'{"seq":9,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"2.523을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"이 점 오이삼","correct":true},{"t":"이 점 오백이십삼","mis":"M4-2-u3-X02"},{"t":"이 점 영오이삼","mis":"M4-2-u3-X03"},{"t":"이십오 점 이삼","mis":"M4-2-u3-X03"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 이.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","2.523 → 이 점 오이삼."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#10','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C2',2,'mc','auto','계량컵에 물이 225 mL 들어 있어요. 물의 양은 몇 L인가요?',ARRAY['M4-2-u3-X04']::text[],false,'{"seq":10,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"계량컵에 물이 225 mL 들어 있어요. 물의 양은 몇 L인가요?","options":[{"t":"0.225 L","correct":true},{"t":"22.5 L","mis":"M4-2-u3-X04"},{"t":"2.25 L","mis":"M4-2-u3-X04"},{"t":"225 L","mis":"M4-2-u3-X04"}],"explanation":["1 L = 1000 mL이므로 1 mL = 0.001 L예요.","225 mL는 0.001 L가 225개예요.","225 mL = 0.225 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#11','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C3',2,'mc','auto','한 병에 0.28 L가 들어 있는 주스 10병의 양을 구하려고 해요. 0.28 L의 10배는 얼마인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06','M4-2-u3-X09']::text[],false,'{"seq":11,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"한 병에 0.28 L가 들어 있는 주스 10병의 양을 구하려고 해요. 0.28 L의 10배는 얼마인가요?","options":[{"t":"2.8 L","correct":true},{"t":"0.028 L","mis":"M4-2-u3-X05"},{"t":"28 L","mis":"M4-2-u3-X06"},{"t":"0.280 L","mis":"M4-2-u3-X09"}],"explanation":["10배를 하면 소수점을 기준으로 숫자가 왼쪽으로 한 자리씩 옮겨 가요.","0.28의 숫자를 왼쪽으로 한 자리 옮겨요.","0.28 L의 10배는 2.8 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#12','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C4',2,'mc','auto','두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.563 ○ 0.561',ARRAY['M4-2-u3-X21','M4-2-u3-X18']::text[],false,'{"seq":12,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 0.563 ○ 0.561","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X21"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 셋째 자리 숫자를 견주면 3 > 1이에요.","0.563 > 0.561."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#13','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C5',2,'mc','auto','5.8 + 0.4를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],false,'{"seq":13,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"5.8 + 0.4를 계산한 값은 얼마인가요?","options":[{"t":"6.2","correct":true},{"t":"5.2","mis":"M4-2-u3-X11"},{"t":"5.12","mis":"M4-2-u3-X10"},{"t":"5.4","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 8 + 4 = 12 — 2를 쓰고 일의 자리로 1을 받아올려요.","5.8 + 0.4 = 6.2예요."],"asset":{"type":"expr_grid","rows":[["","5",".","8"],["+","0",".","4"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#14','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C6',2,'mc','auto','6.19 + 2.82를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],false,'{"seq":14,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"6.19 + 2.82를 계산한 값은 얼마인가요?","options":[{"t":"9.01","correct":true},{"t":"8.91","mis":"M4-2-u3-X11"},{"t":"8.911","mis":"M4-2-u3-X10"},{"t":"3.37","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 9 + 2 = 11 — 1을 쓰고 소수 첫째 자리로 1을 받아올려요.","6.19 + 2.82 = 9.01이에요."],"asset":{"type":"expr_grid","rows":[["","6",".","1","9"],["+","2",".","8","2"],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#15','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C7',2,'mc','auto','8.1 − 2.9를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":15,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"8.1 − 2.9를 계산한 값은 얼마인가요?","options":[{"t":"5.2","correct":true},{"t":"6.8","mis":"M4-2-u3-X13"},{"t":"6.2","mis":"M4-2-u3-X14"},{"t":"11","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 1에서 9를 뺄 수 없어 일의 자리에서 받아내림해요 — 11 − 9 = 2.","8.1 − 2.9 = 5.2예요."],"asset":{"type":"expr_grid","rows":[["","8",".","1"],["−","2",".","9"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#16','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C8',2,'mc','auto','9.27 − 6.59를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":16,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"9.27 − 6.59를 계산한 값은 얼마인가요?","options":[{"t":"2.68","correct":true},{"t":"3.32","mis":"M4-2-u3-X13"},{"t":"3.78","mis":"M4-2-u3-X14"},{"t":"15.86","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 7에서 9를 뺄 수 없어 소수 첫째 자리에서 받아내림해요 — 17 − 9 = 8.","9.27 − 6.59 = 2.68이에요."],"asset":{"type":"expr_grid","rows":[["","9",".","2","7"],["−","6",".","5","9"],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#17','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C5',3,'mc','auto','채원이의 가방 무게는 1.5 kg이고, 은비의 가방 무게는 채원이의 가방 무게보다 0.7 kg 더 무거워요. 은비의 가방 무게는 몇 kg인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],false,'{"seq":17,"concept":"M4-2-u3-C5","difficulty":3,"kind":"mc","stem":"채원이의 가방 무게는 1.5 kg이고, 은비의 가방 무게는 채원이의 가방 무게보다 0.7 kg 더 무거워요. 은비의 가방 무게는 몇 kg인가요?","options":[{"t":"2.2 kg","correct":true},{"t":"1.2 kg","mis":"M4-2-u3-X11"},{"t":"1.12 kg","mis":"M4-2-u3-X10"},{"t":"0.8 kg","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 5 + 7 = 12 — 2를 쓰고 일의 자리로 1을 받아올려요.","1.5 + 0.7 = 2.2 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#18','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C7',3,'mc','auto','50 m 달리기 연습에서 서준이는 10.5초, 도윤이는 11.2초를 기록했어요. 서준이는 도윤이보다 몇 초 더 빠른가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":18,"concept":"M4-2-u3-C7","difficulty":3,"kind":"mc","stem":"50 m 달리기 연습에서 서준이는 10.5초, 도윤이는 11.2초를 기록했어요. 서준이는 도윤이보다 몇 초 더 빠른가요?","options":[{"t":"0.7초","correct":true},{"t":"1.3초","mis":"M4-2-u3-X13"},{"t":"1.7초","mis":"M4-2-u3-X14"},{"t":"21.7초","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 2에서 5를 뺄 수 없어 일의 자리에서 받아내림해요 — 12 − 5 = 7.","11.2 − 10.5 = 0.7초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#19','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C8',3,'error','auto','6.9 − 0.13 = 0.56 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X12','M4-2-u3-X15','M4-2-u3-X14']::text[],false,'{"seq":19,"concept":"M4-2-u3-C8","difficulty":3,"kind":"error","stem":"6.9 − 0.13 = 0.56 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","correct":true,"mis_target":"M4-2-u3-X12"},{"t":"빼지는 수의 빈 자리를 0으로 보지 않고 빼는 수의 숫자를 그대로 내려 썼어요","mis":"M4-2-u3-X15"},{"t":"받아내림을 하고도 윗자리에서 1을 빼지 않았어요","mis":"M4-2-u3-X14"}],"explanation":["틀린 답 0.56: 소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요.","소수점을 맞추어 같은 자리끼리 빼고, 받아내림을 생각해요.","바르게 계산하면 6.9 − 0.13 = 6.77이에요."],"asset":{"type":"expr_grid","rows":[["","","6",".","9"],["−","0",".","1","3"],["","0",".","5","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#20','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C9',3,'mc','auto','개인 혼영 기록표예요. 누가 몇 초 더 빠른가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X12']::text[],false,'{"seq":20,"concept":"M4-2-u3-C9","difficulty":3,"kind":"mc","stem":"개인 혼영 기록표예요. 누가 몇 초 더 빠른가요?","options":[{"t":"건우가 1.2초","correct":true},{"t":"은비가 1.2초","mis":"M4-2-u3-X17"},{"t":"건우가 0.12초","mis":"M4-2-u3-X12"}],"explanation":["은비 176.89초, 건우 175.69초예요.","기록이 작을수록 빨라요.","176.89 − 175.69 = 1.2 — 건우가 1.2초 더 빨라요."],"asset":{"type":"expr_grid","rows":[["이름","접영","배영","평영","자유형"],["은비","42.71","44.99","48.27","40.92"],["건우","41.45","45.28","47.73","41.23"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#21','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C4',3,'mc','auto','질문 — 0.23과 0.123 중에서 더 큰 수는 어느 것인가요?',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":21,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"질문 — 0.23과 0.123 중에서 더 큰 수는 어느 것인가요?","options":[{"t":"0.23","correct":true},{"t":"0.123","mis":"M4-2-u3-X07"},{"t":"두 수는 크기가 같아요","mis":"M4-2-u3-X18"}],"explanation":["0.123이 0.23보다 길지만 소수 셋째 자리만 더 있을 뿐이에요.","소수 첫째 자리를 견주면 2 > 1이에요.","0.23이 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#22','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C8',3,'sa','auto','0.95 − 0.43은 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M4-2-u3-C8","difficulty":3,"kind":"sa","stem":"0.95 − 0.43은 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["0.95는 0.01이 95개, 0.43은 0.01이 43개예요.","95 − 43 = 52예요.","0.95 − 0.43 = 0.52 — 0.01이 52개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#23','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C4',4,'essay','teacher','질문 — 「소수는 수의 길이가 길어도 더 큰 수가 아니에요?」 0.23과 0.123을 예로 들어 답해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u3-C4","difficulty":4,"kind":"essay","stem":"질문 — 「소수는 수의 길이가 길어도 더 큰 수가 아니에요?」 0.23과 0.123을 예로 들어 답해 보세요.","answer_guide":{"answer":"소수는 소수점 아래 숫자가 많다고 해서 큰 수가 아니다. 0.123이 0.23보다 길지만 소수 셋째 자리가 더 있을 뿐이다. 소수점을 기준으로 자리를 맞추어 큰 자리부터 비교하면 소수 첫째 자리가 2 > 1이므로 0.23이 더 크다.","scoring_points":["수의 길이로 비교하면 안 된다고 썼는가","자리를 맞추어 큰 자리부터 비교했는가","0.23 > 0.123을 썼는가"]},"explanation":["자연수는 길이가 길수록 크지만 소수는 아니에요.","0.23 = 0.230, 0.123 — 소수 첫째 자리 2 > 1이에요.","0.23 > 0.123이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#24','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C9',4,'essay','teacher','두 팀의 혼계영 200 m 기록을 각각 구하고 어느 팀이 몇 초 더 빠른지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u3-C9","difficulty":4,"kind":"essay","stem":"두 팀의 혼계영 200 m 기록을 각각 구하고 어느 팀이 몇 초 더 빠른지 설명해 보세요.","answer_guide":{"answer":"돌고래 팀: 39.28 + 42.43 + 35.7 + 31.48 = 148.89(초). 아기 상어 팀: 40.24 + 42.53 + 35.26 + 32.18 = 150.21(초). 148.89 < 150.21이므로 돌고래 팀이 150.21 − 148.89 = 1.32(초) 더 빠르다.","scoring_points":["돌고래 팀 148.89초를 구했는가","아기 상어 팀 150.21초를 구했는가","돌고래 팀이 1.32초 더 빠르다고 썼는가"]},"explanation":["35.7은 35.70으로 보고 소수점을 맞추어 더해요.","148.89 < 150.21이에요.","150.21 − 148.89 = 1.32예요."],"asset":{"type":"expr_grid","rows":[["팀","배영","평영","접영","자유형"],["돌고래","39.28","42.43","35.7","31.48"],["아기 상어","40.24","42.53","35.26","32.18"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_c#25','math',4,2,'u3','','tb_g4_2_math_u3_review_c','unit_review','M4-2-u3-C8',4,'essay','teacher','마무리 ⑥ — 8.1□ − □.52 = 7.□9에서 □에 알맞은 숫자를 각각 구하는 과정을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u3-C8","difficulty":4,"kind":"essay","stem":"마무리 ⑥ — 8.1□ − □.52 = 7.□9에서 □에 알맞은 숫자를 각각 구하는 과정을 설명해 보세요.","answer_guide":{"answer":"소수 둘째 자리에서 2를 뺐는데 9가 나왔으므로 소수 첫째 자리에서 10을 받아내렸다. 10 + □ − 2 = 9이므로 □ = 1이다. 소수 첫째 자리는 1을 받아내려 0이 되었으므로 일의 자리에서 10을 받아내려 10 − 5 = 5, □ = 5이다. 일의 자리는 받아내림하여 7이 되었으므로 7 − □ = 7, □ = 0이다. 8.11 − 0.52 = 7.59이다.","scoring_points":["소수 둘째 자리 □ = 1을 받아내림으로 구했는가","소수 첫째 자리 □ = 5를 구했는가","일의 자리 □ = 0을 구하고 8.11 − 0.52 = 7.59로 확인했는가"]},"explanation":["2를 뺐는데 9가 나오면 받아내림을 한 거예요.","10 − 5 = 5, 7 − 0 = 7이에요.","8.11 − 0.52 = 7.59예요."],"asset":{"type":"expr_grid","rows":[["","8",".","1","□"],["−","□",".","5","2"],["","7",".","□","9"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#1','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C6',1,'blank','auto','정리 — 1.53 + 2.41 = 3.□4 에서 □에 알맞은 숫자는 무엇인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X20']::text[],true,'{"seq":1,"concept":"M4-2-u3-C6","difficulty":1,"kind":"blank","stem":"정리 — 1.53 + 2.41 = 3.□4 에서 □에 알맞은 숫자는 무엇인가요?","options":[{"t":"9","correct":true},{"t":"8","mis":"M4-2-u3-X11"},{"t":"7","mis":"M4-2-u3-X20"}],"explanation":["정리 — 소수 두 자리 수·세 자리 수, 소수 사이의 관계, 크기 비교, 덧셈과 뺄셈을 되짚어요.","소수 첫째 자리: 5 + 4 = 9 — 1.53 + 2.41 = 3.94예요.","□에 알맞은 것은 9예요."],"variant_rule":{"alt":[{"stem":"정리 — 6.98 − 1.23 = 5.□5 에서 □에 알맞은 숫자는 무엇인가요?","options":[{"t":"7","correct":true},{"t":"8","mis":"M4-2-u3-X16"},{"t":"6","mis":"M4-2-u3-X20"}],"explanation":["정리 — 소수 두 자리 수·세 자리 수, 소수 사이의 관계, 크기 비교, 덧셈과 뺄셈을 되짚어요.","소수 첫째 자리: 9 − 2 = 7 — 6.98 − 1.23 = 5.75예요.","□에 알맞은 것은 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#2','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C2',1,'mc','auto','1이 2개, 0.1이 8개, 0.01이 5개, 0.001이 3개인 수는 얼마인가요?',ARRAY['M4-2-u3-X03','M4-2-u3-X01']::text[],false,'{"seq":2,"concept":"M4-2-u3-C2","difficulty":1,"kind":"mc","stem":"1이 2개, 0.1이 8개, 0.01이 5개, 0.001이 3개인 수는 얼마인가요?","options":[{"t":"2.853","correct":true},{"t":"2.358","mis":"M4-2-u3-X03"},{"t":"28.53","mis":"M4-2-u3-X03"},{"t":"2853","mis":"M4-2-u3-X01"}],"explanation":["자리마다 숫자를 차례로 써요 — 일의 자리 2, 소수 첫째 자리 8, 소수 둘째 자리 5, 소수 셋째 자리 3.","2 + 0.8 + 0.05 + 0.003 = 2.853.","1이 2개, 0.1이 8개, 0.01이 5개, 0.001이 3개인 수는 2.853이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#3','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C3',1,'mc','auto','32.87의 □은 3.287이에요. □에 알맞은 것은 무엇인가요?',ARRAY['M4-2-u3-X05','M4-2-u3-X06']::text[],false,'{"seq":3,"concept":"M4-2-u3-C3","difficulty":1,"kind":"mc","stem":"32.87의 □은 3.287이에요. □에 알맞은 것은 무엇인가요?","options":[{"t":"⟨1/10⟩","correct":true},{"t":"10배","mis":"M4-2-u3-X05"},{"t":"⟨1/100⟩","mis":"M4-2-u3-X06"}],"explanation":["32.87 → 3.287: 숫자가 오른쪽으로 한 자리 옮겨 갔어요.","오른쪽으로 한 자리 = ⟨1/10⟩이에요.","32.87의 ⟨1/10⟩은 3.287이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#4','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C8',1,'mc','auto','8.31 − 5.94를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":4,"concept":"M4-2-u3-C8","difficulty":1,"kind":"mc","stem":"8.31 − 5.94를 계산한 값은 얼마인가요?","options":[{"t":"2.37","correct":true},{"t":"3.63","mis":"M4-2-u3-X13"},{"t":"3.47","mis":"M4-2-u3-X14"},{"t":"14.25","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 1에서 4를 뺄 수 없어 소수 첫째 자리에서 받아내림해요 — 11 − 4 = 7.","8.31 − 5.94 = 2.37이에요."],"asset":{"type":"expr_grid","rows":[["","8",".","3","1"],["−","5",".","9","4"],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#5','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C4',1,'mc','auto','정리 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 7.84 ○ 7.836',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":5,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"정리 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 7.84 ○ 7.836","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X07"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 둘째 자리 숫자를 견주면 4 > 3이에요.","7.84 > 7.836."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#6','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C4',1,'mc','auto','5장의 카드 1, 5, 7, 9, 「.」을 한 번씩만 사용하여 만든 소수 세 자리 수 중에서 가장 큰 수는 얼마인가요?',ARRAY['M4-2-u3-X17','M4-2-u3-X08','M4-2-u3-X03']::text[],false,'{"seq":6,"concept":"M4-2-u3-C4","difficulty":1,"kind":"mc","stem":"5장의 카드 1, 5, 7, 9, 「.」을 한 번씩만 사용하여 만든 소수 세 자리 수 중에서 가장 큰 수는 얼마인가요?","options":[{"t":"9.751","correct":true},{"t":"1.579","mis":"M4-2-u3-X17"},{"t":"9.715","mis":"M4-2-u3-X08"},{"t":"97.51","mis":"M4-2-u3-X03"}],"explanation":["가장 큰 수를 만들려면 큰 숫자부터 큰 자리에 놓아요.","일의 자리 9, 소수 첫째 7, 둘째 5, 셋째 1이에요.","가장 큰 수는 9.751이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#7','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C8',1,'mc','auto','마무리 ⑥에서 완성한 뺄셈식 8.11 − 0.52의 계산 결과는 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":7,"concept":"M4-2-u3-C8","difficulty":1,"kind":"mc","stem":"마무리 ⑥에서 완성한 뺄셈식 8.11 − 0.52의 계산 결과는 얼마인가요?","options":[{"t":"7.59","correct":true},{"t":"8.41","mis":"M4-2-u3-X13"},{"t":"8.69","mis":"M4-2-u3-X14"},{"t":"8.63","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 1에서 2를 뺄 수 없어 소수 첫째 자리에서 받아내림해요 — 11 − 2 = 9.","8.11 − 0.52 = 7.59예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#8','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C7',1,'mc','auto','이 단원 학습을 마치고 — 원숭이가 지난달은 16.3 kg이었고 이번 달은 17.2 kg이에요. 몸무게가 몇 kg 늘었나요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":8,"concept":"M4-2-u3-C7","difficulty":1,"kind":"mc","stem":"이 단원 학습을 마치고 — 원숭이가 지난달은 16.3 kg이었고 이번 달은 17.2 kg이에요. 몸무게가 몇 kg 늘었나요?","options":[{"t":"0.9 kg","correct":true},{"t":"1.1 kg","mis":"M4-2-u3-X13"},{"t":"1.9 kg","mis":"M4-2-u3-X14"},{"t":"33.5 kg","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 2에서 3을 뺄 수 없어 일의 자리에서 받아내림해요 — 12 − 3 = 9.","17.2 − 16.3 = 0.9 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#9','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C2',2,'mc','auto','6.703을 바르게 읽은 것은 어느 것인가요?',ARRAY['M4-2-u3-X02','M4-2-u3-X03']::text[],false,'{"seq":9,"concept":"M4-2-u3-C2","difficulty":2,"kind":"mc","stem":"6.703을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"육 점 칠영삼","correct":true},{"t":"육 점 칠백삼","mis":"M4-2-u3-X02"},{"t":"육 점 칠삼","mis":"M4-2-u3-X02"},{"t":"육 점 영칠영삼","mis":"M4-2-u3-X03"}],"explanation":["소수점 왼쪽은 자연수처럼 읽어요 — 육.","소수점 오른쪽은 숫자를 하나씩 차례로 읽어요(0은 「영」).","6.703 → 육 점 칠영삼."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#10','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C1',2,'mc','auto','자로 잰 건전지의 길이는 5 cm예요. 건전지의 길이는 몇 m인가요?',ARRAY['M4-2-u3-X04']::text[],false,'{"seq":10,"concept":"M4-2-u3-C1","difficulty":2,"kind":"mc","stem":"자로 잰 건전지의 길이는 5 cm예요. 건전지의 길이는 몇 m인가요?","options":[{"t":"0.05 m","correct":true},{"t":"0.5 m","mis":"M4-2-u3-X04"},{"t":"0.005 m","mis":"M4-2-u3-X04"},{"t":"5 m","mis":"M4-2-u3-X04"}],"explanation":["1 m = 100 cm이므로 1 cm = 0.01 m예요.","5 cm는 0.01 m가 5개예요.","5 cm = 0.05 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#11','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C3',2,'mc','auto','1.239 kg의 100배는 얼마인가요?',ARRAY['M4-2-u3-X06','M4-2-u3-X09']::text[],false,'{"seq":11,"concept":"M4-2-u3-C3","difficulty":2,"kind":"mc","stem":"1.239 kg의 100배는 얼마인가요?","options":[{"t":"123.9 kg","correct":true},{"t":"1239 kg","mis":"M4-2-u3-X06"},{"t":"12.39 kg","mis":"M4-2-u3-X06"},{"t":"1.23900 kg","mis":"M4-2-u3-X09"}],"explanation":["100배를 하면 소수점을 기준으로 숫자가 왼쪽으로 두 자리씩 옮겨 가요.","1.239의 숫자를 왼쪽으로 두 자리 옮겨요.","1.239 kg의 100배는 123.9 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#12','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C4',2,'mc','auto','두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 1.807 ○ 1.84',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":12,"concept":"M4-2-u3-C4","difficulty":2,"kind":"mc","stem":"두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 1.807 ○ 1.84","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u3-X07"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 둘째 자리 숫자를 견주면 0 < 4예요.","1.807 < 1.84."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#13','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C5',2,'mc','auto','2.4 + 7.9를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X11','M4-2-u3-X10','M4-2-u3-X16']::text[],false,'{"seq":13,"concept":"M4-2-u3-C5","difficulty":2,"kind":"mc","stem":"2.4 + 7.9를 계산한 값은 얼마인가요?","options":[{"t":"10.3","correct":true},{"t":"9.3","mis":"M4-2-u3-X11"},{"t":"9.13","mis":"M4-2-u3-X10"},{"t":"5.5","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 첫째 자리: 4 + 9 = 13 — 3을 쓰고 일의 자리로 1을 받아올려요.","2.4 + 7.9 = 10.3이에요."],"asset":{"type":"expr_grid","rows":[["","","2",".","4"],["+","","7",".","9"],["","?","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#14','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C6',2,'mc','auto','5.13 + 1.24를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":14,"concept":"M4-2-u3-C6","difficulty":2,"kind":"mc","stem":"5.13 + 1.24를 계산한 값은 얼마인가요?","options":[{"t":"6.37","correct":true},{"t":"3.89","mis":"M4-2-u3-X16"},{"t":"637","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.01의 개수로 보면 513 + 124 = 637이에요.","5.13 + 1.24 = 6.37이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#15','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C7',2,'mc','auto','4.7 − 0.5를 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":15,"concept":"M4-2-u3-C7","difficulty":2,"kind":"mc","stem":"4.7 − 0.5를 계산한 값은 얼마인가요?","options":[{"t":"4.2","correct":true},{"t":"5.2","mis":"M4-2-u3-X16"},{"t":"42","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아내림이 없어요 — 0.1의 개수로 보면 47 − 5 = 42예요.","4.7 − 0.5 = 4.2예요."],"asset":{"type":"expr_grid","rows":[["","4",".","7"],["−","0",".","5"],["","?",".","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#16','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C8',2,'mc','auto','8.6 − 5.31을 계산한 값은 얼마인가요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":16,"concept":"M4-2-u3-C8","difficulty":2,"kind":"mc","stem":"8.6 − 5.31을 계산한 값은 얼마인가요?","options":[{"t":"3.29","correct":true},{"t":"3.31","mis":"M4-2-u3-X13"},{"t":"3.39","mis":"M4-2-u3-X14"},{"t":"13.91","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 0에서 1을 뺄 수 없어 소수 첫째 자리에서 받아내림해요 — 10 − 1 = 9.","8.6 − 5.31 = 3.29예요."],"asset":{"type":"expr_grid","rows":[["","8",".","6",""],["−","5",".","3","1"],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#17','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C6',3,'mc','auto','신문지의 무게는 2.16 kg이고, 종이 상자의 무게는 4.82 kg이에요. 모은 재활용 종이의 무게는 모두 몇 kg인가요?',ARRAY['M4-2-u3-X16','M4-2-u3-X01']::text[],false,'{"seq":17,"concept":"M4-2-u3-C6","difficulty":3,"kind":"mc","stem":"신문지의 무게는 2.16 kg이고, 종이 상자의 무게는 4.82 kg이에요. 모은 재활용 종이의 무게는 모두 몇 kg인가요?","options":[{"t":"6.98 kg","correct":true},{"t":"2.66 kg","mis":"M4-2-u3-X16"},{"t":"698 kg","mis":"M4-2-u3-X01"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","받아올림이 없어요 — 0.01의 개수로 보면 216 + 482 = 698이에요.","2.16 + 4.82 = 6.98 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#18','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C8',3,'mc','auto','리본을 선물 포장하는 데에 1.95 m, 꽃 만드는 데에 2.63 m 사용했어요. 꽃 만드는 데에 몇 m 더 많이 사용했나요?',ARRAY['M4-2-u3-X13','M4-2-u3-X14','M4-2-u3-X16']::text[],false,'{"seq":18,"concept":"M4-2-u3-C8","difficulty":3,"kind":"mc","stem":"리본을 선물 포장하는 데에 1.95 m, 꽃 만드는 데에 2.63 m 사용했어요. 꽃 만드는 데에 몇 m 더 많이 사용했나요?","options":[{"t":"0.68 m","correct":true},{"t":"1.32 m","mis":"M4-2-u3-X13"},{"t":"1.78 m","mis":"M4-2-u3-X14"},{"t":"4.58 m","mis":"M4-2-u3-X16"}],"explanation":["소수점을 맞추어 같은 자리끼리 세로로 써요.","소수 둘째 자리: 3에서 5를 뺄 수 없어 소수 첫째 자리에서 받아내림해요 — 13 − 5 = 8.","2.63 − 1.95 = 0.68 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#19','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C8',3,'error','auto','8.1 − 0.52 = 7.62 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u3-X15','M4-2-u3-X12','M4-2-u3-X14']::text[],false,'{"seq":19,"concept":"M4-2-u3-C8","difficulty":3,"kind":"error","stem":"8.1 − 0.52 = 7.62 — 잘못 계산했어요. 잘못 계산한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"빼지는 수의 빈 자리를 0으로 보지 않고 빼는 수의 숫자를 그대로 내려 썼어요","correct":true,"mis_target":"M4-2-u3-X15"},{"t":"소수점의 위치를 맞추지 않고 오른쪽 끝을 맞추어 계산했어요","mis":"M4-2-u3-X12"},{"t":"받아내림을 하고도 윗자리에서 1을 빼지 않았어요","mis":"M4-2-u3-X14"}],"explanation":["틀린 답 7.62: 빼지는 수의 빈 자리를 0으로 보지 않고 빼는 수의 숫자를 그대로 내려 썼어요.","소수점을 맞추어 같은 자리끼리 빼고, 받아내림을 생각해요.","바르게 계산하면 8.1 − 0.52 = 7.58이에요."],"asset":{"type":"expr_grid","rows":[["","8",".","1",""],["−","0",".","5","2"],["","7",".","6","2"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#20','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C10',3,'mc','auto','선수들의 영법별 기록표예요. 한 선수가 한 영법만 헤엄칠 때 네 선수의 기록의 합이 가장 작은 명단(배영, 평영, 접영, 자유형 순)은 어느 것인가요?',ARRAY['M4-2-u3-X19','M4-2-u3-X17','M4-2-u3-X20']::text[],false,'{"seq":20,"concept":"M4-2-u3-C10","difficulty":3,"kind":"mc","stem":"선수들의 영법별 기록표예요. 한 선수가 한 영법만 헤엄칠 때 네 선수의 기록의 합이 가장 작은 명단(배영, 평영, 접영, 자유형 순)은 어느 것인가요?","options":[{"t":"서준, 채원, 건우, 지유","correct":true},{"t":"채원, 채원, 건우, 지유","mis":"M4-2-u3-X19"},{"t":"채원, 서준, 건우, 지유","mis":"M4-2-u3-X17"},{"t":"지유, 채원, 서준, 건우","mis":"M4-2-u3-X20"}],"explanation":["영법별로 가장 빠른 선수 — 배영·평영 채원, 접영 건우, 자유형 지유예요.","채원이가 겹치므로 39.32 + 41.33 = 80.65와 38.96 + 41.93 = 80.89를 견주어요.","서준, 채원, 건우, 지유 — 147.13초로 가장 빨라요."],"asset":{"type":"expr_grid","rows":[["선수","배영","평영","접영","자유형"],["서준","39.32","41.93","35.76","32.52"],["지유","39.56","42.19","35.01","31.86"],["채원","38.96","41.33","36.18","33.23"],["건우","40.15","43.03","34.62","32.35"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#21','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C4',3,'mc','auto','지도서 평가 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 3.97 ○ 3.962',ARRAY['M4-2-u3-X07','M4-2-u3-X18']::text[],false,'{"seq":21,"concept":"M4-2-u3-C4","difficulty":3,"kind":"mc","stem":"지도서 평가 — 두 소수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요. 3.97 ○ 3.962","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u3-X07"},{"t":"=","mis":"M4-2-u3-X18"}],"explanation":["소수점을 기준으로 자리를 맞추어 큰 자리부터 차례로 견주어요.","소수 둘째 자리 숫자를 견주면 7 > 6이에요.","3.97 > 3.962."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#22','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C6',3,'sa','auto','1.59 + 2.89는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M4-2-u3-C6","difficulty":3,"kind":"sa","stem":"1.59 + 2.89는 0.01이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["448"],"explanation":["1.59는 0.01이 159개, 2.89는 0.01이 289개예요.","159 + 289 = 448이에요.","1.59 + 2.89 = 4.48 — 0.01이 448개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#23','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C5',4,'essay','teacher','지도서 오류 2 — 한 친구가 0.9 + 0.7을 세로로 계산하여 0.16이라고 했어요. 무엇을 잘못했는지 쓰고, 모눈종이나 수직선을 이용하여 바르게 계산하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u3-C5","difficulty":4,"kind":"essay","stem":"지도서 오류 2 — 한 친구가 0.9 + 0.7을 세로로 계산하여 0.16이라고 했어요. 무엇을 잘못했는지 쓰고, 모눈종이나 수직선을 이용하여 바르게 계산하는 방법을 설명해 보세요.","answer_guide":{"answer":"소수 첫째 자리 9 + 7 = 16을 그 자리에 그대로 쓰고 소수점을 왼쪽에 찍었다. 0.9는 0.1이 9개, 0.7은 0.1이 7개이므로 0.1이 16개이고, 0.1이 10개면 1이므로 1.6이다. 수직선에서 0.9에서 0.7만큼 더 가면 1을 지나 1.6이 된다. 세로 계산에서는 16에서 6을 쓰고 일의 자리로 1을 받아올린다.","scoring_points":["합 16을 그 자리에 그대로 썼다고 오류를 찾았는가","0.1이 16개 = 1.6으로 설명했는가","받아올림으로 바르게 계산했는가"]},"explanation":["0.9 + 0.7은 1보다 커야 해요(0.16은 너무 작아요).","0.1이 16개 = 1.6이에요.","0.9 + 0.7 = 1.6이에요."],"asset":{"type":"expr_grid","rows":[["","0",".","9",""],["+","0",".","7",""],["","0",".","1","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#24','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C8',4,'essay','teacher','서준이는 7.1 − 2.99를 7.1에서 3을 뺀 다음 0.01을 더해서 4.11로 구했어요. 이 방법이 옳은지 쓰고, 7.1 − 2.99를 세로로 계산한 결과와 견주어 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M4-2-u3-C8","difficulty":4,"kind":"essay","stem":"서준이는 7.1 − 2.99를 7.1에서 3을 뺀 다음 0.01을 더해서 4.11로 구했어요. 이 방법이 옳은지 쓰고, 7.1 − 2.99를 세로로 계산한 결과와 견주어 확인해 보세요.","answer_guide":{"answer":"옳다. 2.99는 3보다 0.01 작으므로 3을 빼면 0.01을 더 뺀 것이어서 다시 0.01을 더한다(7.1 − 3 = 4.1, 4.1 + 0.01 = 4.11). 세로로 계산하면 7.1을 7.10으로 보고 소수 둘째 자리 10 − 9 = 1, 소수 첫째 자리 10 − 9 = 1, 일의 자리 6 − 2 = 4이므로 4.11로 결과가 같다.","scoring_points":["서준이의 방법이 옳다고 판단했는가","0.01을 더하는 까닭을 썼는가","세로 계산 4.11과 견주어 확인했는가"]},"explanation":["2.99 = 3 − 0.01이에요.","7.1 − 3 = 4.1, 4.1 + 0.01 = 4.11이에요.","세로로 계산해도 7.1 − 2.99 = 4.11이에요."],"asset":{"type":"expr_grid","rows":[["","7",".","1",""],["−","2",".","9","9"],["","?",".","?","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u3_review_d#25','math',4,2,'u3','','tb_g4_2_math_u3_review_d','unit_review','M4-2-u3-C6',4,'essay','teacher','이 단원 학습을 마치고 — 다람쥐의 몸무게는 0.63 kg에서 0.02 kg만큼 늘었고, 곰의 몸무게는 135.12 kg에서 130.32 kg이 되었어요. 두 동물의 이번 달 몸무게 변화를 각각 식으로 구해 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u3-C6","difficulty":4,"kind":"essay","stem":"이 단원 학습을 마치고 — 다람쥐의 몸무게는 0.63 kg에서 0.02 kg만큼 늘었고, 곰의 몸무게는 135.12 kg에서 130.32 kg이 되었어요. 두 동물의 이번 달 몸무게 변화를 각각 식으로 구해 설명해 보세요.","answer_guide":{"answer":"다람쥐: 0.63 + 0.02 = 0.65이므로 이번 달 몸무게는 0.65 kg이다. 곰: 135.12 − 130.32 = 4.8이므로 지난달보다 4.8 kg 줄었다(소수점을 맞추고 자연수의 뺄셈과 같은 방법으로 받아내림하여 계산한다).","scoring_points":["다람쥐 0.65 kg을 덧셈으로 구했는가","곰이 4.8 kg 줄었음을 뺄셈으로 구했는가","소수점을 맞추어 계산한다고 썼는가"]},"explanation":["늘었으면 덧셈, 줄어든 만큼은 뺄셈이에요.","0.63 + 0.02 = 0.65예요.","135.12 − 130.32 = 4.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
